import {
  Injectable,
  Inject,
  NotFoundException,
  BadRequestException,
  ConflictException,
  Logger,
} from '@nestjs/common';
import { eq, sql } from 'drizzle-orm';
import { DRIZZLE } from '../drizzle/drizzle.module';
import type { DrizzleDB } from '../drizzle/drizzle.module';
import {
  accountEvents,
  accounts as coreAccounts,
} from '../drizzle/modbm-core-schema';
import { emitEvent } from '../common/emit-event';
import { AggregateType } from '../common/event-types';
import {
  ACCOUNT_TRANSITIONS,
  ACCOUNT_STATE,
  AccountState,
  getValidStates,
} from '@modbm/shared';

import { calculateAuditTrail, AuditMode } from '../common/audit';
import { CreateAccountDto, UpdateAccountDto } from './dto';

const isUuid = (id: string) =>
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id);

import { AppConfigService } from '../settings/app-config.service';

@Injectable()
export class AccountsWriteService {
  constructor(
    @Inject(DRIZZLE) private db: DrizzleDB,
    private readonly appConfig: AppConfigService,
  ) {}

  // Phase 8: [x] Implement strict server-side diffing in `AccountsWriteService`
  private readonly logger = new Logger(AccountsWriteService.name);

  async create(dto: CreateAccountDto, actor: string) {
    // 1. Check if account number exists in core
    const coreExisting = await this.db
      .select({ id: coreAccounts.accountId })
      .from(coreAccounts)
      .where(eq(coreAccounts.accountNumber, dto.accountNumber))
      .limit(1);

    if (coreExisting.length > 0) {
      throw new BadRequestException(
        `Account number '${dto.accountNumber}' already exists in application data`,
      );
    }

    // Legacy ABM accounts are now in core — the check above covers both.

    const allowedKeys: (keyof CreateAccountDto)[] = [
      'accountNumber',
      'name',
      'address1Line1',
      'address1Line2',
      'address1City',
      'address1StateOrProvince',
      'address1PostalCode',
      'address1Country',
      'telephone1',
      'fax',
      'emailAddress1',
      'primaryContactName',
      'primaryContactEmail',
      'primaryContactPhone',
      'accountGroupId',
      'taxCategoryId',
      'currencyCode',

      'notes',
    ];

    const sanitizedDto: any = {};
    for (const key of allowedKeys) {
      if (key in dto && dto[key] !== undefined) {
        sanitizedDto[key] = dto[key];
      }
    }

    let result;
    try {
      result = await this.db.transaction(async (tx: DrizzleDB) => {
        const [account] = await tx
          .insert(coreAccounts)
          .values({
            ...sanitizedDto,
            currencyCode:
              sanitizedDto.currencyCode || this.appConfig.homeCurrency(),
            createdBy: actor,
          })
          .returning();

        await tx.insert(accountEvents).values({
          accountId: account.accountId,
          eventType: 'created',
          payload: dto,
          actor,
        });

        return account;
      });
    } catch (e: any) {
      const pgCode = e.code || e.cause?.code;
      if (pgCode === '23505') {
        throw new ConflictException(
          `Account number '${dto.accountNumber}' already exists`,
        );
      }
      throw e;
    }

    this.logger.log(
      `Account created: ${dto.accountNumber} (ID: ${result.accountId}) by ${actor}`,
    );
    return result;
  }

  async update(id: string, dto: UpdateAccountDto, actor: string) {
    const existing = await this.db
      .select()
      .from(coreAccounts)
      .where(
        isUuid(id)
          ? eq(coreAccounts.accountId, id)
          : eq(coreAccounts.sourceId, id),
      )
      .limit(1);

    if (existing.length === 0) {
      throw new NotFoundException(`Account '${id}' not found`);
    }

    const allowedKeys: (keyof UpdateAccountDto)[] = [
      'name',
      'address1Line1',
      'address1Line2',
      'address1City',
      'address1StateOrProvince',
      'address1PostalCode',
      'address1Country',
      'telephone1',
      'fax',
      'emailAddress1',
      'primaryContactName',
      'primaryContactEmail',
      'primaryContactPhone',
      'accountGroupId',
      'stateCode',
      'taxCategoryId',
      'currencyCode',

      'notes',
    ];

    const sanitizedDto: any = {};
    for (const key of allowedKeys) {
      if (key in dto && dto[key] !== undefined) {
        sanitizedDto[key] = dto[key];
      }
    }

    const result = await this.db.transaction(async (tx: DrizzleDB) => {
      const audit = calculateAuditTrail(
        sanitizedDto,
        existing[0],
        AuditMode.DIFF,
      );

      // Perform the update
      const [updated] = await tx
        .update(coreAccounts)
        .set({
          ...audit.changes,
          modifiedOn: new Date(),
        })
        .where(eq(coreAccounts.accountId, id))
        .returning();

      // Record audit event if something actually changed
      if (audit.hasChanges) {
        const changedKeys = Object.keys(audit.changes);
        const isStatusOnly =
          changedKeys.length === 1 && changedKeys[0] === 'stateCode';

        await tx.insert(accountEvents).values({
          accountId: id,
          eventType: isStatusOnly ? 'status_changed' : 'updated',
          payload: isStatusOnly
            ? {
                from: audit.previousValues.stateCode,
                to: audit.changes.stateCode,
              }
            : {
                changes: audit.changes,
                previousValues: audit.previousValues,
              },
          actor,
        });
      }

      return updated;
    });

    this.logger.log(`Account updated: ${id} by ${actor}`);
    return result;
  }

  /**
   * Archive an account.
   */
  async archive(id: string, actor: string) {
    return await this.changeAccountState(id, ACCOUNT_STATE.ARCHIVED, actor);
  }

  /**
   * Unarchive an account.
   */
  async unarchive(id: string, actor: string) {
    if (!isUuid(id)) {
      throw new BadRequestException(`Account '${id}' is a legacy ABM account.`);
    }

    const existing = await this.db
      .select()
      .from(coreAccounts)
      .where(eq(coreAccounts.accountId, id))
      .limit(1);

    if (existing.length === 0) {
      throw new NotFoundException(`Account '${id}' not found`);
    }

    if (existing[0].stateCode !== ACCOUNT_STATE.ARCHIVED) {
      throw new BadRequestException(`Account '${id}' is not archived`);
    }

    const lastEvent = await this.db
      .select()
      .from(accountEvents)
      .where(
        sql`${accountEvents.accountId} = ${id} AND ${accountEvents.eventType} = 'archived'`,
      )
      .orderBy(sql`${accountEvents.createdOn} DESC`)
      .limit(1);

    const previousState =
      ((lastEvent[0]?.payload as Record<string, unknown>)?.from as string) ||
      ACCOUNT_STATE.ACTIVE;

    return await this.changeAccountState(
      id,
      previousState as AccountState,
      actor,
    );
  }

  /**
   * Centralised state transition logic for accounts.
   * Validates against the shared transition map and records audit events.
   */
  async changeAccountState(
    accountId: string,
    newState: AccountState,
    actor: string,
    tx?: DrizzleDB,
  ) {
    const db = tx || this.db;

    const existing = await db
      .select()
      .from(coreAccounts)
      .where(eq(coreAccounts.accountId, accountId))
      .limit(1);

    if (existing.length === 0) {
      throw new NotFoundException(`Account '${accountId}' not found`);
    }

    const currentState = existing[0].stateCode as AccountState;

    if (currentState === newState) {
      return existing[0];
    }

    // Validation
    const allowed = ACCOUNT_TRANSITIONS[currentState] || [];
    if (!allowed.includes(newState)) {
      throw new BadRequestException(
        `Invalid account state transition: '${currentState}' -> '${newState}'. Valid next states: ${allowed.join(', ') || 'None'}`,
      );
    }

    const [updated] = await db
      .update(coreAccounts)
      .set({ stateCode: newState as any, modifiedOn: new Date() })
      .where(eq(coreAccounts.accountId, accountId))
      .returning();

    (await tx?.insert(accountEvents).values({
      accountId,
      eventType:
        newState === ACCOUNT_STATE.ARCHIVED ? 'archived' : 'status_changed',
      payload: {
        from: currentState,
        to: newState,
      },
      actor,
    })) ||
      (await this.db.insert(accountEvents).values({
        accountId,
        eventType:
          newState === ACCOUNT_STATE.ARCHIVED ? 'archived' : 'status_changed',
        payload: {
          from: currentState,
          to: newState,
        },
        actor,
      }));

    return updated;
  }
}

import {
  Injectable,
  Inject,
  NotFoundException,
  BadRequestException,
  Logger,
} from '@nestjs/common';
import { DRIZZLE } from '../drizzle/drizzle.module';
import type { DrizzleDB } from '../drizzle/drizzle.module';
import {
  goodsReceived,
  goodsReceivedLines,
  suppliers,
  supplierGroups,
  locations,
  products,
  purchaseOrders,
  purchaseOrderLineItems,
  zones,
  bins,
  binContents,
  backorders,
  glJournalEntries,
  glJournalLines,
} from '../drizzle/modbm-core-schema';

import { InventoryService } from '../inventory/inventory.service';
import { emitEvent } from '../common/emit-event';
import { AggregateType, EventType } from '../common/event-types';
import { eq, and, sql, desc, or, ilike } from 'drizzle-orm';
import { randomUUID } from 'crypto';
import { PaginationQuery, parsePagination } from '../common/pagination';
import { evaluatePOLifecycleRules } from '../purchase-orders/purchase-order-lifecycle-rules';
import { AppConfigService } from '../settings/app-config.service';
import { GlService } from '../gl/gl.service';
import { getValuationStrategy } from '../inventory/valuation';
import { getAccountingStrategy } from '../inventory/inventory-accounting';
import {
  RECEIPT_STATE,
  RECEIPT_TRANSITIONS,
  PURCHASE_ORDER_STATE,
  PURCHASE_ORDER_TRANSITIONS,
  BACKORDER_STATE,
  BACKORDER_TRANSITIONS,
  getValidStates,
  PurchaseOrderState,
  BackorderState,
} from '@modbm/shared';

const VALID_GRN_STATES = getValidStates(RECEIPT_TRANSITIONS);

@Injectable()
export class GoodsReceivedService {
  private readonly logger = new Logger(GoodsReceivedService.name);

  constructor(
    @Inject(DRIZZLE) private db: DrizzleDB,
    private readonly inventoryService: InventoryService,
    private readonly appConfig: AppConfigService,
    private readonly glService: GlService,
  ) {}

  /**
   * Create a goods receipt from a packing slip.
   *
   * Records what physically arrived on the dock.
   * - Writes inventory ledger/bin_contents (via InventoryService)
   * - Transitions PO states (if matched)
   *
   * Auto-matches each line to open PO lines for the same supplier + product.
   */
  async create(createDto: any, userId: string) {
    return await this.db.transaction(async (tx) => {
      // 1. Validate vendor and fetch group dimensions
      const [vendor] = await tx
        .select({
          vendorId: suppliers.vendorId,
          name: suppliers.name,
          costCenterId: supplierGroups.defaultCostCenterId,
          activityId: supplierGroups.defaultActivityId,
        })
        .from(suppliers)
        .leftJoin(
          supplierGroups,
          eq(suppliers.supplierGroupId, supplierGroups.supplierGroupId),
        )
        .where(eq(suppliers.vendorId, createDto.vendorId))
        .limit(1);

      if (!vendor) {
        throw new NotFoundException('Supplier not found');
      }

      // 2. Validate location
      const [location] = await tx
        .select({ locationId: locations.locationId })
        .from(locations)
        .where(eq(locations.locationId, createDto.locationId))
        .limit(1);

      if (!location) {
        throw new NotFoundException('Location not found');
      }

      // 3. Create goods received header
      const receiptNumber = `GR-${randomUUID().substring(0, 8).toUpperCase()}`;

      const [receipt] = await tx
        .insert(goodsReceived)
        .values({
          receiptNumber,
          vendorId: createDto.vendorId,
          locationId: createDto.locationId,
          packingSlipNumber: createDto.packingSlipNumber,
          notes: createDto.notes,
          stateCode: RECEIPT_STATE.RECEIVED,
          createdBy: userId,
        })
        .returning();

      // 4. Process lines with auto-matching
      if (createDto.lines && createDto.lines.length > 0) {
        const lineValues = [];

        for (const line of createDto.lines) {
          // Validate product
          const [product] = await tx
            .select({ productId: products.productId })
            .from(products)
            .where(eq(products.productId, line.productId))
            .limit(1);

          if (!product) {
            throw new BadRequestException(
              `Product '${line.productId}' not found`,
            );
          }

          // Auto-match: find open PO lines for this vendor + product
          const openPoLines = await tx
            .select({
              purchaseOrderLineId: purchaseOrderLineItems.purchaseOrderLineId,
              purchaseOrderId: purchaseOrderLineItems.purchaseOrderId,
              quantity: purchaseOrderLineItems.quantity,
              quantityReceived: purchaseOrderLineItems.quantityReceived,
              pricePerUnit: purchaseOrderLineItems.pricePerUnit,
            })
            .from(purchaseOrderLineItems)
            .innerJoin(
              purchaseOrders,
              eq(
                purchaseOrderLineItems.purchaseOrderId,
                purchaseOrders.purchaseOrderId,
              ),
            )
            .where(
              and(
                eq(purchaseOrders.vendorId, createDto.vendorId),
                eq(purchaseOrderLineItems.productId, line.productId),
                eq(purchaseOrders.deliveryLocationId, createDto.locationId),
                sql`${purchaseOrders.stateCode} IN (${PURCHASE_ORDER_STATE.ORDERED}, ${PURCHASE_ORDER_STATE.PARTIALLY_RECEIVED})`,
                sql`CAST(${purchaseOrderLineItems.quantityReceived} AS NUMERIC) < CAST(${purchaseOrderLineItems.quantity} AS NUMERIC)`,
                sql`CAST(${purchaseOrderLineItems.quantity} AS NUMERIC) - CAST(COALESCE(${purchaseOrderLineItems.quantityReceived}, '0') AS NUMERIC) >= CAST(${line.quantityReceived} AS NUMERIC)`,
              ),
            );

          let matchStatus: string;
          let matchedPoLineId: string | null = null;
          let matchedPoId: string | null = null;

          if (openPoLines.length === 1) {
            matchStatus = 'matched';
            matchedPoLineId = openPoLines[0].purchaseOrderLineId;
            matchedPoId = openPoLines[0].purchaseOrderId;
          } else if (openPoLines.length > 1) {
            matchStatus = 'ambiguous';
          } else {
            matchStatus = 'unmatched';
          }

          const unitCost = matchedPoLineId ? openPoLines[0].pricePerUnit : null;

          lineValues.push({
            goodsReceivedId: receipt.goodsReceivedId,
            productId: line.productId,
            quantityReceived: line.quantityReceived.toString(),
            matchStatus,
            putawayStatus:
              matchStatus === 'matched'
                ? 'pending_putaway'
                : 'awaiting_matching',
            purchaseOrderLineId: matchedPoLineId,
            purchaseOrderId: matchedPoId,
            unitCost: unitCost, // Use for valuation, filtered out during insert
          } as any);
        }

        await tx
          .insert(goodsReceivedLines)
          .values(lineValues.map(({ unitCost, ...rest }: any) => rest));

        // --- 5. Inventory Impact: Place items into RECEIVING bin ---
        // Find or create RECEIVING zone/bin
        let receivingZone = await tx
          .select({ zoneId: zones.zoneId })
          .from(zones)
          .where(
            and(
              eq(zones.locationId, createDto.locationId),
              eq(zones.code, 'RECV'),
            ),
          )
          .limit(1)
          .then((res) => res[0]);

        if (!receivingZone) {
          const [newZone] = await tx
            .insert(zones)
            .values({
              locationId: createDto.locationId,
              code: 'RECV',
              name: 'Receiving Dock',
              createdBy: userId,
            })
            .returning();
          receivingZone = newZone;
        }

        let receivingBin = await tx
          .select({ binId: bins.binId })
          .from(bins)
          .where(
            and(
              eq(bins.zoneId, receivingZone.zoneId),
              eq(bins.binNumber, 'RECEIVING'),
            ),
          )
          .limit(1)
          .then((res) => res[0]);

        if (!receivingBin) {
          const [newBin] = await tx
            .insert(bins)
            .values({
              zoneId: receivingZone.zoneId,
              binNumber: 'RECEIVING',
              binType: 'receiving',
              createdBy: userId,
            })
            .returning();
          receivingBin = newBin;
        }

        // Create inventory ledger entries via inventoryService
        await this.inventoryService.recordInventoryMovement(tx, {
          entryNumber: `GRN-${receipt.receiptNumber}`,
          sourceType: 'PO_RECEIPT',
          sourceId: receipt.goodsReceivedId,
          memo: `Goods Reception ${receipt.receiptNumber}`,
          userId,
          lines: lineValues.map((lv) => ({
            productId: lv.productId,
            binId: receivingBin.binId,
            quantity: parseFloat(lv.quantityReceived),
          })),
        });

        // --- 5.1 Financial Integration & Valuation Updates ---
        const valuationMethodCode = this.appConfig.valuationMethod();
        const valuationStrategy = getValuationStrategy(valuationMethodCode);

        // Fetch products to update their WAC and get standard costs
        const productIds = [...new Set(lineValues.map((l) => l.productId))];
        const productRows = await tx
          .select({
            productId: products.productId,
            standardCost: products.standardCost,
            weightedAverageCost: products.weightedAverageCost,
            qoh: sql`COALESCE((SELECT SUM(actual_quantity) FROM modbm_core.bin_contents WHERE product_id = ${products.productId}), 0)`.mapWith(
              Number,
            ),
          })
          .from(products)
          .where(
            sql`${products.productId} IN (${sql.join(
              productIds.map((p) => sql`${p}`),
              sql`, `,
            )})`,
          );

        const productMap = new Map(productRows.map((p) => [p.productId, p]));
        let totalInventoryValueAdded = 0;

        for (const lv of lineValues) {
          const product = productMap.get(lv.productId);
          if (!product) continue;

          const qty = parseFloat(lv.quantityReceived);
          const unitCost = lv.unitCost ? String(lv.unitCost) : '0';

          const productData = {
            ...product,
            standardCost: product.standardCost || '0',
            weightedAverageCost: product.weightedAverageCost || '0',
          };

          const valuation = valuationStrategy.onGoodsReceipt(
            productData,
            product.qoh,
            qty,
            unitCost,
          );

          totalInventoryValueAdded += parseFloat(valuation.inventoryValueAdded);

          // Update product WAC
          await tx
            .update(products)
            .set({ weightedAverageCost: valuation.newWeightedAverageCost })
            .where(eq(products.productId, product.productId));

          // Update local QOH to ensure subsequent lines calculate correctly
          product.qoh += qty;
          product.weightedAverageCost = valuation.newWeightedAverageCost;
        }

        // Post Journal Entry via Accounting Strategy
        const accountingStrategy = getAccountingStrategy(
          this.appConfig.inventoryAccountingMode(),
          {
            inventoryAccountId: this.appConfig.defaultInventoryAccountId(),
            grniAccountId: this.appConfig.defaultGrniAccountId(),
            cogsAccountId: this.appConfig.defaultCogsAccountId(),
            shrinkageAccountId: this.appConfig.defaultShrinkageAccountId(),
          },
        );

        const glResult = accountingStrategy.onGoodsReceipt({
          amount: Number(totalInventoryValueAdded.toFixed(2)),
          memo: `Goods Receipt ${receipt.receiptNumber}`,
          partyType: 'supplier',
          partyId: vendor.vendorId,
          costCenterId: vendor.costCenterId || undefined,
          activityId: vendor.activityId || undefined,
        });

        if (glResult) {
          await this.glService.postJournalEntry(
            glResult.lines as any,
            {
              actor: userId,
              entryDate: new Date().toISOString().slice(0, 10),
              sourceType: glResult.sourceType,
              sourceId: receipt.goodsReceivedId,
              memo: `Goods Receipt ${receipt.receiptNumber} (${vendor.name})`,
            },
            tx,
          );
        }

        // --- 6. PO Update: Update matched PO lines ---
        const matchedLines = lineValues.filter(
          (l) => l.matchStatus === 'matched',
        );
        for (const ml of matchedLines) {
          await tx
            .update(purchaseOrderLineItems)
            .set({
              quantityReceived: sql`CAST(quantity_received AS NUMERIC) + CAST(${ml.quantityReceived} AS NUMERIC)`,
            })
            .where(
              eq(
                purchaseOrderLineItems.purchaseOrderLineId,
                ml.purchaseOrderLineId,
              ),
            );
        }

        // --- 6.1 Backorder Sync: Transition awaiting_receipt → received_reserved ---
        for (const ml of matchedLines) {
          if (!ml.purchaseOrderLineId) continue;

          const awaitingBackorders = await tx
            .select()
            .from(backorders)
            .where(
              and(
                eq(backorders.purchaseOrderLineId, ml.purchaseOrderLineId),
                eq(backorders.stateCode, BACKORDER_STATE.AWAITING_RECEIPT),
              ),
            );

          let receiptRemaining = parseFloat(ml.quantityReceived);

          for (const bo of awaitingBackorders) {
            if (receiptRemaining <= 0) break;
            const boQty = parseFloat(bo.quantity);

            if (receiptRemaining >= boQty) {
              // Fully fulfilled — transition entire backorder
              await this.changeBackorderState(
                bo.backorderId,
                BACKORDER_STATE.RECEIVED_RESERVED,
                userId,
                tx,
              );
              receiptRemaining -= boQty;
            } else {
              // Partially fulfilled — split the backorder record
              await tx
                .update(backorders)
                .set({
                  quantity: (boQty - receiptRemaining).toString(),
                  modifiedOn: new Date(),
                })
                .where(eq(backorders.backorderId, bo.backorderId));

              await tx.insert(backorders).values({
                salesOrderId: bo.salesOrderId,
                salesOrderLineId: bo.salesOrderLineId,
                productId: bo.productId,
                purchaseOrderId: bo.purchaseOrderId,
                purchaseOrderLineId: bo.purchaseOrderLineId,
                quantity: receiptRemaining.toString(),
                stateCode: BACKORDER_STATE.RECEIVED_RESERVED,
              });
              receiptRemaining = 0;
            }
          }
        }

        // Recompute PO State for any affected POs
        const updatedPoIds = [
          ...new Set(
            matchedLines.map((l) => l.purchaseOrderId!).filter(Boolean),
          ),
        ];
        for (const poId of updatedPoIds) {
          // Trigger the lifecycle engine instead of hardcoded updates
          try {
            await evaluatePOLifecycleRules(
              tx as any,
              poId,
              {
                entity: 'goods_receipt',
                action: 'created',
              },
              'system',
            );
          } catch (err) {
            this.logger.error(
              `Failed to evaluate PO lifecycle rules for PO ${poId} after goods receipt:`,
              err,
            );
          }
        }
      }

      // 7. Emit audit event
      await emitEvent(tx, {
        aggregateType: AggregateType.SYSTEM,
        aggregateId: receipt.goodsReceivedId,
        eventType: EventType.STOCK_RECEIVED,
        payload: {
          goodsReceivedId: receipt.goodsReceivedId,
          receiptNumber: receipt.receiptNumber,
          vendorId: createDto.vendorId,
          vendorName: vendor.name,
          locationId: createDto.locationId,
          packingSlipNumber: createDto.packingSlipNumber,
          lineCount: createDto.lines?.length || 0,
        },
        actor: userId,
      });

      this.logger.log(
        `Goods received ${receiptNumber} created for supplier ${vendor.name}`,
      );

      return this.findOne(receipt.goodsReceivedId, tx);
    });
  }

  /**
   * Cancel a goods receipt.
   *
   * Reverses inventory ledgers, GL integration, decrements PO quantity,
   * and reverts PO state if applicable.
   */
  async cancelReception(goodsReceivedId: string, userId: string) {
    return await this.db.transaction(async (tx) => {
      // 1. Load receipt and lines
      const [receipt] = await tx
        .select()
        .from(goodsReceived)
        .where(eq(goodsReceived.goodsReceivedId, goodsReceivedId))
        .limit(1);

      if (!receipt) {
        throw new NotFoundException(
          `Goods receipt ${goodsReceivedId} not found.`,
        );
      }

      if (receipt.stateCode === RECEIPT_STATE.CANCELLED) {
        throw new BadRequestException('Receipt is already cancelled.');
      }

      const receiptLines = await tx
        .select()
        .from(goodsReceivedLines)
        .where(eq(goodsReceivedLines.goodsReceivedId, goodsReceivedId));

      // 2. Validate states
      for (const line of receiptLines) {
        if (line.putawayStatus === 'completed') {
          throw new BadRequestException(
            `Line ${line.goodsReceivedLineId} has been putaway. Cannot cancel receipt directly. You must reverse the putaway first.`,
          );
        }
      }

      // Check if it is invoiced (Optional, but if we don't have purchase_invoice_lines handy, stateCode 'invoiced' on GR isn't tracked. We will rely on manual checks if any).
      // Wait, let's assume no invoice logic is explicitly checked for now, just cancellation.

      // 3. Reverse Inventory Movement
      const receivingBinCode = 'RECEIVING';
      const [receivingZone] = await tx
        .select({ zoneId: zones.zoneId })
        .from(zones)
        .where(
          and(eq(zones.locationId, receipt.locationId), eq(zones.code, 'RECV')),
        )
        .limit(1);

      if (!receivingZone) {
        throw new BadRequestException(
          'Receiving zone not found. Cannot cancel.',
        );
      }

      const [receivingBin] = await tx
        .select({ binId: bins.binId })
        .from(bins)
        .where(
          and(
            eq(bins.zoneId, receivingZone.zoneId),
            eq(bins.binNumber, receivingBinCode),
          ),
        )
        .limit(1);

      if (!receivingBin) {
        throw new BadRequestException(
          'Receiving bin not found. Cannot cancel.',
        );
      }

      await this.inventoryService.recordInventoryMovement(tx, {
        entryNumber: `CAN-${receipt.receiptNumber}`,
        sourceType: 'PO_RECEIPT',
        sourceId: receipt.goodsReceivedId,
        memo: `Cancel Reception ${receipt.receiptNumber}`,
        userId,
        lines: receiptLines.map((lv) => ({
          productId: lv.productId,
          binId: receivingBin.binId,
          quantity: -parseFloat(lv.quantityReceived),
        })),
      });

      // 4. Reverse Financial Integration (GL)
      // Find the original journal entry
      const [originalEntry] = await tx
        .select()
        .from(glJournalEntries)
        .where(
          and(
            eq(glJournalEntries.sourceId, receipt.goodsReceivedId),
            eq(glJournalEntries.sourceType, 'inventory_receipt'),
          ),
        )
        .limit(1);

      if (originalEntry) {
        const originalLines = await tx
          .select()
          .from(glJournalLines)
          .where(
            eq(glJournalLines.journalEntryId, originalEntry.journalEntryId),
          );

        if (originalLines.length > 0) {
          const reversedLines = originalLines.map((line) => ({
            accountId: line.glAccountId,
            costCenterId: line.costCenterId,
            activityId: line.activityId,
            partyType: line.partyType,
            partyId: line.partyId,
            debit: parseFloat(line.credit), // Swap debits/credits
            credit: parseFloat(line.debit),
            memo: `Reversal of ${originalEntry.entryNumber}`,
          }));

          await this.glService.postJournalEntry(
            reversedLines as any,
            {
              actor: userId,
              entryDate: new Date().toISOString().slice(0, 10),
              sourceType: 'inventory_receipt',
              sourceId: receipt.goodsReceivedId,
              memo: `Cancel Reception ${receipt.receiptNumber}`,
            },
            tx,
          );
        }
      }

      // 5. Decrement PO lines and revert PO state
      const updatedPoIds = new Set<string>();

      for (const line of receiptLines) {
        if (
          line.matchStatus === 'matched' &&
          line.purchaseOrderLineId &&
          line.purchaseOrderId
        ) {
          await tx.execute(
            sql`UPDATE modbm_core.purchase_order_lines 
                SET quantity_received = COALESCE(quantity_received, 0) - CAST(${line.quantityReceived} AS NUMERIC)
                WHERE purchase_order_line_id = ${line.purchaseOrderLineId}`,
          );
          updatedPoIds.add(line.purchaseOrderId);
        }
      }

      // Revert PO States
      for (const poId of updatedPoIds) {
        const lines = await tx
          .select({
            quantityReceived: purchaseOrderLineItems.quantityReceived,
          })
          .from(purchaseOrderLineItems)
          .where(eq(purchaseOrderLineItems.purchaseOrderId, poId));

        const totalReceived = lines.reduce(
          (sum, l) => sum + parseFloat(l.quantityReceived || '0'),
          0,
        );

        let newPoState: PurchaseOrderState = PURCHASE_ORDER_STATE.ORDERED;
        if (totalReceived > 0) {
          // If there are still received lines, it might be partially received
          newPoState = PURCHASE_ORDER_STATE.PARTIALLY_RECEIVED;
        }

        // Just blindly revert state, assuming no invoice blocking. If the user wants to close short later they can.
        await this.changePurchaseOrderState(poId, newPoState, userId, tx);

        await emitEvent(tx, {
          aggregateType: AggregateType.PURCHASE_ORDER,
          aggregateId: poId,
          eventType: 'auto_status_changed',
          payload: {
            rule: 'cancel_receipt_revert',
            from: PURCHASE_ORDER_STATE.RECEIVED,
            to: newPoState,
            reason: `Receipt ${receipt.receiptNumber} was cancelled.`,
          },
          actor: userId,
        });
      }

      // 6. Update GR state
      await this.changeReceiptState(
        goodsReceivedId,
        RECEIPT_STATE.CANCELLED,
        userId,
        tx,
      );

      this.logger.log(
        `Goods received ${receipt.receiptNumber} cancelled by ${userId}`,
      );

      return { success: true };
    });
  }

  /**
   * Universal changeState for Goods Receipt
   */
  async changeReceiptState(
    receiptId: string,
    newState: string,
    actor: string,
    tx: DrizzleDB,
  ) {
    if (!VALID_GRN_STATES.includes(newState)) {
      throw new BadRequestException(
        `Invalid goods receipt state: '${newState}'`,
      );
    }

    const [receipt] = await tx
      .select({
        stateCode: goodsReceived.stateCode,
        receiptNumber: goodsReceived.receiptNumber,
      })
      .from(goodsReceived)
      .where(eq(goodsReceived.goodsReceivedId, receiptId));

    if (!receipt) {
      throw new NotFoundException(`Receipt ${receiptId} not found`);
    }

    const allowed = RECEIPT_TRANSITIONS[receipt.stateCode];
    if (!allowed || !allowed.includes(newState)) {
      throw new BadRequestException(
        `Cannot transition receipt from '${receipt.stateCode}' to '${newState}'. Allowed transitions: ${allowed?.join(', ') || 'none'}`,
      );
    }

    const [updated] = await tx
      .update(goodsReceived)
      .set({ stateCode: newState, modifiedOn: new Date() })
      .where(eq(goodsReceived.goodsReceivedId, receiptId))
      .returning();

    await emitEvent(tx as any, {
      aggregateType: AggregateType.GOODS_RECEIPT,
      aggregateId: receiptId,
      eventType: 'status_changed',
      payload: {
        entity: 'goods_receipt',
        entityId: receiptId,
        receiptNumber: receipt.receiptNumber,
        from: receipt.stateCode,
        to: newState,
      },
      actor,
    });

    return updated;
  }

  /**
   * List all goods receipts with pagination and optional filtering.
   */
  async findAll(params: PaginationQuery) {
    const { page, limit, offset, searchTerm, days } = parsePagination(params);

    const conditions = [];

    if (searchTerm) {
      conditions.push(
        or(
          ilike(goodsReceived.receiptNumber, searchTerm),
          ilike(goodsReceived.packingSlipNumber, searchTerm),
          ilike(suppliers.name, searchTerm),
        ),
      );
    }

    if (days && days > 0) {
      conditions.push(
        sql`${goodsReceived.createdOn} >= now() - interval '${sql.raw(String(days))} days'`,
      );
    }

    const whereClause = conditions.length > 0 ? and(...conditions) : undefined;

    const data = await this.db
      .select({
        receipt: goodsReceived,
        vendorName: suppliers.name,
        vendorNumber: suppliers.vendorNumber,
      })
      .from(goodsReceived)
      .leftJoin(suppliers, eq(goodsReceived.vendorId, suppliers.vendorId))
      .where(whereClause)
      .limit(limit)
      .offset(offset)
      .orderBy(desc(goodsReceived.createdOn));

    const [{ count }] = await this.db
      .select({ count: sql<number>`count(*)` })
      .from(goodsReceived)
      .leftJoin(suppliers, eq(goodsReceived.vendorId, suppliers.vendorId))
      .where(whereClause);

    // For each receipt, count match statuses
    const receiptIds = data.map((d) => d.receipt.goodsReceivedId);
    let matchCounts: Map<string, { total: number; matched: number }> =
      new Map();

    if (receiptIds.length > 0) {
      const lineCounts = await this.db
        .select({
          goodsReceivedId: goodsReceivedLines.goodsReceivedId,
          total: sql<number>`count(*)`,
          matched: sql<number>`count(*) FILTER (WHERE ${goodsReceivedLines.matchStatus} = 'matched')`,
        })
        .from(goodsReceivedLines)
        .where(
          sql`${goodsReceivedLines.goodsReceivedId} IN (${sql.join(
            receiptIds.map((id) => sql`${id}`),
            sql`, `,
          )})`,
        )
        .groupBy(goodsReceivedLines.goodsReceivedId);

      matchCounts = new Map(
        lineCounts.map((lc) => [
          lc.goodsReceivedId,
          { total: Number(lc.total), matched: Number(lc.matched) },
        ]),
      );
    }

    return {
      data: data.map((d) => {
        const counts = matchCounts.get(d.receipt.goodsReceivedId) || {
          total: 0,
          matched: 0,
        };
        return {
          ...d.receipt,
          vendorName: d.vendorName,
          vendorNumber: d.vendorNumber,
          totalLines: counts.total,
          matchedLines: counts.matched,
        };
      }),
      page,
      limit,
      total: Number(count),
    };
  }

  /**
   * List all goods receipt lines with pagination and optional filtering.
   * This provides a flattened "Receipt Lines" view.
   */
  async findAllLines(
    params: PaginationQuery,
    purchaseOrderId?: string,
    putawayStatus?: string,
    locationId?: string,
  ) {
    const { page, limit, offset, searchTerm, days } = parsePagination(params);

    const conditions = [];

    if (purchaseOrderId) {
      conditions.push(eq(goodsReceivedLines.purchaseOrderId, purchaseOrderId));
    }

    if (putawayStatus) {
      conditions.push(
        eq(goodsReceivedLines.putawayStatus, putawayStatus as any),
      );
    }

    if (locationId) {
      conditions.push(eq(goodsReceived.locationId, locationId));
    }

    if (searchTerm) {
      conditions.push(
        or(
          ilike(goodsReceived.receiptNumber, searchTerm),
          ilike(goodsReceived.packingSlipNumber, searchTerm),
          ilike(products.productNumber, searchTerm),
          ilike(products.alternateProductNumber, searchTerm),
          ilike(products.name, searchTerm),
          ilike(suppliers.name, searchTerm),
        ),
      );
    }

    if (days && days > 0) {
      conditions.push(
        sql`${goodsReceived.createdOn} >= now() - interval '${sql.raw(String(days))} days'`,
      );
    }

    const whereClause = conditions.length > 0 ? and(...conditions) : undefined;

    const data = await this.db
      .select({
        line: goodsReceivedLines,
        receiptNumber: goodsReceived.receiptNumber,
        packingSlipNumber: goodsReceived.packingSlipNumber,
        vendorId: suppliers.vendorId,
        vendorName: suppliers.name,
        createdOn: goodsReceived.createdOn,
        locationId: goodsReceived.locationId,
        locationName: locations.name,
        productNumber: products.productNumber,
        productName: products.name,
        orderNumber: purchaseOrders.orderNumber,
        stateCode: goodsReceived.stateCode,
      })
      .from(goodsReceivedLines)
      .leftJoin(
        goodsReceived,
        eq(goodsReceivedLines.goodsReceivedId, goodsReceived.goodsReceivedId),
      )
      .leftJoin(products, eq(goodsReceivedLines.productId, products.productId))
      .leftJoin(suppliers, eq(goodsReceived.vendorId, suppliers.vendorId))
      .leftJoin(
        purchaseOrders,
        eq(goodsReceivedLines.purchaseOrderId, purchaseOrders.purchaseOrderId),
      )
      .leftJoin(locations, eq(goodsReceived.locationId, locations.locationId))
      .where(whereClause)
      .limit(limit)
      .offset(offset)
      .orderBy(desc(goodsReceived.createdOn));

    const [{ count }] = await this.db
      .select({ count: sql<number>`count(*)` })
      .from(goodsReceivedLines)
      .leftJoin(
        goodsReceived,
        eq(goodsReceivedLines.goodsReceivedId, goodsReceived.goodsReceivedId),
      )
      .leftJoin(products, eq(goodsReceivedLines.productId, products.productId))
      .leftJoin(suppliers, eq(goodsReceived.vendorId, suppliers.vendorId))
      .where(whereClause);

    return {
      data: data.map((d) => ({
        ...d.line,
        receiptNumber: d.receiptNumber,
        packingSlipNumber: d.packingSlipNumber,
        vendorId: d.vendorId,
        vendorName: d.vendorName,
        createdOn: d.createdOn,
        locationId: d.locationId,
        locationName: d.locationName,
        productNumber: d.productNumber,
        productName: d.productName,
        orderNumber: d.orderNumber,
        stateCode: d.stateCode,
      })),
      page,
      limit,
      total: Number(count),
    };
  }

  /**
   * Get a single goods receipt with all lines.
   */
  async findOne(id: string, tx: any = this.db) {
    const receipt = await tx
      .select({
        receipt: goodsReceived,
        vendorName: suppliers.name,
        vendorNumber: suppliers.vendorNumber,
      })
      .from(goodsReceived)
      .leftJoin(suppliers, eq(goodsReceived.vendorId, suppliers.vendorId))
      .where(eq(goodsReceived.goodsReceivedId, id))
      .limit(1)
      .then((res: any[]) => res[0]);

    if (!receipt) {
      throw new NotFoundException(`Goods receipt ${id} not found`);
    }

    const lines = await tx
      .select({
        goodsReceivedLineId: goodsReceivedLines.goodsReceivedLineId,
        productId: goodsReceivedLines.productId,
        quantityReceived: goodsReceivedLines.quantityReceived,
        matchStatus: goodsReceivedLines.matchStatus,
        putawayStatus: goodsReceivedLines.putawayStatus,
        purchaseOrderLineId: goodsReceivedLines.purchaseOrderLineId,
        purchaseOrderId: goodsReceivedLines.purchaseOrderId,
        productNumber: products.productNumber,
        productName: products.name,
        orderNumber: purchaseOrders.orderNumber,
      })
      .from(goodsReceivedLines)
      .leftJoin(products, eq(goodsReceivedLines.productId, products.productId))
      .leftJoin(
        purchaseOrders,
        eq(goodsReceivedLines.purchaseOrderId, purchaseOrders.purchaseOrderId),
      )
      .where(eq(goodsReceivedLines.goodsReceivedId, id));

    return {
      ...receipt.receipt,
      vendorName: receipt.vendorName,
      vendorNumber: receipt.vendorNumber,
      lines,
    };
  }

  /**
   * Manually resolve an ambiguous or unmatched line to a specific PO line.
   */
  async resolveAllocation(
    goodsReceivedLineId: string,
    poLineId: string,
    userId: string,
    allocatedQuantity?: string,
  ) {
    return await this.db.transaction(async (tx) => {
      const [grLine] = await tx
        .select()
        .from(goodsReceivedLines)
        .where(eq(goodsReceivedLines.goodsReceivedLineId, goodsReceivedLineId))
        .limit(1);

      if (!grLine) throw new NotFoundException('Line not found');
      if (grLine.matchStatus === 'matched')
        throw new BadRequestException('Line already matched');

      const [poLine] = await tx
        .select({
          poLineId: purchaseOrderLineItems.purchaseOrderLineId,
          poId: purchaseOrderLineItems.purchaseOrderId,
          quantity: purchaseOrderLineItems.quantity,
          quantityReceived: purchaseOrderLineItems.quantityReceived,
          stateCode: purchaseOrders.stateCode,
        })
        .from(purchaseOrderLineItems)
        .innerJoin(
          purchaseOrders,
          eq(
            purchaseOrderLineItems.purchaseOrderId,
            purchaseOrders.purchaseOrderId,
          ),
        )
        .where(eq(purchaseOrderLineItems.purchaseOrderLineId, poLineId))
        .limit(1);

      if (!poLine) throw new NotFoundException('PO Line not found');
      if (
        [
          PURCHASE_ORDER_STATE.RECEIVED,
          PURCHASE_ORDER_STATE.INVOICED,
          PURCHASE_ORDER_STATE.CANCELLED,
          PURCHASE_ORDER_STATE.CLOSED_SHORT,
        ].includes(poLine.stateCode as any)
      ) {
        throw new BadRequestException(
          `Cannot match to a PO in '${poLine.stateCode}' state.`,
        );
      }

      const originalQuantity = parseFloat(grLine.quantityReceived);
      const targetQuantity = allocatedQuantity
        ? parseFloat(allocatedQuantity)
        : originalQuantity;

      if (targetQuantity <= 0 || targetQuantity > originalQuantity) {
        throw new BadRequestException('Invalid allocated quantity');
      }

      // Update GR Line
      await tx
        .update(goodsReceivedLines)
        .set({
          matchStatus: 'matched',
          // ADV-086: Preserve quarantined status if set — matching doesn't clear quarantine
          putawayStatus:
            grLine.putawayStatus === 'quarantined'
              ? 'quarantined'
              : 'pending_putaway',
          purchaseOrderLineId: poLine.poLineId,
          purchaseOrderId: poLine.poId,
          quantityReceived: targetQuantity.toString(),
        })
        .where(eq(goodsReceivedLines.goodsReceivedLineId, goodsReceivedLineId));

      // Handle partial allocation splits
      let splitLine = null;
      if (targetQuantity < originalQuantity) {
        const remainder = originalQuantity - targetQuantity;
        const [inserted] = await tx
          .insert(goodsReceivedLines)
          .values({
            goodsReceivedId: grLine.goodsReceivedId,
            productId: grLine.productId,
            quantityReceived: remainder.toString(),
            matchStatus: 'ambiguous',
            putawayStatus: 'awaiting_matching',
          })
          .returning();
        splitLine = inserted;
      }

      // Update PO Line
      await tx
        .update(purchaseOrderLineItems)
        .set({
          quantityReceived: sql`CAST(quantity_received AS NUMERIC) + CAST(${targetQuantity} AS NUMERIC)`,
        })
        .where(eq(purchaseOrderLineItems.purchaseOrderLineId, poLine.poLineId));

      // --- Backorder Sync: Transition awaiting_receipt → received_reserved ---
      const awaitingBackorders = await tx
        .select()
        .from(backorders)
        .where(
          and(
            eq(backorders.purchaseOrderLineId, poLine.poLineId),
            eq(backorders.stateCode, 'awaiting_receipt'),
          ),
        );

      let receiptRemaining = targetQuantity;

      for (const bo of awaitingBackorders) {
        if (receiptRemaining <= 0) break;
        const boQty = parseFloat(bo.quantity);

        if (receiptRemaining >= boQty) {
          await tx
            .update(backorders)
            .set({ stateCode: 'received_reserved', modifiedOn: new Date() })
            .where(eq(backorders.backorderId, bo.backorderId));
          receiptRemaining -= boQty;
        } else {
          await tx
            .update(backorders)
            .set({
              quantity: (boQty - receiptRemaining).toString(),
              modifiedOn: new Date(),
            })
            .where(eq(backorders.backorderId, bo.backorderId));

          await tx.insert(backorders).values({
            salesOrderId: bo.salesOrderId,
            salesOrderLineId: bo.salesOrderLineId,
            productId: bo.productId,
            purchaseOrderId: bo.purchaseOrderId,
            purchaseOrderLineId: bo.purchaseOrderLineId,
            quantity: receiptRemaining.toString(),
            stateCode: 'received_reserved',
          });
          receiptRemaining = 0;
        }
      }

      // Recompute PO State
      const poLines = await tx
        .select({
          quantity: purchaseOrderLineItems.quantity,
          quantityReceived: purchaseOrderLineItems.quantityReceived,
        })
        .from(purchaseOrderLineItems)
        .where(eq(purchaseOrderLineItems.purchaseOrderId, poLine.poId));

      const allFullyReceived = poLines.every(
        (l) =>
          parseFloat(l.quantityReceived || '0') >=
          parseFloat(l.quantity || '0'),
      );

      await tx
        .update(purchaseOrders)
        .set({
          stateCode: allFullyReceived
            ? PURCHASE_ORDER_STATE.RECEIVED
            : PURCHASE_ORDER_STATE.PARTIALLY_RECEIVED,
        })
        .where(eq(purchaseOrders.purchaseOrderId, poLine.poId));

      // Emit Event
      await emitEvent(tx, {
        aggregateType: AggregateType.SYSTEM,
        aggregateId: grLine.goodsReceivedId,
        eventType: EventType.RECEIPT_MATCHED,
        payload: {
          goodsReceivedLineId,
          purchaseOrderLineId: poLine.poLineId,
          purchaseOrderId: poLine.poId,
          allocatedQuantity: targetQuantity,
        },
        actor: userId,
      });

      return { success: true, splitLine };
    });
  }

  /**
   * Unresolve a previously matched line back to ambiguous state.
   */
  async unresolveAllocation(goodsReceivedLineId: string, userId: string) {
    return await this.db.transaction(async (tx) => {
      const [grLine] = await tx
        .select()
        .from(goodsReceivedLines)
        .where(eq(goodsReceivedLines.goodsReceivedLineId, goodsReceivedLineId))
        .limit(1);

      if (!grLine) throw new NotFoundException('Line not found');
      if (grLine.matchStatus !== 'matched' || !grLine.purchaseOrderLineId) {
        throw new BadRequestException('Line is not matched to a PO');
      }

      const [poLine] = await tx
        .select({
          poLineId: purchaseOrderLineItems.purchaseOrderLineId,
          poId: purchaseOrderLineItems.purchaseOrderId,
          quantity: purchaseOrderLineItems.quantity,
          quantityReceived: purchaseOrderLineItems.quantityReceived,
        })
        .from(purchaseOrderLineItems)
        .where(
          eq(
            purchaseOrderLineItems.purchaseOrderLineId,
            grLine.purchaseOrderLineId,
          ),
        )
        .limit(1);

      if (!poLine) throw new NotFoundException('Linked PO Line not found');

      // 1. Attempt Reunification or fall back to making it ambiguous
      const [existingUnmatched] = await tx
        .select()
        .from(goodsReceivedLines)
        .where(
          and(
            eq(goodsReceivedLines.goodsReceivedId, grLine.goodsReceivedId),
            eq(goodsReceivedLines.productId, grLine.productId),
            sql`${goodsReceivedLines.matchStatus} != 'matched'`,
            sql`${goodsReceivedLines.goodsReceivedLineId} != ${grLine.goodsReceivedLineId}`,
          ),
        )
        .limit(1);

      if (existingUnmatched) {
        // Reunify into the existing unmatched line
        await tx
          .update(goodsReceivedLines)
          .set({
            quantityReceived: sql`CAST(quantity_received AS NUMERIC) + CAST(${grLine.quantityReceived} AS NUMERIC)`,
          })
          .where(
            eq(
              goodsReceivedLines.goodsReceivedLineId,
              existingUnmatched.goodsReceivedLineId,
            ),
          );

        // Delete this fragmented line
        await tx
          .delete(goodsReceivedLines)
          .where(
            eq(goodsReceivedLines.goodsReceivedLineId, goodsReceivedLineId),
          );
      } else {
        // Just unresolve it normally
        // ADV-086: Preserve quarantined status — only clear PO links, don't change putaway state
        await tx
          .update(goodsReceivedLines)
          .set({
            matchStatus: 'ambiguous',
            putawayStatus:
              grLine.putawayStatus === 'quarantined'
                ? 'quarantined'
                : 'awaiting_matching',
            purchaseOrderLineId: null,
            purchaseOrderId: null,
          })
          .where(
            eq(goodsReceivedLines.goodsReceivedLineId, goodsReceivedLineId),
          );
      }

      // 2. Deduct quantity from PO Line
      await tx
        .update(purchaseOrderLineItems)
        .set({
          quantityReceived: sql`CAST(quantity_received AS NUMERIC) - CAST(${grLine.quantityReceived} AS NUMERIC)`,
        })
        .where(eq(purchaseOrderLineItems.purchaseOrderLineId, poLine.poLineId));

      // 3. Recompute PO State
      const poLines = await tx
        .select({
          quantity: purchaseOrderLineItems.quantity,
          quantityReceived: purchaseOrderLineItems.quantityReceived,
        })
        .from(purchaseOrderLineItems)
        .where(eq(purchaseOrderLineItems.purchaseOrderId, poLine.poId));

      const allFullyReceived = poLines.every(
        (l) =>
          parseFloat(l.quantityReceived || '0') >=
          parseFloat(l.quantity || '0'),
      );

      const anyReceived = poLines.some(
        (l) => parseFloat(l.quantityReceived || '0') > 0,
      );

      await tx
        .update(purchaseOrders)
        .set({
          stateCode: allFullyReceived
            ? PURCHASE_ORDER_STATE.RECEIVED
            : anyReceived
              ? PURCHASE_ORDER_STATE.PARTIALLY_RECEIVED
              : PURCHASE_ORDER_STATE.ORDERED,
        })
        .where(eq(purchaseOrders.purchaseOrderId, poLine.poId));

      // 4. Emit Event
      await emitEvent(tx, {
        aggregateType: AggregateType.SYSTEM,
        aggregateId: grLine.goodsReceivedId,
        eventType: EventType.RECEIPT_UNMATCHED,
        payload: {
          goodsReceivedLineId,
          previousPurchaseOrderLineId: poLine.poLineId,
          previousPurchaseOrderId: poLine.poId,
        },
        actor: userId,
      });

      return { success: true };
    });
  }

  async toggleQuarantine(
    goodsReceivedLineId: string,
    userId: string,
    reason?: string,
  ) {
    return await this.db.transaction(async (tx) => {
      const [grLine] = await tx
        .select({
          line: goodsReceivedLines,
          locationId: goodsReceived.locationId,
          receiptNumber: goodsReceived.receiptNumber,
        })
        .from(goodsReceivedLines)
        .innerJoin(
          goodsReceived,
          eq(goodsReceivedLines.goodsReceivedId, goodsReceived.goodsReceivedId),
        )
        .where(eq(goodsReceivedLines.goodsReceivedLineId, goodsReceivedLineId))
        .limit(1);

      if (!grLine) throw new NotFoundException('Line not found');

      const currentStatus = grLine.line.putawayStatus;
      if (currentStatus === 'completed') {
        throw new BadRequestException(
          'Cannot quarantine an already putaway line',
        );
      }

      // ADV-086: Context-aware status restoration
      // When un-quarantining, restore to 'pending_putaway' only if matched to a PO;
      // otherwise restore to 'awaiting_matching' to prevent unmatched items
      // from bypassing the allocation stage.
      let newStatus: 'quarantined' | 'pending_putaway' | 'awaiting_matching';
      if (currentStatus === 'quarantined') {
        newStatus = grLine.line.purchaseOrderLineId
          ? 'pending_putaway'
          : 'awaiting_matching';
      } else {
        newStatus = 'quarantined';
      }
      const targetBinCode =
        newStatus === 'quarantined' ? 'QUARANTINE' : 'RECEIVING';
      const currentBinCode =
        currentStatus === 'quarantined' ? 'QUARANTINE' : 'RECEIVING';

      // Find the zones/bins
      const [sourceBin] = await tx
        .select({ binId: bins.binId })
        .from(bins)
        .innerJoin(zones, eq(bins.zoneId, zones.zoneId))
        .where(
          and(
            eq(zones.locationId, grLine.locationId),
            eq(bins.binNumber, currentBinCode),
          ),
        )
        .limit(1);

      let targetBin = await tx
        .select({ binId: bins.binId, zoneId: bins.zoneId })
        .from(bins)
        .innerJoin(zones, eq(bins.zoneId, zones.zoneId))
        .where(
          and(
            eq(zones.locationId, grLine.locationId),
            eq(bins.binNumber, targetBinCode),
          ),
        )
        .limit(1)
        .then((res) => res[0]);

      if (!targetBin) {
        // Find or create zone
        let targetZone = await tx
          .select({ zoneId: zones.zoneId })
          .from(zones)
          .where(
            and(
              eq(zones.locationId, grLine.locationId),
              eq(zones.code, targetBinCode === 'QUARANTINE' ? 'QUAR' : 'RECV'),
            ),
          )
          .limit(1)
          .then((res) => res[0]);

        if (!targetZone) {
          const [newZone] = await tx
            .insert(zones)
            .values({
              locationId: grLine.locationId,
              code: targetBinCode === 'QUARANTINE' ? 'QUAR' : 'RECV',
              name:
                targetBinCode === 'QUARANTINE'
                  ? 'Quarantine Zone'
                  : 'Receiving Dock',
              createdBy: userId,
            })
            .returning();
          targetZone = newZone;
        }

        const [newBin] = await tx
          .insert(bins)
          .values({
            zoneId: targetZone.zoneId,
            binNumber: targetBinCode,
            binType:
              targetBinCode === 'QUARANTINE' ? 'quarantine' : 'receiving',
            createdBy: userId,
          })
          .returning();
        targetBin = newBin;
      }

      // ADV-086: Strict bin validation — never update status without a ledger movement
      if (!sourceBin) {
        throw new BadRequestException(
          `Source bin '${currentBinCode}' not found for this location. Cannot toggle quarantine.`,
        );
      }

      await this.inventoryService.recordInventoryMovement(tx, {
        entryNumber: `QRN-${grLine.receiptNumber}-${grLine.line.goodsReceivedLineId.substring(0, 4)}`,
        sourceType: 'PO_RECEIPT',
        sourceId: grLine.line.goodsReceivedId,
        memo: reason
          ? `Status: ${newStatus} - ${reason}`
          : `Status: ${newStatus}`,
        userId,
        lines: [
          {
            productId: grLine.line.productId,
            binId: sourceBin.binId,
            quantity: -parseFloat(grLine.line.quantityReceived),
          },
          {
            productId: grLine.line.productId,
            binId: targetBin.binId,
            quantity: parseFloat(grLine.line.quantityReceived),
          },
        ],
      });

      await tx
        .update(goodsReceivedLines)
        .set({ putawayStatus: newStatus })
        .where(eq(goodsReceivedLines.goodsReceivedLineId, goodsReceivedLineId));

      return { success: true, putawayStatus: newStatus };
    });
  }

  async putaway(dto: import('./dto').PutawayBulkDto, userId: string) {
    return await this.db.transaction(async (tx) => {
      for (const lineDto of dto.putaways) {
        const [grLine] = await tx
          .select({
            line: goodsReceivedLines,
            locationId: goodsReceived.locationId,
            receiptNumber: goodsReceived.receiptNumber,
          })
          .from(goodsReceivedLines)
          .innerJoin(
            goodsReceived,
            eq(
              goodsReceivedLines.goodsReceivedId,
              goodsReceived.goodsReceivedId,
            ),
          )
          .where(eq(goodsReceivedLines.goodsReceivedLineId, lineDto.lineId))
          .limit(1);

        if (!grLine)
          throw new NotFoundException(`Line ${lineDto.lineId} not found`);
        if (grLine.line.matchStatus !== 'matched') {
          throw new BadRequestException(
            `Cannot putaway unmatched line: ${lineDto.lineId}`,
          );
        }
        if (grLine.line.putawayStatus === 'completed') {
          throw new BadRequestException(
            `Line ${lineDto.lineId} is already putaway`,
          );
        }

        const sourceBinCode =
          grLine.line.putawayStatus === 'quarantined'
            ? 'QUARANTINE'
            : 'RECEIVING';

        const [sourceBin] = await tx
          .select({ binId: bins.binId })
          .from(bins)
          .innerJoin(zones, eq(bins.zoneId, zones.zoneId))
          .where(
            and(
              eq(zones.locationId, grLine.locationId),
              eq(bins.binNumber, sourceBinCode),
            ),
          )
          .limit(1);

        if (!sourceBin) {
          throw new BadRequestException(
            `Source bin ${sourceBinCode} not found for line ${lineDto.lineId}`,
          );
        }

        const qty = parseFloat(lineDto.quantity);

        const movements: any[] = [
          {
            productId: grLine.line.productId,
            binId: sourceBin.binId,
            quantity: -qty,
          },
          {
            productId: grLine.line.productId,
            binId: lineDto.destinationBinId,
            quantity: qty,
          },
        ];

        // Handle discrepancies if newTotalQuantity is provided
        if (lineDto.newTotalQuantity !== undefined) {
          const newTotal = parseFloat(lineDto.newTotalQuantity);

          const [destBinContent] = await tx
            .select({ actualQuantity: binContents.actualQuantity })
            .from(binContents)
            .where(
              and(
                eq(binContents.productId, grLine.line.productId),
                eq(binContents.binId, lineDto.destinationBinId),
              ),
            )
            .limit(1);

          const currentDbQty = destBinContent
            ? parseFloat(destBinContent.actualQuantity)
            : 0;
          const expectedTotal = currentDbQty + qty;

          const discrepancy = newTotal - expectedTotal;

          if (Math.abs(discrepancy) > 0.001) {
            movements.push({
              productId: grLine.line.productId,
              binId: lineDto.destinationBinId,
              quantity: discrepancy,
            });
            this.logger.warn(
              `Putaway discrepancy adjustment created. Expected: ${expectedTotal}, Counted: ${newTotal}, Adj: ${discrepancy}`,
            );
          }
        }

        await this.inventoryService.recordInventoryMovement(tx, {
          entryNumber: `PUT-${grLine.receiptNumber}-${grLine.line.goodsReceivedLineId.substring(0, 4)}`,
          sourceType: 'PO_RECEIPT',
          sourceId: grLine.line.goodsReceivedId,
          memo: `Putaway to ${lineDto.destinationBinId}`,
          userId,
          lines: movements,
        });

        await tx
          .update(goodsReceivedLines)
          .set({ putawayStatus: 'completed' })
          .where(eq(goodsReceivedLines.goodsReceivedLineId, lineDto.lineId));
      }

      return { success: true };
    });
  }
  private async changeBackorderState(
    backorderId: string,
    newState: BackorderState,
    actor: string,
    tx: DrizzleDB,
  ) {
    const [existing] = await tx
      .select({
        stateCode: backorders.stateCode,
        salesOrderId: backorders.salesOrderId,
      })
      .from(backorders)
      .where(eq(backorders.backorderId, backorderId))
      .limit(1);

    if (!existing) return;
    if (existing.stateCode === newState) return;

    const allowed = BACKORDER_TRANSITIONS[existing.stateCode] || [];
    if (!allowed.includes(newState)) {
      throw new BadRequestException(
        `Invalid backorder transition: ${existing.stateCode} -> ${newState}`,
      );
    }

    await tx
      .update(backorders)
      .set({ stateCode: newState as any, modifiedOn: new Date() })
      .where(eq(backorders.backorderId, backorderId));

    await emitEvent(tx, {
      aggregateType: AggregateType.SALES_ORDER,
      aggregateId: existing.salesOrderId,
      eventType: EventType.STATUS_CHANGED,
      payload: {
        entity: 'backorder',
        entityId: backorderId,
        from: existing.stateCode,
        to: newState,
      },
      actor,
    });
  }

  private async changePurchaseOrderState(
    poId: string,
    newState: PurchaseOrderState,
    actor: string,
    tx: DrizzleDB,
  ) {
    const [existing] = await tx
      .select({ stateCode: purchaseOrders.stateCode })
      .from(purchaseOrders)
      .where(eq(purchaseOrders.purchaseOrderId, poId))
      .limit(1);

    if (!existing) return;
    if (existing.stateCode === newState) return;

    const allowed =
      PURCHASE_ORDER_TRANSITIONS[existing.stateCode as string] || [];
    if (!allowed.includes(newState)) {
      throw new BadRequestException(
        `Invalid PO transition: ${existing.stateCode} -> ${newState}`,
      );
    }

    await tx
      .update(purchaseOrders)
      .set({ stateCode: newState as any, modifiedOn: new Date() })
      .where(eq(purchaseOrders.purchaseOrderId, poId));

    await emitEvent(tx, {
      aggregateType: AggregateType.PURCHASE_ORDER,
      aggregateId: poId,
      eventType: EventType.STATUS_CHANGED,
      payload: { from: existing.stateCode, to: newState },
      actor,
    });
  }
}

import { randomUUID } from 'crypto';
import {
  Injectable,
  Inject,
  BadRequestException,
  Logger,
  NotFoundException,
} from '@nestjs/common';
import { eq, sql, desc, and, inArray, gte, or } from 'drizzle-orm';
import { DRIZZLE } from '../drizzle/drizzle.module';
import type { DrizzleDB } from '../drizzle/drizzle.module';
import {
  purchaseOrders,
  purchaseInvoices,
  purchaseInvoiceLines,
  purchaseOrderLineItems,
  outbox,
  purchaseOrderEvents,
  suppliers,
  supplierGroups,
  products as coreProducts,
  productGroups,
  glAccounts,
  goodsReceivedLines,
  purchaseInvoiceReceipts,
  systemEvents,
} from '../drizzle/modbm-core-schema';
import { emitEvent } from '../common/emit-event';
import { AggregateType, EventType } from '../common/event-types';
import { GlService } from '../gl/gl.service';
import { evaluatePOLifecycleRules } from '../purchase-orders/purchase-order-lifecycle-rules';
import { TaxCategoriesService } from '../tax/tax-categories.service';
import { AppConfigService } from '../settings/app-config.service';
import {
  computeLinePriceForStorage,
  EXPENSE_ROUTING_PRECEDENCE,
  PURCHASE_INVOICE_STATE,
  PURCHASE_INVOICE_TRANSITIONS,
  getValidStates,
} from '@modbm/shared';

const VALID_INVOICE_STATES = getValidStates(PURCHASE_INVOICE_TRANSITIONS);
import { CreateStandaloneInvoiceDto } from './dto';

@Injectable()
export class PurchaseInvoiceService {
  private readonly logger = new Logger(PurchaseInvoiceService.name);

  constructor(
    @Inject(DRIZZLE) private readonly db: DrizzleDB,
    private readonly glService: GlService,
    private readonly taxService: TaxCategoriesService,
    private readonly appConfig: AppConfigService,
  ) {}

  /**
   * Generates a structural sequence number for the internal AP bill record natively in ModBM.
   */
  private async generateBillNumber(): Promise<string> {
    const today = new Date().toISOString().slice(0, 10).replace(/-/g, '');
    const prefix = `BILL-${today}-`;

    const result = await this.db
      .select({ invoiceNumber: purchaseInvoices.invoiceNumber })
      .from(purchaseInvoices)
      .where(sql`${purchaseInvoices.invoiceNumber} LIKE ${prefix + '%'}`)
      .orderBy(sql`${purchaseInvoices.invoiceNumber} DESC`)
      .limit(1);

    const seq =
      result.length > 0
        ? parseInt(result[0].invoiceNumber.replace(prefix, ''), 10) + 1
        : 1;

    return `${prefix}${String(seq).padStart(4, '0')}`;
  }

  /**
   * Fetch a specific ModBM AP Bill with natively populated mappings structurally
   */
  async findOne(invoiceId: string, tx?: DrizzleDB) {
    const db = tx || this.db;
    const rows = await db
      .select({
        invoice: purchaseInvoices,
        vendorName: suppliers.name,
      })
      .from(purchaseInvoices)
      .leftJoin(suppliers, eq(purchaseInvoices.vendorId, suppliers.vendorId))
      .where(eq(purchaseInvoices.invoiceId, invoiceId))
      .limit(1);

    if (rows.length === 0) {
      throw new NotFoundException(`Bill '${invoiceId}' not found directly.`);
    }

    const invoiceEntity = rows[0].invoice || rows[0];
    const invoice = { ...invoiceEntity, vendorName: rows[0].vendorName };

    // Hydrate explicitly native ModBM line mapping structurally
    const lines = await db
      .select({
        lineId: purchaseInvoiceLines.invoiceLineId,
        matchStatus: purchaseInvoiceLines.matchStatus,
        description: purchaseInvoiceLines.description,
        quantityInvoiced: purchaseInvoiceLines.quantityInvoiced,
        pricePerUnit: purchaseInvoiceLines.pricePerUnit,
        amount: purchaseInvoiceLines.amount,
        productId: purchaseInvoiceLines.productId,
        productNumber: coreProducts.productNumber,
        glAccountId: purchaseInvoiceLines.glAccountId,
        purchaseOrderId: purchaseOrderLineItems.purchaseOrderId,
        purchaseOrderNumber: purchaseOrders.orderNumber,
        purchaseOrderLineId: purchaseInvoiceLines.purchaseOrderLineId,
        goodsReceivedLineId: purchaseInvoiceReceipts.goodsReceivedLineId,
        quantityBilled: purchaseInvoiceReceipts.quantityBilled,
        poLineQuantityOrdered: purchaseOrderLineItems.quantity,
        poLineQuantityReceived: purchaseOrderLineItems.quantityReceived,
        poLinePricePerUnit: purchaseOrderLineItems.pricePerUnit,
      })
      .from(purchaseInvoiceLines)
      .leftJoin(
        purchaseOrderLineItems,
        eq(
          purchaseInvoiceLines.purchaseOrderLineId,
          purchaseOrderLineItems.purchaseOrderLineId,
        ),
      )
      .leftJoin(
        purchaseOrders,
        eq(
          purchaseOrderLineItems.purchaseOrderId,
          purchaseOrders.purchaseOrderId,
        ),
      )
      .leftJoin(
        coreProducts,
        eq(purchaseInvoiceLines.productId, coreProducts.productId),
      )
      .leftJoin(
        purchaseInvoiceReceipts,
        eq(
          purchaseInvoiceLines.invoiceLineId,
          purchaseInvoiceReceipts.invoiceLineId,
        ),
      )
      .where(eq(purchaseInvoiceLines.invoiceId, invoiceId));

    return { ...invoice, lines };
  }

  /**
   * Fetch all Native ModBM Bills strictly tied to a distinct active purchase order.
   * Finds any invoice that has lines matched to the purchase order.
   */
  async findByOrder(purchaseOrderId: string) {
    const linesRows = await this.db
      .select({
        invoiceId: purchaseInvoiceLines.invoiceId,
      })
      .from(purchaseInvoiceLines)
      .innerJoin(
        purchaseOrderLineItems,
        eq(
          purchaseInvoiceLines.purchaseOrderLineId,
          purchaseOrderLineItems.purchaseOrderLineId,
        ),
      )
      .where(eq(purchaseOrderLineItems.purchaseOrderId, purchaseOrderId));

    const matchedInvoiceIds = [
      ...new Set(linesRows.map((r) => r.invoiceId).filter(Boolean)),
    ];

    if (matchedInvoiceIds.length === 0) return [];

    const invoices = await this.db
      .select()
      .from(purchaseInvoices)
      .where(
        sql`${purchaseInvoices.invoiceId} IN (${sql.join(
          matchedInvoiceIds.map((id) => sql`${id}`),
          sql`, `,
        )})`,
      )
      .orderBy(desc(purchaseInvoices.createdOn));

    if (invoices.length === 0) return [];

    const invoiceIds = invoices.map((i) => i.invoiceId);
    if (invoiceIds.length > 0) {
      const allLines = await this.db
        .select({
          lineId: purchaseInvoiceLines.invoiceLineId,
          invoiceId: purchaseInvoiceLines.invoiceId,
          purchaseOrderLineId: purchaseInvoiceLines.purchaseOrderLineId,
          quantityInvoiced: purchaseInvoiceLines.quantityInvoiced,
          pricePerUnit: purchaseInvoiceLines.pricePerUnit,
          amount: purchaseInvoiceLines.amount,
          productId: purchaseInvoiceLines.productId,
          productNumber: coreProducts.productNumber,
          description: purchaseInvoiceLines.description,
          poLineDescription: purchaseOrderLineItems.productDescription,
          purchaseOrderId: purchaseOrderLineItems.purchaseOrderId,
          purchaseOrderNumber: purchaseOrders.orderNumber,
        })
        .from(purchaseInvoiceLines)
        .leftJoin(
          purchaseOrderLineItems,
          eq(
            purchaseInvoiceLines.purchaseOrderLineId,
            purchaseOrderLineItems.purchaseOrderLineId,
          ),
        )
        .leftJoin(
          purchaseOrders,
          eq(
            purchaseOrderLineItems.purchaseOrderId,
            purchaseOrders.purchaseOrderId,
          ),
        )
        .leftJoin(
          coreProducts,
          eq(purchaseInvoiceLines.productId, coreProducts.productId),
        )
        .where(
          sql`${purchaseInvoiceLines.invoiceId} IN (${sql.join(
            invoiceIds.map((id) => sql`${id}`),
            sql`, `,
          )})`,
        );

      const groupedLines = new Map<string, any[]>();
      for (const line of allLines) {
        if (!groupedLines.has(line.invoiceId)) {
          groupedLines.set(line.invoiceId, []);
        }
        groupedLines.get(line.invoiceId)!.push(line);
      }

      return invoices.map((inv) => ({
        ...inv,
        lines: groupedLines.get(inv.invoiceId) || [],
      }));
    }

    return invoices;
  }
  /**
   * Creates a standalone draft Purchase Invoice.
   */
  async createDraftInvoice(
    dto: CreateStandaloneInvoiceDto,
    actor: string,
  ): Promise<any> {
    const internalBillNumber = await this.generateBillNumber();

    return this.db.transaction(async (tx: DrizzleDB) => {
      const [invoice] = await tx
        .insert(purchaseInvoices)
        .values({
          invoiceNumber: internalBillNumber,
          vendorId: dto.vendorId,
          supplierInvoiceNumber: dto.supplierInvoiceNumber,
          totalAmount: String(dto.totalAmount),
          outstandingAmount: String(dto.totalAmount),
          taxAmount: String(dto.taxAmount),
          receiptFilename: dto.receiptFilename,
          currencyCode: dto.currencyCode,
          stateCode: PURCHASE_INVOICE_STATE.DRAFT,
          notes: dto.notes,
          purchaseOrderId: dto.purchaseOrderId,
          createdBy: actor,
        })
        .returning();

      if (dto.lines && dto.lines.length > 0) {
        const linesToInsert = dto.lines.map((l: any) => {
          const qty = parseFloat(l.quantityInvoiced || '0');
          const price = parseFloat(l.pricePerUnit || '0');
          const pricing = computeLinePriceForStorage({
            quantity: qty,
            pricePerUnit: price,
          });
          return {
            invoiceLineId: randomUUID(),
            invoiceId: invoice.invoiceId,
            description: l.description,
            productId: l.productId,
            glAccountId: l.glAccountId,
            quantityInvoiced: String(qty),
            pricePerUnit: String(price),
            amount: pricing.amount,
            purchaseOrderLineId: l.purchaseOrderLineId,
            matchStatus: l.purchaseOrderLineId ? 'matched' : 'unmatched',
          };
        });

        await tx.insert(purchaseInvoiceLines).values(linesToInsert);
      }

      await emitEvent(tx as any, {
        aggregateType: AggregateType.PURCHASE_INVOICE,
        aggregateId: invoice.invoiceId,
        eventType: 'status_changed',
        payload: {
          entity: 'purchase_invoice',
          entityId: invoice.invoiceId,
          from: null,
          to: PURCHASE_INVOICE_STATE.DRAFT,
        },
        actor,
      });

      return invoice;
    });
  }

  private async recalculateInvoiceTotals(invoiceId: string, tx: any) {
    const lines = await tx
      .select({ amount: purchaseInvoiceLines.amount })
      .from(purchaseInvoiceLines)
      .where(eq(purchaseInvoiceLines.invoiceId, invoiceId));

    let lineTotal = 0;
    for (const line of lines) {
      lineTotal += parseFloat(line.amount || '0');
    }

    const [invoice] = await tx
      .select()
      .from(purchaseInvoices)
      .where(eq(purchaseInvoices.invoiceId, invoiceId));

    const taxAmt = parseFloat(invoice.taxAmount || '0');
    const newTotal = lineTotal + taxAmt;

    await tx
      .update(purchaseInvoices)
      .set({
        totalAmount: newTotal.toFixed(2),
        outstandingAmount: newTotal.toFixed(2),
      })
      .where(eq(purchaseInvoices.invoiceId, invoiceId));
  }

  async updateInvoice(invoiceId: string, dto: any, actor: string) {
    return this.db.transaction(async (tx) => {
      const [invoice] = await tx
        .select()
        .from(purchaseInvoices)
        .where(eq(purchaseInvoices.invoiceId, invoiceId));
      if (!invoice) throw new NotFoundException('Invoice not found');
      if (invoice.stateCode !== PURCHASE_INVOICE_STATE.DRAFT)
        throw new BadRequestException('Only draft invoices can be updated');

      const updateData: any = {};
      if (dto.supplierInvoiceNumber !== undefined)
        updateData.supplierInvoiceNumber = dto.supplierInvoiceNumber;
      if (dto.receiptFilename !== undefined)
        updateData.receiptFilename = dto.receiptFilename;
      if (dto.notes !== undefined) updateData.notes = dto.notes;
      if (dto.taxAmount !== undefined) updateData.taxAmount = dto.taxAmount;
      if (dto.currencyCode !== undefined)
        updateData.currencyCode = dto.currencyCode;
      if (dto.vendorId !== undefined) updateData.vendorId = dto.vendorId;

      if (Object.keys(updateData).length > 0) {
        await tx
          .update(purchaseInvoices)
          .set(updateData)
          .where(eq(purchaseInvoices.invoiceId, invoiceId));

        if (updateData.taxAmount !== undefined) {
          await this.recalculateInvoiceTotals(invoiceId, tx);
        }
      }

      return this.findOne(invoiceId);
    });
  }

  async updateLine(invoiceId: string, lineId: string, dto: any, actor: string) {
    return this.db.transaction(async (tx) => {
      const [invoice] = await tx
        .select()
        .from(purchaseInvoices)
        .where(eq(purchaseInvoices.invoiceId, invoiceId));
      if (!invoice) throw new NotFoundException('Invoice not found');
      if (invoice.stateCode !== PURCHASE_INVOICE_STATE.DRAFT)
        throw new BadRequestException(
          'Only draft invoice lines can be updated',
        );

      const [line] = await tx
        .select()
        .from(purchaseInvoiceLines)
        .where(eq(purchaseInvoiceLines.invoiceLineId, lineId));
      if (!line) throw new NotFoundException('Line not found');

      const updateData: any = {};
      if (dto.description !== undefined)
        updateData.description = dto.description;
      if (dto.glAccountId !== undefined)
        updateData.glAccountId = dto.glAccountId;
      if (dto.productId !== undefined) updateData.productId = dto.productId;

      let qty = parseFloat(line.quantityInvoiced);
      let price = parseFloat(line.pricePerUnit);

      if (dto.quantityInvoiced !== undefined) {
        updateData.quantityInvoiced = String(dto.quantityInvoiced);
        qty = parseFloat(dto.quantityInvoiced);
      }
      if (dto.pricePerUnit !== undefined) {
        updateData.pricePerUnit = String(dto.pricePerUnit);
        price = parseFloat(dto.pricePerUnit);
      }

      if (
        dto.quantityInvoiced !== undefined ||
        dto.pricePerUnit !== undefined
      ) {
        const pricing = computeLinePriceForStorage({
          quantity: qty,
          pricePerUnit: price,
        });
        updateData.amount = pricing.amount;
      }

      await tx
        .update(purchaseInvoiceLines)
        .set(updateData)
        .where(eq(purchaseInvoiceLines.invoiceLineId, lineId));

      if (updateData.amount !== undefined) {
        await this.recalculateInvoiceTotals(invoiceId, tx);
      }

      return { success: true };
    });
  }

  async removeLine(invoiceId: string, lineId: string, actor: string) {
    return this.db.transaction(async (tx) => {
      const [invoice] = await tx
        .select()
        .from(purchaseInvoices)
        .where(eq(purchaseInvoices.invoiceId, invoiceId));
      if (!invoice) throw new NotFoundException('Invoice not found');
      if (invoice.stateCode !== PURCHASE_INVOICE_STATE.DRAFT)
        throw new BadRequestException(
          'Only draft invoice lines can be removed',
        );

      await tx
        .delete(purchaseInvoiceLines)
        .where(eq(purchaseInvoiceLines.invoiceLineId, lineId));

      await this.recalculateInvoiceTotals(invoiceId, tx);

      return { success: true };
    });
  }

  async addLine(invoiceId: string, dto: any, actor: string) {
    return this.db.transaction(async (tx) => {
      const [invoice] = await tx
        .select()
        .from(purchaseInvoices)
        .where(eq(purchaseInvoices.invoiceId, invoiceId));
      if (!invoice) throw new NotFoundException('Invoice not found');
      if (invoice.stateCode !== PURCHASE_INVOICE_STATE.DRAFT)
        throw new BadRequestException('Only draft invoice lines can be added');

      const qty = parseFloat(dto.quantityInvoiced || '1');
      const price = parseFloat(dto.pricePerUnit || '0');
      const pricing = computeLinePriceForStorage({
        quantity: qty,
        pricePerUnit: price,
      });

      let defaultGlAccountId = dto.glAccountId || null;
      if (!defaultGlAccountId) {
        const settings = await this.glService.getSettings();
        if (settings?.defaultExpenseAccountId) {
          defaultGlAccountId = settings.defaultExpenseAccountId;
        } else {
          // Fallback to the first expense account if no default is configured
          const fallbackRows = await tx
            .select({ id: glAccounts.glAccountId })
            .from(glAccounts)
            .where(eq(glAccounts.accountType, 'expense'))
            .limit(1);
          if (fallbackRows.length > 0) {
            defaultGlAccountId = fallbackRows[0].id;
          }
        }
      }

      await tx.insert(purchaseInvoiceLines).values({
        invoiceLineId: randomUUID(),
        invoiceId,
        description: dto.description || '',
        productId: dto.productId || null,
        glAccountId: defaultGlAccountId,
        quantityInvoiced: String(qty),
        pricePerUnit: String(price),
        amount: pricing.amount,
        matchStatus: 'unmatched',
      });

      await this.recalculateInvoiceTotals(invoiceId, tx);

      return { success: true };
    });
  }

  /**
   * Posts a draft invoice, validates totals, and creates the GL entries.
   */
  async postInvoice(invoiceId: string, actor: string): Promise<any> {
    const [invoice] = await this.db
      .select()
      .from(purchaseInvoices)
      .where(eq(purchaseInvoices.invoiceId, invoiceId));
    if (!invoice) throw new NotFoundException('Invoice not found');
    if (invoice.stateCode !== PURCHASE_INVOICE_STATE.DRAFT)
      throw new BadRequestException('Only draft invoices can be posted');

    const lines = await this.db
      .select({
        line: purchaseInvoiceLines,
        poProductId: purchaseOrderLineItems.productId,
      })
      .from(purchaseInvoiceLines)
      .leftJoin(
        purchaseOrderLineItems,
        eq(
          purchaseInvoiceLines.purchaseOrderLineId,
          purchaseOrderLineItems.purchaseOrderLineId,
        ),
      )
      .where(eq(purchaseInvoiceLines.invoiceId, invoiceId));

    let lineTotal = 0;
    const expenseByAccountId = new Map<string, number>();
    let defaultExpense = 0;
    let grniExpense = 0;

    for (const { line, poProductId } of lines) {
      if (line.matchStatus !== 'matched' && !line.glAccountId) {
        throw new BadRequestException(
          `Line "${line.description}" is unmatched and must have a GL Account assigned before finalisation.`,
        );
      }

      const amt = parseFloat(line.amount);
      lineTotal += amt;

      const acctId = line.glAccountId;
      if (acctId) {
        const current = expenseByAccountId.get(acctId) || 0;
        expenseByAccountId.set(acctId, current + amt);
      } else if (line.matchStatus === 'matched' && poProductId) {
        grniExpense += amt;
      } else {
        defaultExpense += amt;
      }
    }

    const headerTotal = parseFloat(invoice.totalAmount || '0');
    const taxAmount = parseFloat(invoice.taxAmount || '0');
    const expectedHeader = lineTotal + taxAmount;

    if (Math.abs(expectedHeader - headerTotal) > 0.01) {
      throw new BadRequestException(
        `Invoice totals mismatch. Header: ${headerTotal.toFixed(2)}, Lines+Tax: ${expectedHeader.toFixed(2)}`,
      );
    }

    // Verify Vendor default AP / Expense Accounts + Dimensions
    const [supp] = await this.db
      .select({
        vendorId: suppliers.vendorId,
        defaultApAccountId: supplierGroups.defaultApAccountId,
        defaultExpenseAccountId: supplierGroups.defaultExpenseAccountId,
        supplierCostCenterId: supplierGroups.defaultCostCenterId,
        supplierActivityId: supplierGroups.defaultActivityId,
      })
      .from(suppliers)
      .leftJoin(
        supplierGroups,
        eq(suppliers.supplierGroupId, supplierGroups.supplierGroupId),
      )
      .where(eq(suppliers.vendorId, invoice.vendorId));
    const supplierApAccountId = supp?.defaultApAccountId;
    const supplierExpenseAccountId = supp?.defaultExpenseAccountId;
    const supplierCostCenterId = supp?.supplierCostCenterId || null;
    const supplierActivityId = supp?.supplierActivityId || null;

    // GL Posting + State Update (atomic transaction)
    const updatedInvoice = await this.db.transaction(async (tx: DrizzleDB) => {
      const settings = await this.glService.getSettings();
      const effectiveApAccountId =
        supplierApAccountId || settings?.defaultApAccountId;

      if (effectiveApAccountId) {
        const distinctAccountIds = new Set<string>();
        distinctAccountIds.add(effectiveApAccountId);
        if (settings?.defaultTaxAccountId)
          distinctAccountIds.add(settings.defaultTaxAccountId);
        if (settings?.defaultExpenseAccountId)
          distinctAccountIds.add(settings.defaultExpenseAccountId);
        if (settings?.defaultGrniAccountId)
          distinctAccountIds.add(settings.defaultGrniAccountId);
        if (supplierExpenseAccountId)
          distinctAccountIds.add(supplierExpenseAccountId);
        for (const acctId of expenseByAccountId.keys())
          distinctAccountIds.add(acctId);

        const settingsIds = Array.from(distinctAccountIds).filter(Boolean);

        if (settingsIds.length > 0) {
          const acctRows = await tx
            .select({
              glAccountId: glAccounts.glAccountId,
              accountCode: glAccounts.accountCode,
            })
            .from(glAccounts)
            .where(inArray(glAccounts.glAccountId, settingsIds));

          const idToCode = new Map(
            acctRows.map((a) => [a.glAccountId, a.accountCode]),
          );

          const apCode = idToCode.get(effectiveApAccountId);
          // If no specific line expense, fallback to supplier's default expense, or system default
          const fallbackExpCode =
            (supplierExpenseAccountId &&
              idToCode.get(supplierExpenseAccountId)) ||
            (settings.defaultExpenseAccountId &&
              idToCode.get(settings.defaultExpenseAccountId));

          // In perpetual mode, matched inventory lines clear the GRNI liability.
          // In periodic mode, matched lines are treated as direct expenses.
          const isPerpetual =
            this.appConfig.inventoryAccountingMode() === 'perpetual';
          const grniCode =
            isPerpetual && settings.defaultGrniAccountId
              ? idToCode.get(settings.defaultGrniAccountId)
              : fallbackExpCode; // Periodic: route through expense

          const taxCode = settings.defaultTaxAccountId
            ? idToCode.get(settings.defaultTaxAccountId)
            : null;

          if (apCode) {
            const glLines: any[] = [];

            if (defaultExpense > 0 && fallbackExpCode) {
              glLines.push({
                accountCode: fallbackExpCode,
                debit: defaultExpense,
                credit: 0,
                memo: `Expense (Default): ${invoice.invoiceNumber}`,
                costCenterId: supplierCostCenterId || undefined,
                activityId: supplierActivityId || undefined,
              });
            }

            if (grniExpense > 0 && grniCode) {
              glLines.push({
                accountCode: grniCode,
                debit: grniExpense,
                credit: 0,
                memo: `GRNI Clearance: ${invoice.invoiceNumber}`,
                partyId: invoice.vendorId,
                partyType: 'supplier',
                costCenterId: supplierCostCenterId || undefined,
                activityId: supplierActivityId || undefined,
              });
            }

            for (const [acctId, amount] of expenseByAccountId.entries()) {
              const code = idToCode.get(acctId);
              if (code && amount > 0) {
                glLines.push({
                  accountCode: code,
                  debit: amount,
                  credit: 0,
                  memo: `Expense: ${invoice.invoiceNumber}`,
                  costCenterId: supplierCostCenterId || undefined,
                  activityId: supplierActivityId || undefined,
                });
              }
            }

            if (taxCode && taxAmount > 0) {
              glLines.push({
                accountCode: taxCode,
                debit: taxAmount,
                credit: 0,
                memo: `Tax: ${invoice.invoiceNumber}`,
              });
            }

            // AP Credit
            const totalDebits = glLines.reduce((sum, l) => sum + l.debit, 0);
            glLines.push({
              accountCode: apCode,
              debit: 0,
              credit: totalDebits,
              memo: `Accounts Payable: ${invoice.invoiceNumber}`,
              partyId: invoice.vendorId,
              partyType: 'supplier',
              costCenterId: supplierCostCenterId || undefined,
              activityId: supplierActivityId || undefined,
            });

            await this.glService.postJournalEntry(
              glLines,
              {
                sourceType: 'purchase_invoice',
                sourceId: invoice.invoiceId,
                memo: `Purchase Invoice ${invoice.invoiceNumber}`,
                actor,
              },
              tx,
            );
          }
        }
      }

      // Mark as invoiced (atomic with GL posting)
      await this.updateStateInternal(
        invoiceId,
        PURCHASE_INVOICE_STATE.INVOICED,
        actor,
        tx,
      );

      if (invoice.purchaseOrderId) {
        await evaluatePOLifecycleRules(
          tx,
          invoice.purchaseOrderId,
          { entity: 'purchase_invoice', action: 'posted' },
          actor,
        );
      }

      return this.findOne(invoiceId, tx);
    });

    // Trigger lifecycle rules for affected POs (non-fatal side effect)
    const affectedPoIds = [
      ...new Set(
        ((invoice as any).lines || [])
          .map((l: any) => l.purchaseOrderId)
          .filter(Boolean),
      ),
    ] as string[];

    for (const poId of affectedPoIds) {
      try {
        await evaluatePOLifecycleRules(
          this.db,
          poId,
          {
            entity: 'purchase_invoice',
            action: 'posted',
            id: invoiceId,
          },
          actor,
        );
      } catch (err) {
        this.logger.error(
          `Failed to evaluate PO lifecycle rules for PO ${poId} after invoice posting:`,
          err,
        );
      }
    }

    return updatedInvoice;
  }

  /**
   * Changes the state of a Purchase Invoice.
   * Handles draft -> cancelled, cancelled -> draft.
   * draft -> invoiced delegates to postInvoice.
   */
  async changePurchaseInvoiceState(
    invoiceId: string,
    newState: string,
    actor: string,
    discrepanciesAcknowledged?: boolean,
    tx?: DrizzleDB,
  ) {
    const fullInvoice = await this.findOne(invoiceId, tx);
    if (!fullInvoice) throw new NotFoundException('Invoice not found');
    const invoice = fullInvoice as any; // Full invoice with lines

    const allowed = PURCHASE_INVOICE_TRANSITIONS[invoice.stateCode] || [];
    if (!allowed.includes(newState)) {
      throw new BadRequestException(
        `Cannot transition invoice from ${invoice.stateCode} to ${newState}`,
      );
    }

    const db = tx || this.db;
    // Check for discrepancies on forward transition
    if (
      newState !== PURCHASE_INVOICE_STATE.DRAFT &&
      newState !== PURCHASE_INVOICE_STATE.CANCELLED
    ) {
      const discrepancies: any[] = [];
      invoice.lines.forEach((line: any, idx: number) => {
        if (
          line.matchStatus !== 'matched' &&
          !line.purchaseOrderLineId &&
          parseFloat(line.amount || '0') > 0
        ) {
          discrepancies.push({
            type: 'unplanned_line',
            message: `Line ${idx + 1} is unplanned.`,
          });
        }
        if (line.matchStatus === 'matched' && line.purchaseOrderLineId) {
          const billedQty = parseFloat(line.quantityInvoiced || '0');
          const poReceived = parseFloat(line.poLineQuantityReceived || '0');
          const billedPrice = parseFloat(line.pricePerUnit || '0');
          const poPrice = parseFloat(line.poLinePricePerUnit || '0');

          if (Math.abs(billedPrice - poPrice) > 0.001) {
            discrepancies.push({
              type: 'price_variance',
              message: `Line ${idx + 1} price variance.`,
            });
          }
          if (billedQty > poReceived) {
            discrepancies.push({
              type: 'quantity_variance',
              message: `Line ${idx + 1} quantity variance.`,
            });
          }
        }
      });

      if (discrepancies.length > 0) {
        if (!discrepanciesAcknowledged) {
          throw new BadRequestException('Unacknowledged discrepancies exist.');
        }

        // Log the approval of discrepancies
        await db.insert(systemEvents).values({
          eventType: 'invoice_discrepancy_approved',
          aggregateType: 'purchase_invoice',
          aggregateId: invoiceId,
          actor,
          payload: {
            discrepancies,
            purchaseOrderId: invoice.lines[0]?.purchaseOrderId,
          },
        });
      }
    }

    if (newState === PURCHASE_INVOICE_STATE.INVOICED) {
      return this.postInvoice(invoiceId, actor);
    }

    return this.updateStateInternal(invoiceId, newState, actor, tx);
  }

  /**
   * Allocates/matches an existing invoice line to a PO line.
   */
  async resolveInvoiceLine(
    invoiceLineId: string,
    purchaseOrderLineId: string,
    actor: string,
  ) {
    return this.db.transaction(async (tx) => {
      const [line] = await tx
        .select()
        .from(purchaseInvoiceLines)
        .where(eq(purchaseInvoiceLines.invoiceLineId, invoiceLineId));
      if (!line) throw new NotFoundException('Invoice line not found');

      const [poLine] = await tx
        .select()
        .from(purchaseOrderLineItems)
        .where(
          eq(purchaseOrderLineItems.purchaseOrderLineId, purchaseOrderLineId),
        );
      if (!poLine) throw new NotFoundException('PO line not found');

      await tx
        .update(purchaseInvoiceLines)
        .set({
          purchaseOrderLineId,
          productId: poLine.productId,
          matchStatus: 'matched',
        })
        .where(eq(purchaseInvoiceLines.invoiceLineId, invoiceLineId));

      await emitEvent(tx, {
        aggregateType: AggregateType.PURCHASE_ORDER,
        aggregateId: poLine.purchaseOrderId,
        eventType: EventType.INVOICE_MATCHED,
        actor,
        payload: {
          invoiceLineId,
          purchaseOrderLineId,
          invoiceId: line.invoiceId,
        },
      });

      return { success: true };
    });
  }

  /**
   * Auto-matches unbilled lines from a given PO to this invoice.
   */
  async autoMatchPurchaseOrder(
    invoiceId: string,
    purchaseOrderId: string,
    actor: string,
  ) {
    return this.db.transaction(async (tx) => {
      const [invoice] = await tx
        .select()
        .from(purchaseInvoices)
        .where(eq(purchaseInvoices.invoiceId, invoiceId));
      if (!invoice) throw new NotFoundException('Invoice not found');
      if (invoice.stateCode !== PURCHASE_INVOICE_STATE.DRAFT)
        throw new BadRequestException(
          'Only draft invoices can be auto-matched',
        );

      // 1. Fetch PO Lines
      const poLines = await tx
        .select()
        .from(purchaseOrderLineItems)
        .where(eq(purchaseOrderLineItems.purchaseOrderId, purchaseOrderId));

      // 2. Fetch existing unmatched invoice lines
      const invLines = await tx
        .select()
        .from(purchaseInvoiceLines)
        .where(eq(purchaseInvoiceLines.invoiceId, invoiceId));

      let matchedCount = 0;
      let addedCount = 0;

      for (const poLine of poLines) {
        // Find if we already have an unmatched invoice line for this product
        const match = invLines.find(
          (l) =>
            l.matchStatus === 'unmatched' && l.productId === poLine.productId,
        );

        if (match) {
          await tx
            .update(purchaseInvoiceLines)
            .set({
              purchaseOrderLineId: poLine.purchaseOrderLineId,
              matchStatus: 'matched',
            })
            .where(eq(purchaseInvoiceLines.invoiceLineId, match.invoiceLineId));
          match.matchStatus = 'matched'; // Prevent mapping to this line again
          matchedCount++;
        } else {
          // Add it as a new matched line
          const qty = parseFloat(poLine.quantity || '0');
          const price = parseFloat(poLine.pricePerUnit || '0');
          const pricing = computeLinePriceForStorage({
            quantity: qty,
            pricePerUnit: price,
          });

          await tx.insert(purchaseInvoiceLines).values({
            invoiceLineId: randomUUID(),
            invoiceId,
            description: poLine.productDescription || '',
            productId: poLine.productId,
            glAccountId: null,
            quantityInvoiced: String(qty),
            pricePerUnit: String(price),
            amount: pricing.amount,
            purchaseOrderLineId: poLine.purchaseOrderLineId,
            matchStatus: 'matched',
          });
          addedCount++;
        }
      }

      await this.recalculateInvoiceTotals(invoiceId, tx);

      if (matchedCount > 0 || addedCount > 0) {
        await emitEvent(tx, {
          aggregateType: AggregateType.PURCHASE_ORDER,
          aggregateId: purchaseOrderId,
          eventType: EventType.INVOICE_MATCHED,
          actor,
          payload: {
            invoiceId,
            matchedCount,
            addedCount,
          },
        });
      }

      return { success: true, matchedCount, addedCount };
    });
  }

  /**
   * Un-matches an invoice line.
   */
  async unresolveInvoiceLine(invoiceLineId: string, actor: string) {
    return this.db.transaction(async (tx) => {
      const [line] = await tx
        .select({
          invoiceId: purchaseInvoiceLines.invoiceId,
          purchaseOrderLineId: purchaseInvoiceLines.purchaseOrderLineId,
        })
        .from(purchaseInvoiceLines)
        .where(eq(purchaseInvoiceLines.invoiceLineId, invoiceLineId));

      if (!line) throw new NotFoundException('Invoice line not found');

      let poId: string | null = null;
      if (line.purchaseOrderLineId) {
        const [poLine] = await tx
          .select({ purchaseOrderId: purchaseOrderLineItems.purchaseOrderId })
          .from(purchaseOrderLineItems)
          .where(
            eq(
              purchaseOrderLineItems.purchaseOrderLineId,
              line.purchaseOrderLineId,
            ),
          );
        if (poLine) poId = poLine.purchaseOrderId;
      }

      await tx
        .update(purchaseInvoiceLines)
        .set({
          purchaseOrderLineId: null,
          matchStatus: 'unmatched',
        })
        .where(eq(purchaseInvoiceLines.invoiceLineId, invoiceLineId));

      if (poId) {
        await emitEvent(tx, {
          aggregateType: AggregateType.PURCHASE_ORDER,
          aggregateId: poId,
          eventType: EventType.INVOICE_UNMATCHED,
          actor,
          payload: {
            invoiceLineId,
            invoiceId: line.invoiceId,
          },
        });
      }

      return { success: true };
    });
  }

  /**
   * Fetch a flattened, global list of Purchase Invoices spanning multiple orders.
   * Useful for the "All Invoices" page and Account Detail tabs.
   */
  async findActiveInvoices(query: {
    days?: number;
    vendorId?: string;
    invoiceId?: string;
    limit?: number;
  }) {
    const { days = 30, vendorId, invoiceId, limit = 100 } = query;

    const conditions: any[] = [];

    // When filtering by specific invoiceId, skip the date range filter
    if (invoiceId) {
      conditions.push(eq(purchaseInvoices.invoiceId, invoiceId));
    } else if (days > 0) {
      const cutoffDate = new Date();
      cutoffDate.setDate(cutoffDate.getDate() - days);
      conditions.push(gte(purchaseInvoices.createdOn, cutoffDate));
    }

    if (vendorId) {
      conditions.push(
        or(
          eq(purchaseInvoices.vendorId, vendorId),
          eq(suppliers.externalId, vendorId),
        ),
      );
    }

    const dataQuery = this.db
      .select({
        invoiceId: purchaseInvoices.invoiceId,
        invoiceNumber: purchaseInvoices.invoiceNumber,
        vendorId: purchaseInvoices.vendorId,
        vendorName: suppliers.name,
        supplierInvoiceNumber: purchaseInvoices.supplierInvoiceNumber,
        totalAmount: purchaseInvoices.totalAmount,
        taxAmount: purchaseInvoices.taxAmount,
        currencyCode: purchaseInvoices.currencyCode,
        stateCode: purchaseInvoices.stateCode,
        createdOn: purchaseInvoices.createdOn,
      })
      .from(purchaseInvoices)
      .leftJoin(suppliers, eq(purchaseInvoices.vendorId, suppliers.vendorId))
      .where(and(...conditions))
      .orderBy(desc(purchaseInvoices.createdOn));

    if (limit > 0) {
      return await dataQuery.limit(limit);
    }
    return await dataQuery;
  }

  private async updateStateInternal(
    invoiceId: string,
    newState: string,
    actor: string,
    tx?: DrizzleDB,
  ) {
    if (!VALID_INVOICE_STATES.includes(newState)) {
      throw new BadRequestException(`Invalid invoice state: '${newState}'`);
    }

    const db = tx || this.db;
    const [existing] = await db
      .select({
        stateCode: purchaseInvoices.stateCode,
        invoiceNumber: purchaseInvoices.invoiceNumber,
      })
      .from(purchaseInvoices)
      .where(eq(purchaseInvoices.invoiceId, invoiceId))
      .limit(1);

    if (!existing) {
      throw new NotFoundException(`Invoice ${invoiceId} not found`);
    }

    const allowed = PURCHASE_INVOICE_TRANSITIONS[existing.stateCode];
    if (!allowed || !allowed.includes(newState)) {
      throw new BadRequestException(
        `Cannot transition invoice from '${existing.stateCode}' to '${newState}'. Allowed transitions: ${allowed?.join(', ') || 'none'}`,
      );
    }

    const [updated] = await db
      .update(purchaseInvoices)
      .set({
        stateCode: newState as any,
        modifiedOn: new Date(),
      })
      .where(eq(purchaseInvoices.invoiceId, invoiceId))
      .returning();

    await emitEvent(db as any, {
      aggregateType: AggregateType.PURCHASE_INVOICE,
      aggregateId: invoiceId,
      eventType: 'status_changed',
      payload: {
        entity: 'purchase_invoice',
        entityId: invoiceId,
        invoiceNumber: existing.invoiceNumber,
        from: existing.stateCode,
        to: newState,
      },
      actor,
    });

    return updated;
  }
}

import {
  Injectable,
  Logger,
  HttpException,
  HttpStatus,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { Inject } from '@nestjs/common';
import { DRIZZLE } from '../drizzle/drizzle.module';
import type { DrizzleDB } from '../drizzle/drizzle.module';
import {
  salesOrders,
  salesOrderLineItems,
  backorders,
  purchaseOrders,
  purchaseOrderLineItems,
  productSuppliers,
  purchaseOrderEvents,
  products as coreProducts,
  orderEvents,
  suppliers as coreSuppliers,
  taxCategories,
  locations,
  transferOrders,
  transferOrderLines,
  transferOrderEvents,
} from '../drizzle/modbm-core-schema';
import { emitEvent } from '../common/emit-event';
import { AggregateType, EventType } from '../common/event-types';
