  async generatePOsFromDemands(payload: any, actor: string) {
    this.logger.log(
      `Manual PO Generation triggered by ${actor} for ${payload.pos?.length || 0} POs`,
    );

    if (!payload || !payload.pos || !Array.isArray(payload.pos)) {
      throw new HttpException(
        'Invalid payload structure',
        HttpStatus.BAD_REQUEST,
      );
    }

    await this.db.transaction(async (tx) => {
      // 1. Get fallback tax category
      const [defaultTaxCat] = await tx
        .select({ id: taxCategories.taxCategoryId })
        .from(taxCategories)
        .where(eq(taxCategories.isDefault, true))
        .limit(1);

      let fallbackTaxId = defaultTaxCat?.id;
      if (!fallbackTaxId) {
        const [firstCat] = await tx
          .select({ id: taxCategories.taxCategoryId })
          .from(taxCategories)
          .limit(1);
        fallbackTaxId = firstCat?.id;
      }

      for (const poPayload of payload.pos) {
        if (!poPayload.vendorId) {
          throw new HttpException(
            'Cannot generate a PO without a vendorId',
            HttpStatus.BAD_REQUEST,
          );
        }

        const currencyCode =
          poPayload.currencyCode || this.appConfig.homeCurrency();
        const orderNumber = await this.generatePurchaseOrderNumber(tx);

        const soNotes =
          poPayload.soNumbers && poPayload.soNumbers.length > 0
            ? `to fulfill open demands from: ${poPayload.soNumbers.join(', ')}`
            : 'to fulfill open demands';

        let deliveryLocationId =
          poPayload.deliveryLocationId ||
          this.appConfig.defaultFulfillmentLocationId();
        if (!deliveryLocationId) {
          const locs = await tx.execute(
            sql`SELECT location_id FROM modbm_core.locations LIMIT 1`,
          );
          deliveryLocationId = (locs as any)[0]?.location_id;
        }
        if (!deliveryLocationId) {
          throw new HttpException(
            'No locations configured',
            HttpStatus.INTERNAL_SERVER_ERROR,
          );
        }

        const [po] = await tx
          .insert(purchaseOrders)
          .values({
            orderNumber,
            name: `Requisition PO ${orderNumber}`,
            vendorId: poPayload.vendorId,
            deliveryLocationId: deliveryLocationId,
            stateCode: 'draft',
            currencyCode,
            notes: `Generated ${soNotes}`,
            createdBy: actor,
          })
          .returning();

        await emitEvent(tx, {
          aggregateType: AggregateType.PURCHASE_ORDER,
          aggregateId: po.purchaseOrderId,
          eventType: EventType.CREATED,
          actor,
          payload: { reason: 'manual_requisition' },
        });

        let openLineNumber = 1;
        for (const line of poPayload.lines) {
          const [coreProd] = await tx
            .select({
              name: coreProducts.name,
              purchaseTaxCategoryId: coreProducts.purchaseTaxCategoryId,
            })
            .from(coreProducts)
            .where(eq(coreProducts.productId, line.productId));

          const [poLine] = await tx
            .insert(purchaseOrderLineItems)
            .values({
              purchaseOrderId: po.purchaseOrderId,
              lineNumber: openLineNumber++,
              productId: line.productId,
              productDescription: coreProd?.name,
              quantity: line.quantity.toString(),
              pricePerUnit: line.pricePerUnit.toString(),
              taxCategoryId: coreProd?.purchaseTaxCategoryId || fallbackTaxId,
            })
            .returning();

          if (line.backorderIds && line.backorderIds.length > 0) {
            for (const backorderId of line.backorderIds) {
              await tx
                .update(backorders)
                .set({
                  purchaseOrderId: po.purchaseOrderId,
                  purchaseOrderLineId: poLine.purchaseOrderLineId,
                  modifiedOn: new Date(),
                })
                .where(eq(backorders.backorderId, backorderId));

              await this.changeBackorderState(
                backorderId,
                BACKORDER_STATE.AWAITING_RECEIPT,
                actor,
                tx,
              );
            }
          }
        }
      }
    });
  }

  /**
   * Returns open PO lines for a given product, calculating their available unallocated capacity.
   */
  async getAvailablePoLines(productId: string) {
    if (!productId) return [];

    const openPoLines = await this.db
      .select({
        purchaseOrderId: purchaseOrders.purchaseOrderId,
        purchaseOrderLineId: purchaseOrderLineItems.purchaseOrderLineId,
        orderNumber: purchaseOrders.orderNumber,
        stateCode: purchaseOrders.stateCode,
        quantity: purchaseOrderLineItems.quantity,
        vendorId: purchaseOrders.vendorId,
        vendorName: coreSuppliers.name,
        deliveryLocationId: purchaseOrders.deliveryLocationId,
        locationName: locations.name,
      })
      .from(purchaseOrderLineItems)
      .innerJoin(
        purchaseOrders,
        eq(
          purchaseOrderLineItems.purchaseOrderId,
          purchaseOrders.purchaseOrderId,
        ),
      )
      .leftJoin(
        coreSuppliers,
        eq(purchaseOrders.vendorId, coreSuppliers.vendorId),
      )
      .leftJoin(
        locations,
        eq(purchaseOrders.deliveryLocationId, locations.locationId),
      )
      .where(
        and(
          eq(purchaseOrderLineItems.productId, productId),
          inArray(purchaseOrders.stateCode, OPEN_PURCHASE_ORDER_STATES),
        ),
      );

    if (openPoLines.length === 0) return [];

    const poLineIds = openPoLines.map((l) => l.purchaseOrderLineId);

    // Get existing allocations
    const existingAllocations = await this.db
      .select({
        purchaseOrderLineId: backorders.purchaseOrderLineId,
        allocatedQty: sql<number>`SUM(${backorders.quantity}::numeric)`,
      })
      .from(backorders)
      .where(inArray(backorders.purchaseOrderLineId, poLineIds))
      .groupBy(backorders.purchaseOrderLineId);

    const allocationMap = new Map<string, number>();
    for (const a of existingAllocations) {
      if (a.purchaseOrderLineId) {
        allocationMap.set(a.purchaseOrderLineId, Number(a.allocatedQty));
      }
    }

    const availableLines = openPoLines
      .map((line) => {
        const allocated = allocationMap.get(line.purchaseOrderLineId) || 0;
        return {
          ...line,
          availableQty: Number(line.quantity) - allocated,
        };
      })
      .filter((line) => line.availableQty > 0);

    return availableLines;
  }

  /**
   * Manually links an open demand to a specific PO line. Splits the demand if necessary.
   */
  async linkDemandToPo(
    demandId: string,
    purchaseOrderLineId: string,
    quantityToLink: number,
    actor: string,
  ) {
    await this.db.transaction(async (tx) => {
      // 1. Get the demand
      const [demand] = await tx
        .select()
        .from(backorders)
        .where(eq(backorders.backorderId, demandId));

      if (!demand)
        throw new HttpException('Demand not found', HttpStatus.NOT_FOUND);
      if (demand.purchaseOrderId)
        throw new HttpException(
          'Demand is already linked',
          HttpStatus.BAD_REQUEST,
        );

      const demandQty = Number(demand.quantity);
      if (quantityToLink <= 0 || quantityToLink > demandQty) {
        throw new HttpException('Invalid quantity', HttpStatus.BAD_REQUEST);
      }

      // 2. Get the target PO line
      const [poLine] = await tx
        .select({
          purchaseOrderId: purchaseOrderLineItems.purchaseOrderId,
          quantity: purchaseOrderLineItems.quantity,
          productId: purchaseOrderLineItems.productId,
        })
        .from(purchaseOrderLineItems)
        .where(
          eq(purchaseOrderLineItems.purchaseOrderLineId, purchaseOrderLineId),
        );

      if (!poLine)
        throw new HttpException('PO line not found', HttpStatus.NOT_FOUND);
      if (poLine.productId !== demand.productId)
        throw new HttpException('Product mismatch', HttpStatus.BAD_REQUEST);

      // Verify capacity
      const [existingAlloc] = await tx
        .select({
          allocated: sql<number>`SUM(${backorders.quantity}::numeric)`,
        })
        .from(backorders)
        .where(eq(backorders.purchaseOrderLineId, purchaseOrderLineId));

      const allocated = Number(existingAlloc?.allocated || 0);
      const available = Number(poLine.quantity) - allocated;

      if (quantityToLink > available) {
        throw new HttpException(
          `Insufficient capacity on PO line. Available: ${available}`,
          HttpStatus.BAD_REQUEST,
        );
      }

      // 3. Link (and split if needed)
      if (quantityToLink < demandQty) {
        // Update current row to the allocated quantity
        await tx
          .update(backorders)
          .set({
            purchaseOrderId: poLine.purchaseOrderId,
            purchaseOrderLineId: purchaseOrderLineId,
            quantity: quantityToLink.toString(),
            modifiedOn: new Date(),
          })
          .where(eq(backorders.backorderId, demandId));

        await this.changeBackorderState(
          demandId,
          BACKORDER_STATE.AWAITING_RECEIPT,
          actor,
          tx,
        );

        // Create remaining demand
        const remainingQty = demandQty - quantityToLink;
        await tx.insert(backorders).values({
          salesOrderId: demand.salesOrderId,
          salesOrderLineId: demand.salesOrderLineId,
          productId: demand.productId,
          quantity: remainingQty.toString(),
          stateCode: BACKORDER_STATE.PENDING_SUPPLY,
        });
      } else {
        // Fully allocate
        await tx
          .update(backorders)
          .set({
            purchaseOrderId: poLine.purchaseOrderId,
            purchaseOrderLineId: purchaseOrderLineId,
            modifiedOn: new Date(),
          })
          .where(eq(backorders.backorderId, demandId));

        await this.changeBackorderState(
          demandId,
          BACKORDER_STATE.AWAITING_RECEIPT,
          actor,
          tx,
        );
      }

      // Optional: Emit event
      await emitEvent(tx, {
        aggregateType: AggregateType.PURCHASE_ORDER,
        aggregateId: poLine.purchaseOrderId,
        eventType: EventType.DEMAND_ALLOCATED,
        actor,
        payload: { backorderId: demandId, quantity: quantityToLink },
      });
    });
  }

  /**
   * Reallocates a demand (backorder) to a new fulfillment location.
   * This unlinks any existing PO allocations for the entire sales order line,
   * updates the line's fulfillment location, and re-evaluates the gap.
   */
  async reallocateDemand(
    backorderId: string,
    newLocationId: string,
    actor: string,
  ) {
    await this.db.transaction(async (tx) => {
      // 1. Get the current demand to find the salesOrderLineId
      const [demand] = await tx
        .select({
          salesOrderId: backorders.salesOrderId,
          salesOrderLineId: backorders.salesOrderLineId,
        })
        .from(backorders)
        .where(eq(backorders.backorderId, backorderId));

      if (!demand) {
        throw new HttpException('Demand not found', HttpStatus.NOT_FOUND);
      }

      // 2. Find ALL demands for this line
      const lineDemands = await tx
        .select({
          backorderId: backorders.backorderId,
          purchaseOrderId: backorders.purchaseOrderId,
        })
        .from(backorders)
        .where(eq(backorders.salesOrderLineId, demand.salesOrderLineId));

      // 3. Unlink any linked demands
      for (const ld of lineDemands) {
        if (ld.purchaseOrderId) {
          await this.changeBackorderState(
            ld.backorderId,
            BACKORDER_STATE.PENDING_SUPPLY,
            actor,
            tx,
          );

          await tx
            .update(backorders)
            .set({
              purchaseOrderId: null,
              purchaseOrderLineId: null,
              modifiedOn: new Date(),
            })
            .where(eq(backorders.backorderId, ld.backorderId));

          await emitEvent(tx, {
            aggregateType: AggregateType.PURCHASE_ORDER,
            aggregateId: ld.purchaseOrderId,
            eventType: EventType.DEMAND_UNALLOCATED,
            actor,
            payload: { backorderId: ld.backorderId },
          });
        }
      }

      // 4. Update the Sales Order Line's fulfillmentLocationId
      await tx
        .update(salesOrderLineItems)
        .set({ fulfillmentLocationId: newLocationId })
        .where(
          eq(salesOrderLineItems.salesOrderLineId, demand.salesOrderLineId),
        );

      // 5. Delete all backorders for this line to recalculate cleanly
      await tx
        .delete(backorders)
        .where(eq(backorders.salesOrderLineId, demand.salesOrderLineId));

      // 6. Run gap evaluation for the order
      const gaps = await this.evaluateGaps(demand.salesOrderId);

      // Filter the gaps to only the line we just touched
      const lineGaps = gaps.filter(
        (g) => g.salesOrderLineId === demand.salesOrderLineId,
      );

      // 7. Regenerate demand for this line if there is still a shortage
      if (lineGaps.length > 0) {
        // We need to implement generateDemand logic inline or pass tx
        // generateDemand accepts tx as a parameter
        await this.generateDemand(demand.salesOrderId, lineGaps, actor, tx);
      }

      // 8. Emit an event indicating reallocation
      await emitEvent(tx, {
        aggregateType: AggregateType.SALES_ORDER,
        aggregateId: demand.salesOrderId,
        eventType: 'demand_reallocated' as any,
        actor,
        payload: {
          lineId: demand.salesOrderLineId,
          newLocationId,
          stillHasShortage: lineGaps.length > 0,
        },
      });
    });
  }
  async generateTransfersFromDemands(payload: any, actor: string) {
    if (
      !payload ||
      !payload.demands ||
      !Array.isArray(payload.demands) ||
      !payload.sourceLocationId
    ) {
      throw new HttpException('Invalid payload', HttpStatus.BAD_REQUEST);
    }

    const { demands, sourceLocationId } = payload;

    await this.db.transaction(async (tx) => {
      const demandsWithLocation = await tx
        .select({
          backorderId: backorders.backorderId,
          productId: backorders.productId,
          quantity: backorders.quantity,
          salesOrderLineId: backorders.salesOrderLineId,
          destinationLocationId: salesOrderLineItems.fulfillmentLocationId,
          productDescription: coreProducts.name,
        })
        .from(backorders)
        .innerJoin(
          salesOrderLineItems,
          eq(backorders.salesOrderLineId, salesOrderLineItems.salesOrderLineId),
        )
        .innerJoin(
          coreProducts,
          eq(backorders.productId, coreProducts.productId),
        )
        .where(inArray(backorders.backorderId, demands));

      if (demandsWithLocation.length === 0) return;

      const byDestination = new Map<string, typeof demandsWithLocation>();
      for (const d of demandsWithLocation) {
        const dest = d.destinationLocationId;
        if (!byDestination.has(dest)) byDestination.set(dest, []);
        byDestination.get(dest)!.push(d);
      }

      for (const [destLoc, items] of byDestination.entries()) {
        const orderNumber = `TO-${Date.now().toString().slice(-6)}${Math.floor(Math.random() * 100)}`;

        const [to] = await tx
          .insert(transferOrders)
          .values({
            orderNumber,
            sourceLocationId,
            destinationLocationId: destLoc,
            stateCode: 'released', // Instantly released to outbound queue
            createdBy: actor,
          })
          .returning();

        for (const item of items) {
          const [toLine] = await tx
            .insert(transferOrderLines)
            .values({
              transferOrderId: to.transferOrderId,
              productId: item.productId,
              quantity: item.quantity,
            })
            .returning();

          await tx
            .update(backorders)
            .set({
              transferOrderId: to.transferOrderId,
              transferOrderLineId: toLine.transferOrderLineId,
              stateCode: BACKORDER_STATE.AWAITING_RECEIPT,
            })
            .where(eq(backorders.backorderId, item.backorderId));
        }

        await tx.insert(transferOrderEvents).values({
          transferOrderId: to.transferOrderId,
          eventType: 'created',
          actor,
        });

        await tx.insert(transferOrderEvents).values({
          transferOrderId: to.transferOrderId,
          eventType: 'released',
          actor,
        });
      }
    });
  }
  /**
   * Transition a backorder to a new state, validating against the transition map.
   */
  async changeBackorderState(
    backorderId: string,
    newState: BackorderState,
    actor: string,
    tx?: DrizzleDB,
  ) {
    const db = tx || this.db;
    const [existing] = await db
      .select({
        stateCode: backorders.stateCode,
        salesOrderId: backorders.salesOrderId,
      })
      .from(backorders)
      .where(eq(backorders.backorderId, backorderId))
      .limit(1);

    if (!existing) {
      throw new NotFoundException(`Backorder ${backorderId} not found`);
    }

    const allowed = BACKORDER_TRANSITIONS[existing.stateCode];
    if (!allowed || !allowed.includes(newState)) {
      throw new BadRequestException(
        `Cannot transition backorder from '${existing.stateCode}' to '${newState}'`,
      );
    }

    const [updated] = await db
      .update(backorders)
      .set({
        stateCode: newState,
        modifiedOn: new Date(),
      })
      .where(eq(backorders.backorderId, backorderId))
      .returning();

    await emitEvent(db as any, {
      aggregateType: AggregateType.SALES_ORDER,
      aggregateId: existing.salesOrderId,
      eventType: EventType.STATUS_CHANGED,
      payload: {
        entity: 'backorder',
        entityId: backorderId,
        from: existing.stateCode,
        to: newState,
      },
      actor,
    });

    this.logger.log(
      `Backorder ${backorderId} state: ${existing.stateCode} → ${newState} by ${actor}`,
    );

    return updated;
  }
}

import {
  Injectable,
  Inject,
  BadRequestException,
  Logger,
} from '@nestjs/common';
import { eq, and, sql, desc, inArray } from 'drizzle-orm';
import { DRIZZLE } from '../drizzle/drizzle.module';
import type { DrizzleDB } from '../drizzle/drizzle.module';
import {
  salesOrders,
  salesOrderLineItems,
  products as coreProducts,
  bins,
  zones,
  binContents,
  locations,
  salesOrderPicks,
  salesOrderShipments,
  salesOrderShipmentLines,
  backorders,
  accounts as coreAccounts,
  transferOrders,
  transferOrderLines,
  transferOrderPicks,
} from '../drizzle/modbm-core-schema';
import { InventoryService } from '../inventory/inventory.service';
import {
  findOrder,
  findOrderLine,
  getCommittedPerLine,
} from './shipment-helpers';
import { emitEvent } from '../common/emit-event';
import { AggregateType } from '../common/event-types';
import { ShipmentService } from './shipment.service';
import { calculatePickAllocations } from './picking-math.utils';
import { evaluateLifecycleRules } from './order-lifecycle-rules';
import {
  filterPickableBins,
  calculatePickableOnHand,
} from '../inventory/inventory-math.utils';
import {
  SALES_ORDER_PICK_STATE,
  SALES_ORDER_PICK_TRANSITIONS,
  SALES_ORDER_STATE,
  TRANSFER_ORDER_STATE,
  getValidStates,
} from '@modbm/shared';

const VALID_PICK_STATES = getValidStates(SALES_ORDER_PICK_TRANSITIONS);

@Injectable()
export class PickingService {
  constructor(
    @Inject(DRIZZLE) private db: DrizzleDB,
    private readonly shipmentService: ShipmentService,
    private readonly inventoryService: InventoryService,
  ) {}

  private readonly logger = new Logger(PickingService.name);

  // -------------------------------------------------------------------------
  // Summary
  // -------------------------------------------------------------------------

  /**
   * Get picking summary for an order, including shipped quantities.
   */
  async getPickingSummary(orderId: string) {
    await findOrder(this.db, orderId);

    const lines = await this.db
      .select({
        salesOrderLineId: salesOrderLineItems.salesOrderLineId,
        lineNumber: salesOrderLineItems.lineNumber,
        productId: salesOrderLineItems.productId,
        productDescription: salesOrderLineItems.productDescription,
        quantity: salesOrderLineItems.quantity,
        productNumber: coreProducts.productNumber,
        productType: coreProducts.productType,
        locationName: locations.name,
        fulfillmentLocationId: salesOrderLineItems.fulfillmentLocationId,
      })
      .from(salesOrderLineItems)
      .leftJoin(
        coreProducts,
        eq(salesOrderLineItems.productId, coreProducts.productId),
      )
      .leftJoin(
        locations,
        eq(salesOrderLineItems.fulfillmentLocationId, locations.locationId),
      )
      .where(eq(salesOrderLineItems.salesOrderId, orderId))
      .orderBy(salesOrderLineItems.lineNumber);

    const committedMap = await getCommittedPerLine(this.db, orderId);

    // Fetch backorder allocation status per line
    const lineIds = lines.map((l) => l.salesOrderLineId);
    const allocations =
      lineIds.length > 0
        ? await this.db
            .select({
              salesOrderLineId: backorders.salesOrderLineId,
              allocatedQty: sql<number>`COALESCE(SUM(${backorders.quantity}), 0)`,
            })
            .from(backorders)
            .where(
              and(
                inArray(backorders.salesOrderLineId, lineIds),
                eq(backorders.stateCode, 'received_reserved'),
              ),
            )
            .groupBy(backorders.salesOrderLineId)
        : [];
    const allocationMap = new Map(
      allocations.map((a) => [a.salesOrderLineId, a.allocatedQty]),
    );

    const productIds = Array.from(
      new Set(lines.map((l) => l.productId).filter(Boolean) as string[]),
    );
    const binStock =
      productIds.length > 0
        ? await this.db
            .select({
              productId: binContents.productId,
              locationId: zones.locationId,
              zoneCode: zones.code,
              binId: bins.binId,
              binNumber: bins.binNumber,
              binType: bins.binType,
              isUnavailable: bins.isUnavailable,
              onHand: binContents.actualQuantity,
            })
            .from(binContents)
            .innerJoin(bins, eq(binContents.binId, bins.binId))
            .innerJoin(zones, eq(bins.zoneId, zones.zoneId))
            .where(inArray(binContents.productId, productIds))
        : [];

    const picksRaw = await this.db
      .select({
        pick: salesOrderPicks,
        binName: bins.binNumber,
      })
      .from(salesOrderPicks)
      .leftJoin(bins, eq(salesOrderPicks.binId, bins.binId))
      .where(eq(salesOrderPicks.salesOrderId, orderId));

    const picks = picksRaw.map((p) => ({
      ...p.pick,
      binName: p.binName,
    }));

    const pickedMap = new Map<string, number>();
    for (const pick of picks) {
      if (pick.stateCode !== SALES_ORDER_PICK_STATE.CANCELLED) {
        const current = pickedMap.get(pick.salesOrderLineId) || 0;
        pickedMap.set(
          pick.salesOrderLineId,
          current + parseFloat(pick.quantity),
        );
      }
    }

    const summary = lines.map((line) => {
      const ordered = parseFloat(line.quantity);
      const isPhysical = !line.productType || line.productType === 'inventory';
      const picked = isPhysical
        ? (pickedMap.get(line.salesOrderLineId) ?? 0)
        : ordered;
      const committed = isPhysical
        ? (committedMap.get(line.salesOrderLineId) ?? 0)
        : ordered;

      const productLocationBins = binStock.filter(
        (s) =>
          s.productId === line.productId &&
          s.locationId === line.fulfillmentLocationId,
      );

      const availableBins = filterPickableBins(productLocationBins as any[])
        .sort(
          (a, b) =>
            parseFloat(String(b.onHand || 0)) -
            parseFloat(String(a.onHand || 0)),
        )
        .map((b: any) => ({
          binId: b.binId,
          binName: `${b.zoneCode}.${b.binNumber}`,
          onHand: String(b.onHand || 0),
        }));

      return {
        salesOrderLineId: line.salesOrderLineId,
        lineNumber: line.lineNumber,
        productId: line.productId,
        productNumber: line.productNumber,
        productType: line.productType,
        productDescription: line.productDescription,
        locationName: line.locationName || 'System Default',
        quantity: line.quantity,
        quantityPicked: isPhysical ? String(picked) : String(ordered),
        quantityShipped: String(committed),
        remaining: String(ordered - picked),
        isFullyPicked: picked >= ordered,
        isPhysical,
        onHand: String(calculatePickableOnHand(productLocationBins as any[])),
        availableBins,
        hasAllocation: (allocationMap.get(line.salesOrderLineId) ?? 0) > 0,
      };
    });

    const totalLines = lines.length;
    const fullyPickedLines = summary.filter((s) => s.isFullyPicked).length;

    return {
      totalLines,
      fullyPickedLines,
      isFullyPicked: totalLines > 0 && fullyPickedLines === totalLines,
      lines: summary,
      picks, // Include raw picks for UI
    };
  }

  // -------------------------------------------------------------------------
  // Pick Line
  // -------------------------------------------------------------------------

  async pickLine(
    orderId: string,
    lineId: string,
    binId: string,
    quantity: string,
    actor: string,
  ) {
    const order = await findOrder(this.db, orderId);
    if (
      order.stateCode !== SALES_ORDER_STATE.PICKING &&
      order.stateCode !== SALES_ORDER_STATE.CONFIRMED
    ) {
      throw new BadRequestException(
        `Cannot pick lines on order in state '${order.stateCode}'. Order must be in 'confirmed' or 'picking'.`,
      );
    }

    const line = await findOrderLine(this.db, lineId, orderId);
    const qty = parseFloat(quantity);
    const ordered = parseFloat(line.quantity);

    if (isNaN(qty) || qty <= 0) {
      throw new BadRequestException('Picked quantity must be > 0');
    }

    // Get current picked amount
    const [currentPickSum] = await this.db
      .select({ sum: sql<number>`COALESCE(SUM(quantity), 0)` })
      .from(salesOrderPicks)
      .where(
        and(
          eq(salesOrderPicks.salesOrderLineId, lineId),
          sql`state_code != ${SALES_ORDER_PICK_STATE.CANCELLED}`,
        ),
      );

    const currentlyPicked = parseFloat(String(currentPickSum?.sum ?? 0));

    if (currentlyPicked + qty > ordered) {
      throw new BadRequestException(
        `Cannot pick ${qty} — only ${ordered - currentlyPicked} remaining on this line`,
      );
    }

    // Resolve SHIPPING bin for physical stock movement
    const [shippingBin] = await this.db
      .select({ binId: bins.binId })
      .from(bins)
      .innerJoin(zones, eq(bins.zoneId, zones.zoneId))
      .where(
        and(
          eq(bins.binNumber, 'SHIPPING'),
          eq(zones.locationId, line.fulfillmentLocationId),
        ),
      )
      .limit(1);

    if (!shippingBin) {
      throw new BadRequestException(
        `No SHIPPING staging bin found for location ${line.fulfillmentLocationId}.`,
      );
    }

    const result = await this.db.transaction(async (tx: DrizzleDB) => {
      // 1. Record physical inventory movement
      await this.inventoryService.recordInventoryMovement(tx, {
        entryNumber: `PCK-${orderId.substring(0, 8)}-${line.lineNumber}-${Date.now()
          .toString()
          .slice(-4)}`,
        sourceType: 'SO_PICK',
        sourceId: orderId,
        memo: `Sales Order Pick`,
        userId: actor,
        lines: [
          {
            productId: line.productId!,
            binId: binId,
            quantity: -qty,
          },
          {
            productId: line.productId!,
            binId: shippingBin.binId,
            quantity: qty,
          },
        ],
      });

      // 2. Insert into sales_order_picks
      const [newPick] = await tx
        .insert(salesOrderPicks)
        .values({
          salesOrderId: orderId,
          salesOrderLineId: lineId,
          productId: line.productId!,
          binId: binId,
          quantity: quantity,
          createdBy: actor,
        })
        .returning();

      // 3. Update order modifiedOn
      await tx
        .update(salesOrders)
        .set({ modifiedOn: new Date() })
        .where(eq(salesOrders.salesOrderId, orderId));

      await emitEvent(tx, {
        aggregateType: AggregateType.SALES_ORDER,
        aggregateId: orderId,
        eventType: 'status_changed',
        payload: {
          entity: 'pick',
          entityId: newPick.pickId,
          from: null,
          to: SALES_ORDER_PICK_STATE.PICKED,
          lineId,
          quantityPicked: quantity,
          binId,
        },
        actor,
      });

      await evaluateLifecycleRules(
        tx,
        orderId,
        { entity: 'picking', id: lineId, action: 'line_picked' },
        actor,
      );

      return newPick;
    });

    return result;
  }

  // -------------------------------------------------------------------------
  // Shipped gate — called from OrdersWriteService
  // -------------------------------------------------------------------------

  /**
   * Check if all lines on an order are fully picked.
   * Throws BadRequestException if not.
   */
  async assertFullyPicked(orderId: string): Promise<void> {
    const summary = await this.getPickingSummary(orderId);

    const unpicked = summary.lines.filter((l) => {
      const ordered = parseFloat(l.quantity);
      const picked = parseFloat(l.quantityPicked ?? '0');
      return picked < ordered;
    });

    if (unpicked.length > 0) {
      const details = unpicked.map(
        (l) =>
          `line ${l.lineNumber}: picked ${l.quantityPicked ?? '0'} of ${l.quantity}`,
      );
      throw new BadRequestException(
        `Cannot transition to 'shipped' - ${unpicked.length} line(s) not fully picked: ${details.join('; ')}`,
      );
    }
  }

  /**
   * Check if all lines on an order are fully shipped.
   * Throws BadRequestException if not.
   */
  async assertFullyShipped(orderId: string): Promise<void> {
    const summary = await this.getPickingSummary(orderId);

    const unshipped = summary.lines.filter((l) => {
      const ordered = parseFloat(l.quantity);
      const shipped = parseFloat(l.quantityShipped ?? '0');
      return shipped < ordered;
    });

    if (unshipped.length > 0) {
      const details = unshipped.map(
        (l) =>
          `line ${l.lineNumber}: shipped ${l.quantityShipped ?? '0'} of ${l.quantity}`,
      );
      throw new BadRequestException(
        `Cannot transition to 'shipped' - ${unshipped.length} line(s) not fully shipped: ${details.join('; ')}`,
      );
    }
  }

  // -------------------------------------------------------------------------
  // Picking Queue
  // -------------------------------------------------------------------------

  /**
   * Returns a queue of orders pending picking, enriched with pickability status.
   * Pickability is determined by physical on-hand stock in pickable bins.
   */
  async getPickingQueue(locationId?: string) {
    const rawLines = await this.db
      .select({
        id: salesOrders.salesOrderId,
        orderNumber: salesOrders.orderNumber,
        name: salesOrders.name,
        customerName: coreAccounts.name,
        customerOrderNumber: salesOrders.customerOrderNumber,
        stateCode: salesOrders.stateCode,
        createdOn: salesOrders.createdOn,
        createdBy: salesOrders.createdBy,
        currencyCode: salesOrders.currencyCode,
        lineId: salesOrderLineItems.salesOrderLineId,
        lineQuantity: salesOrderLineItems.quantity,
        isPhysical: sql<boolean>`CASE WHEN ${coreProducts.productType} = 'inventory' THEN true ELSE false END`,
        onHand: sql<number>`COALESCE((
          SELECT sum(bc.actual_quantity)
          FROM modbm_core.bin_contents bc
          JOIN modbm_core.bins b ON b.bin_id = bc.bin_id
          JOIN modbm_core.zones z ON z.zone_id = b.zone_id
          WHERE bc.product_id = ${salesOrderLineItems.productId}
            AND z.location_id = ${salesOrderLineItems.fulfillmentLocationId}
            AND b.bin_type IN ('storage', 'pick', 'bulk')
            AND b.is_unavailable = false
            AND b.is_bonded = false
        ), 0)`,
        pickedQty: sql<number>`COALESCE((
          SELECT SUM(quantity) 
          FROM modbm_core.sales_order_picks 
          WHERE sales_order_line_id = ${salesOrderLineItems.salesOrderLineId}
            AND state_code != 'cancelled'
        ), 0)`,
        hasAllocation: sql<boolean>`EXISTS(
          SELECT 1 FROM modbm_core.backorders bo
          WHERE bo.sales_order_line_id = ${salesOrderLineItems.salesOrderLineId}
            AND bo.state_code = 'received_reserved'
        )`,
      })
      .from(salesOrders)
      .innerJoin(
        salesOrderLineItems,
        eq(salesOrders.salesOrderId, salesOrderLineItems.salesOrderId),
      )
      .leftJoin(
        coreAccounts,
        eq(salesOrders.customerId, coreAccounts.accountId),
      )
      .leftJoin(
        coreProducts,
        eq(salesOrderLineItems.productId, coreProducts.productId),
      )
      .where(
        and(
          inArray(salesOrders.stateCode, [
            SALES_ORDER_STATE.CONFIRMED,
            SALES_ORDER_STATE.PICKING,
          ]),
          locationId
            ? eq(salesOrderLineItems.fulfillmentLocationId, locationId)
            : undefined,
        ),
      )
      .orderBy(salesOrders.createdOn);

    const rawTransferLines = await this.db
      .select({
        id: transferOrders.transferOrderId,
        orderNumber: transferOrders.orderNumber,
        name: sql<string>`'Internal Transfer'`,
        customerName: locations.name,
        customerOrderNumber: sql<string>`'N/A'`,
        stateCode: transferOrders.stateCode,
        createdOn: transferOrders.createdOn,
        createdBy: transferOrders.createdBy,
        currencyCode: sql<string>`'N/A'`,
        lineId: transferOrderLines.transferOrderLineId,
        lineQuantity: transferOrderLines.quantity,
        isPhysical: sql<boolean>`CASE WHEN ${coreProducts.productType} = 'inventory' THEN true ELSE false END`,
        onHand: sql<number>`COALESCE((
          SELECT sum(bc.actual_quantity)
          FROM modbm_core.bin_contents bc
          JOIN modbm_core.bins b ON b.bin_id = bc.bin_id
          JOIN modbm_core.zones z ON z.zone_id = b.zone_id
          WHERE bc.product_id = ${transferOrderLines.productId}
            AND z.location_id = ${transferOrders.sourceLocationId}
            AND b.bin_type IN ('storage', 'pick', 'bulk')
            AND b.is_unavailable = false
            AND b.is_bonded = false
        ), 0)`,
        pickedQty: sql<number>`COALESCE((
          SELECT SUM(quantity) 
          FROM modbm_core.transfer_order_picks 
          WHERE transfer_order_line_id = ${transferOrderLines.transferOrderLineId}
            AND state_code != 'cancelled'
        ), 0)`,
        hasAllocation: sql<boolean>`false`,
        type: sql<string>`'transfer_order'`,
      })
      .from(transferOrders)
      .innerJoin(
        transferOrderLines,
        eq(transferOrders.transferOrderId, transferOrderLines.transferOrderId),
      )
      .leftJoin(
        locations,
        eq(transferOrders.destinationLocationId, locations.locationId),
      )
      .leftJoin(
        coreProducts,
        eq(transferOrderLines.productId, coreProducts.productId),
      )
      .where(
        and(
          inArray(transferOrders.stateCode, [
            TRANSFER_ORDER_STATE.RELEASED,
            TRANSFER_ORDER_STATE.PICKING,
          ]),
          locationId
            ? eq(transferOrders.sourceLocationId, locationId)
            : undefined,
        ),
      );

    const allLines = [
      ...rawLines.map((r) => ({ ...r, type: 'sales_order' })),
      ...rawTransferLines,
    ];

    const orderMap = new Map<string, any>();

    for (const row of allLines) {
      if (!orderMap.has(row.id)) {
        orderMap.set(row.id, {
          id: row.id,
          orderNumber: row.orderNumber,
          name: row.name,
          customerName: row.customerName,
          customerOrderNumber: row.customerOrderNumber,
          stateCode: row.stateCode,
          createdOn: row.createdOn,
          createdBy: row.createdBy,
          totalPrice: null,
          currencyCode: row.currencyCode,
          _linesUnfulfilled: 0,
          _linesFullyPickable: 0,
          _linesPartiallyPickable: 0,
          _hasAllocation: false,
          type: row.type,
        });
      }

      const order = orderMap.get(row.id);
      if (row.hasAllocation) {
        order._hasAllocation = true;
      }
      if (row.isPhysical) {
        const required = parseFloat(row.lineQuantity ?? '0');
        const picked = parseFloat(row.pickedQty?.toString() ?? '0');
        const remaining = required - picked;

        if (remaining > 0) {
          order._linesUnfulfilled += 1;
          const onHand = parseFloat(row.onHand?.toString() ?? '0');

          if (onHand >= remaining) {
            order._linesFullyPickable += 1;
          } else if (onHand > 0) {
            order._linesPartiallyPickable += 1;
          }
          // else: blocked (no on-hand) — counted implicitly
        }
      }
    }

    const queue = Array.from(orderMap.values())
      .filter((order) => order._linesUnfulfilled > 0)
      .map((order) => {
        let pickabilityStatus: 'ready' | 'partial' | 'blocked';

        if (order._linesFullyPickable === order._linesUnfulfilled) {
          pickabilityStatus = 'ready';
        } else if (
          order._linesFullyPickable > 0 ||
          order._linesPartiallyPickable > 0
        ) {
          pickabilityStatus = 'partial';
        } else {
          pickabilityStatus = 'blocked';
        }

        const hasAllocation = order._hasAllocation;
        delete order._linesUnfulfilled;
        delete order._linesFullyPickable;
        delete order._linesPartiallyPickable;
        delete order._hasAllocation;

        return {
          ...order,
          pickabilityStatus,
          hasAllocation,
        };
      });

    // Sort: allocated orders first within each status group
    queue.sort((a, b) => {
      if (a.hasAllocation !== b.hasAllocation) {
        return a.hasAllocation ? -1 : 1;
      }
      return 0; // preserve original createdOn ordering within same allocation status
    });

    return queue;
  }

  // -------------------------------------------------------------------------
  // Cancel Pick Line
  // -------------------------------------------------------------------------

  async cancelPick(orderId: string, pickId: string, actor: string) {
    const pickRows = await this.db
      .select({
        pick: salesOrderPicks,
        locationId: zones.locationId,
      })
      .from(salesOrderPicks)
      .innerJoin(bins, eq(salesOrderPicks.binId, bins.binId))
      .innerJoin(zones, eq(bins.zoneId, zones.zoneId))
      .where(
        and(
          eq(salesOrderPicks.pickId, pickId),
          eq(salesOrderPicks.salesOrderId, orderId),
        ),
      )
      .limit(1);

    if (pickRows.length === 0) {
      throw new BadRequestException(
        `Pick not found or does not belong to this order.`,
      );
    }

    const { pick, locationId } = pickRows[0];

    if (pick.stateCode !== SALES_ORDER_PICK_STATE.PICKED) {
      throw new BadRequestException(
        `Cannot cancel pick in state '${pick.stateCode}'. Only 'picked' lines can be cancelled.`,
      );
    }

    const qty = parseFloat(pick.quantity);

    // Resolve SHIPPING bin for physical stock movement reversal
    const [shippingBin] = await this.db
      .select({ binId: bins.binId })
      .from(bins)
      .innerJoin(zones, eq(bins.zoneId, zones.zoneId))
      .where(
        and(eq(bins.binNumber, 'SHIPPING'), eq(zones.locationId, locationId)),
      )
      .limit(1);

    if (!shippingBin) {
      throw new BadRequestException(
        `No SHIPPING staging bin found for location ${locationId}.`,
      );
    }

    const result = await this.db.transaction(async (tx: DrizzleDB) => {
      // 1. Record physical inventory movement (reverse the pick)
      await this.inventoryService.recordInventoryMovement(tx, {
        entryNumber: `UPK-${orderId.substring(0, 8)}-${Date.now()
          .toString()
          .slice(-4)}`,
        sourceType: 'SO_PICK',
        sourceId: orderId,
        memo: `Sales Order Pick Reversal`,
        userId: actor,
        lines: [
          {
            productId: pick.productId,
            binId: shippingBin.binId,
            quantity: -qty, // remove from shipping
          },
          {
            productId: pick.productId,
            binId: pick.binId!, // put back to original bin
            quantity: qty,
          },
        ],
      });

      // 2. Update sales_order_picks
      const updatedPick = await this.changeSalesPickState(
        pickId,
        SALES_ORDER_PICK_STATE.CANCELLED,
        actor,
        tx,
      );

      // 3. Update order modifiedOn
      await tx
        .update(salesOrders)
        .set({ modifiedOn: new Date() })
        .where(eq(salesOrders.salesOrderId, orderId));

      return updatedPick;
    });

    return result;
  }

  /**
   * Universal changeState for Sales Order Picks
   */
  async changeSalesPickState(
    pickId: string,
    newState: string,
    actor: string,
    tx: DrizzleDB,
  ) {
    if (!VALID_PICK_STATES.includes(newState)) {
      throw new BadRequestException(`Invalid pick state: '${newState}'`);
    }

    const [pick] = await tx
      .select({
        stateCode: salesOrderPicks.stateCode,
        salesOrderLineId: salesOrderPicks.salesOrderLineId,
        productId: salesOrderPicks.productId,
        quantity: salesOrderPicks.quantity,
        binId: salesOrderPicks.binId,
        salesOrderId: salesOrderPicks.salesOrderId,
      })
      .from(salesOrderPicks)
      .where(eq(salesOrderPicks.pickId, pickId));

    if (!pick) {
      throw new BadRequestException(`Pick ${pickId} not found`);
    }

    const allowed = SALES_ORDER_PICK_TRANSITIONS[pick.stateCode as string];
    if (!allowed || !allowed.includes(newState)) {
      throw new BadRequestException(
        `Cannot transition pick from '${pick.stateCode}' to '${newState}'. Allowed transitions: ${allowed?.join(', ') || 'none'}`,
      );
    }

    const [updated] = await tx
      .update(salesOrderPicks)
      .set({ stateCode: newState as any, modifiedOn: new Date() })
      .where(eq(salesOrderPicks.pickId, pickId))
      .returning();

    await emitEvent(tx as any, {
      aggregateType: AggregateType.SALES_ORDER,
      aggregateId: pick.salesOrderId,
      eventType: 'status_changed',
      payload: {
        entity: 'pick',
        entityId: pickId,
        salesOrderLineId: pick.salesOrderLineId,
        productId: pick.productId,
        quantity: pick.quantity,
        binId: pick.binId,
        from: pick.stateCode,
        to: newState,
      },
      actor,
    });

    return updated;
  }

  // -------------------------------------------------------------------------
  // Shipping Queue
  // -------------------------------------------------------------------------

  /**
   * Returns a queue of orders pending shipment, enriched with shippability status.
   * Shippability is determined by comparing picked quantities to shipped quantities.
   */
  async getShippingQueue(locationId?: string) {
    const rawLines = await this.db
      .select({
        id: salesOrders.salesOrderId,
        orderNumber: salesOrders.orderNumber,
        name: salesOrders.name,
        customerName: coreAccounts.name,
        customerOrderNumber: salesOrders.customerOrderNumber,
        stateCode: salesOrders.stateCode,
        createdOn: salesOrders.createdOn,
        createdBy: salesOrders.createdBy,
        currencyCode: salesOrders.currencyCode,
        lineId: salesOrderLineItems.salesOrderLineId,
        lineQuantity: salesOrderLineItems.quantity,
        isPhysical: sql<boolean>`CASE WHEN ${coreProducts.productType} = 'inventory' OR ${coreProducts.productType} IS NULL THEN true ELSE false END`,
        pickedQty: sql<number>`COALESCE((
          SELECT SUM(quantity)
          FROM modbm_core.sales_order_picks
          WHERE sales_order_line_id = ${salesOrderLineItems.salesOrderLineId}
            AND state_code != 'cancelled'
        ), 0)`,
        shippedQty: sql<number>`COALESCE((
          SELECT SUM(sl.quantity_shipped)
          FROM modbm_core.sales_order_shipment_lines sl
          JOIN modbm_core.sales_order_shipments s ON s.shipment_id = sl.shipment_id
          WHERE sl.sales_order_line_id = ${salesOrderLineItems.salesOrderLineId}
             AND s.state_code != ${SALES_ORDER_PICK_STATE.CANCELLED}
        ), 0)`,
      })
      .from(salesOrders)
      .innerJoin(
        salesOrderLineItems,
        eq(salesOrders.salesOrderId, salesOrderLineItems.salesOrderId),
      )
      .leftJoin(
        coreAccounts,
        eq(salesOrders.customerId, coreAccounts.accountId),
      )
      .leftJoin(
        coreProducts,
        eq(salesOrderLineItems.productId, coreProducts.productId),
      )
      .where(
        and(
          eq(salesOrders.stateCode, SALES_ORDER_STATE.PICKING),
          locationId
            ? eq(salesOrderLineItems.fulfillmentLocationId, locationId)
            : undefined,
        ),
      )
      .orderBy(salesOrders.createdOn);

    const orderMap = new Map<string, any>();

    for (const row of rawLines) {
      if (!orderMap.has(row.id)) {
        orderMap.set(row.id, {
          id: row.id,
          orderNumber: row.orderNumber,
          name: row.name,
          customerName: row.customerName,
          customerOrderNumber: row.customerOrderNumber,
          stateCode: row.stateCode,
          createdOn: row.createdOn,
          createdBy: row.createdBy,
          currencyCode: row.currencyCode,
          _totalPhysicalLines: 0,
          _fullyPickedLines: 0,
          _shippableLines: 0,
        });
      }

      const order = orderMap.get(row.id);
      if (row.isPhysical) {
        order._totalPhysicalLines += 1;
        const ordered = parseFloat(row.lineQuantity ?? '0');
        const picked = parseFloat(row.pickedQty?.toString() ?? '0');
        const shipped = parseFloat(row.shippedQty?.toString() ?? '0');
        const availableToShip = picked - shipped;

        if (picked >= ordered) {
          order._fullyPickedLines += 1;
        }

        if (availableToShip > 0) {
          order._shippableLines += 1;
        }
      }
    }

    const queue = Array.from(orderMap.values())
      .filter((order) => order._shippableLines > 0)
      .map((order) => {
        let shippabilityStatus: 'ready' | 'partial';

        if (
          order._totalPhysicalLines > 0 &&
          order._fullyPickedLines === order._totalPhysicalLines
        ) {
          shippabilityStatus = 'ready';
        } else {
          shippabilityStatus = 'partial';
        }

        const totalShippableLines = order._shippableLines;
        const totalLines = order._totalPhysicalLines;
        delete order._totalPhysicalLines;
        delete order._fullyPickedLines;
        delete order._shippableLines;

        return {
          ...order,
          shippabilityStatus,
          totalShippableLines,
          totalLines,
        };
      });

    return queue;
  }

  // -------------------------------------------------------------------------
  // Shipping Context
  // -------------------------------------------------------------------------

  /**
   * Returns shipping context for an order: lines enriched with picked/shipped
   * quantities and available-to-ship amounts, plus existing shipment summaries.
   */
  async getShippingContext(orderId: string) {
    await findOrder(this.db, orderId);

    const lines = await this.db
      .select({
        salesOrderLineId: salesOrderLineItems.salesOrderLineId,
        lineNumber: salesOrderLineItems.lineNumber,
        productId: salesOrderLineItems.productId,
        productDescription: salesOrderLineItems.productDescription,
        quantity: salesOrderLineItems.quantity,
        productNumber: coreProducts.productNumber,
        productType: coreProducts.productType,
      })
      .from(salesOrderLineItems)
      .leftJoin(
        coreProducts,
        eq(salesOrderLineItems.productId, coreProducts.productId),
      )
      .where(eq(salesOrderLineItems.salesOrderId, orderId))
      .orderBy(salesOrderLineItems.lineNumber);

    // Get picked quantities from the picks sub-ledger
    const lineIds = lines.map((l) => l.salesOrderLineId);
    const pickedMap = new Map<string, number>();
    if (lineIds.length > 0) {
      const pickSums = await this.db
        .select({
          salesOrderLineId: salesOrderPicks.salesOrderLineId,
          totalPicked: sql<number>`COALESCE(SUM(${salesOrderPicks.quantity}), 0)`,
        })
        .from(salesOrderPicks)
        .where(
          and(
            inArray(salesOrderPicks.salesOrderLineId, lineIds),
            sql`${salesOrderPicks.stateCode} != ${SALES_ORDER_PICK_STATE.CANCELLED}`,
          ),
        )
        .groupBy(salesOrderPicks.salesOrderLineId);

      for (const row of pickSums) {
        pickedMap.set(
          row.salesOrderLineId,
          parseFloat(String(row.totalPicked)),
        );
      }
    }

    // Get shipped quantities from committed (non-cancelled) shipment lines
    const committedMap = await getCommittedPerLine(this.db, orderId);

    const enrichedLines = lines.map((line) => {
      const ordered = parseFloat(line.quantity);
      const isPhysical = !line.productType || line.productType === 'inventory';
      const picked = isPhysical
        ? (pickedMap.get(line.salesOrderLineId) ?? 0)
        : ordered;
      const shipped = committedMap.get(line.salesOrderLineId) ?? 0;
      const availableToShip = Math.max(0, picked - shipped);

      return {
        salesOrderLineId: line.salesOrderLineId,
        lineNumber: line.lineNumber,
        productId: line.productId,
        productNumber: line.productNumber,
        productDescription: line.productDescription,
        isPhysical,
        quantity: line.quantity,
        quantityPicked: String(picked),
        quantityShipped: String(shipped),
        availableToShip: String(availableToShip),
      };
    });

    // Existing shipments summary
    const shipments = await this.db
      .select({
        shipmentId: salesOrderShipments.shipmentId,
        shipmentNumber: salesOrderShipments.shipmentNumber,
        stateCode: salesOrderShipments.stateCode,
        notes: salesOrderShipments.notes,
        trackingNumber: salesOrderShipments.trackingNumber,
        createdOn: salesOrderShipments.createdOn,
      })
      .from(salesOrderShipments)
      .where(
        and(
          eq(salesOrderShipments.salesOrderId, orderId),
          sql`${salesOrderShipments.stateCode} != ${SALES_ORDER_STATE.CANCELLED}`,
        ),
      )
      .orderBy(desc(salesOrderShipments.createdOn));

    // Get line counts per shipment
    const shipmentIds = shipments.map((s) => s.shipmentId);
    const lineCountMap = new Map<string, number>();
    if (shipmentIds.length > 0) {
      const lineCounts = await this.db
        .select({
          shipmentId: salesOrderShipmentLines.shipmentId,
          lineCount: sql<number>`COUNT(*)`,
        })
        .from(salesOrderShipmentLines)
        .where(inArray(salesOrderShipmentLines.shipmentId, shipmentIds))
        .groupBy(salesOrderShipmentLines.shipmentId);

      for (const row of lineCounts) {
        lineCountMap.set(row.shipmentId, Number(row.lineCount));
      }
    }

    return {
      lines: enrichedLines,
      shipments: shipments.map((s) => ({
        ...s,
        lineCount: lineCountMap.get(s.shipmentId) ?? 0,
      })),
    };
  }
}

import {
  Injectable,
  BadRequestException,
  NotFoundException,
} from '@nestjs/common';
import { Inject } from '@nestjs/common';
import { DRIZZLE } from '../../drizzle/drizzle.module';
import type { DrizzleDB } from '../../drizzle/drizzle.module';
import {
  transferOrders,
  transferOrderLines,
  transferOrderPicks,
  transferOrderShipments,
  transferOrderShipmentLines,
  transferOrderReceipts,
  transferOrderReceiptLines,
  transferOrderEvents,
  locations,
  bins,
  zones,
  binContents,
  backorders,
  salesOrderLineItems,
  products as coreProducts,
} from '../../drizzle/modbm-core-schema';
import { eq, and, inArray, sum, sql, desc } from 'drizzle-orm';
import { InventoryService } from '../../inventory/inventory.service';
import { emitEvent } from '../../common/emit-event';
import { AggregateType } from '../../common/event-types';
import {
  BACKORDER_STATE,
  TRANSFER_ORDER_STATE,
  TRANSFER_ORDER_TRANSITIONS,
  TRANSFER_ORDER_PICK_STATE,
  TRANSFER_ORDER_PICK_TRANSITIONS,
  getValidStates,
} from '@modbm/shared';
import type { TransferOrderState, TransferOrderPickState } from '@modbm/shared';
import { v4 as uuidv4 } from 'uuid';

const VALID_TRANSFER_STATES = getValidStates(TRANSFER_ORDER_TRANSITIONS);
const VALID_PICK_STATES = getValidStates(TRANSFER_ORDER_PICK_TRANSITIONS);

@Injectable()
export class TransferService {
  constructor(
    @Inject(DRIZZLE) private db: DrizzleDB,
    private readonly inventoryService: InventoryService,
  ) {}

  // -------------------------------------------------------------------------
  // Creation
  // -------------------------------------------------------------------------

  async createTransferFromDemands(
    sourceLocationId: string,
    backorderIds: string[],
    actor: string,
  ) {
    if (!backorderIds || backorderIds.length === 0) {
      throw new BadRequestException('No demands specified');
    }

    return await this.db.transaction(async (tx) => {
      // Find backorders
      const lines = await tx
        .select({
          backorderId: backorders.backorderId,
          productId: backorders.productId,
          quantity: backorders.quantity,
          locationId: salesOrderLineItems.fulfillmentLocationId,
          salesOrderId: backorders.salesOrderId,
          salesOrderLineId: backorders.salesOrderLineId,
        })
        .from(backorders)
        .innerJoin(
          salesOrderLineItems,
          eq(backorders.salesOrderLineId, salesOrderLineItems.salesOrderLineId),
        )
        .where(
          and(
            inArray(backorders.backorderId, backorderIds),
            eq(backorders.stateCode, BACKORDER_STATE.PENDING_SUPPLY),
            sql`${backorders.purchaseOrderId} IS NULL`,
            sql`${backorders.transferOrderId} IS NULL`,
          ),
        );

      if (lines.length !== backorderIds.length) {
        throw new BadRequestException(
          'Some demands could not be found or are not open',
        );
      }

      // Check they are all for the same destination location
      const destLocationId = lines[0].locationId;
      if (!lines.every((l) => l.locationId === destLocationId)) {
        throw new BadRequestException(
          'All demands must be for the same destination location',
        );
      }

      // 1) Generate transfer_order_number
      const prefix = `TO-${new Date().toISOString().split('T')[0].replace(/-/g, '')}-`;
      const lastOrder = await tx
        .select({ orderNumber: transferOrders.orderNumber })
        .from(transferOrders)
        .where(sql`${transferOrders.orderNumber} LIKE ${prefix + '%'}`)
        .orderBy(desc(transferOrders.orderNumber))
        .limit(1);

      let nextNum = 1;
      if (lastOrder.length > 0) {
        const parts = lastOrder[0].orderNumber.split('-');
        nextNum = parseInt(parts[2], 10) + 1;
      }
      const orderNumber = `${prefix}${String(nextNum).padStart(3, '0')}`;

      const transferOrderId = uuidv4();

      // 2) Insert Header
      await tx.insert(transferOrders).values({
        transferOrderId,
        orderNumber,
        sourceLocationId,
        destinationLocationId: destLocationId,
        stateCode: TRANSFER_ORDER_STATE.RELEASED,
        createdBy: actor,
      });

      // 3) Insert Lines and Update Backorders
      for (const line of lines) {
        const transferOrderLineId = uuidv4();
        await tx.insert(transferOrderLines).values({
          transferOrderLineId,
          transferOrderId,
          productId: line.productId,
          quantity: line.quantity,
        });

        // "Allocate" the backorder to this transfer order
        await tx
          .update(backorders)
          .set({
            transferOrderId,
            transferOrderLineId,
            stateCode: BACKORDER_STATE.AWAITING_RECEIPT,
          })
          .where(eq(backorders.backorderId, line.backorderId));
      }

      return { transferOrderId, orderNumber };
    });
  }

  // -------------------------------------------------------------------------
  // Picking
  // -------------------------------------------------------------------------

  async getPickingSummary(transferOrderId: string) {
    const order = await this.db.query.transferOrders.findFirst({
      where: eq(transferOrders.transferOrderId, transferOrderId),
    });

    if (!order) {
      throw new NotFoundException('Transfer Order not found');
    }

    const sourceLoc = await this.db.query.locations.findFirst({
      where: eq(locations.locationId, order.sourceLocationId),
    });

    const lines = await this.db
      .select({
        transferOrderLineId: transferOrderLines.transferOrderLineId,
        productId: transferOrderLines.productId,
        productNumber: coreProducts.productNumber,
        productType: coreProducts.productType,
        productDescription: coreProducts.name,
        quantity: transferOrderLines.quantity,
        quantityShipped: transferOrderLines.quantityShipped,
      })
      .from(transferOrderLines)
      .innerJoin(
        coreProducts,
        eq(transferOrderLines.productId, coreProducts.productId),
      )
      .where(eq(transferOrderLines.transferOrderId, transferOrderId));

    const picks = await this.db
      .select({
        pickId: transferOrderPicks.pickId,
        transferOrderId: transferOrderPicks.transferOrderId,
        transferOrderLineId: transferOrderPicks.transferOrderLineId,
        productId: transferOrderPicks.productId,
        binId: transferOrderPicks.binId,
        binName: bins.binNumber,
        quantity: transferOrderPicks.quantity,
        stateCode: transferOrderPicks.stateCode,
      })
      .from(transferOrderPicks)
      .leftJoin(bins, eq(transferOrderPicks.binId, bins.binId))
      .where(eq(transferOrderPicks.transferOrderId, transferOrderId));

    // For each line, compute remaining and get available bins
    const enrichedLines = await Promise.all(
      lines.map(async (line: any) => {
        const linePicks = picks.filter(
          (p: any) =>
            p.transferOrderLineId === line.transferOrderLineId &&
            p.stateCode !== 'cancelled',
        );
        const pickedQty = linePicks.reduce(
          (acc: number, p: any) => acc + parseFloat(p.quantity),
          0,
        );
        const orderedQty = parseFloat(line.quantity as string);
        const remaining = orderedQty - pickedQty;

        let availableBins: any[] = [];
        let totalOnHand = 0;

        if (line.productType === 'inventory') {
          const rawBins = await this.db
            .select({
              binId: bins.binId,
              binName: bins.binNumber,
              onHand: binContents.actualQuantity,
            })
            .from(binContents)
            .innerJoin(bins, eq(binContents.binId, bins.binId))
            .innerJoin(zones, eq(bins.zoneId, zones.zoneId))
            .where(
              and(
                eq(binContents.productId, line.productId),
                eq(zones.locationId, order.sourceLocationId),
                inArray(bins.binType, ['storage', 'pick', 'bulk']),
                eq(bins.isUnavailable, false),
                eq(bins.isBonded, false),
              ),
            );

          availableBins = rawBins;
          totalOnHand = availableBins.reduce(
            (acc, b) => acc + parseFloat(b.onHand),
            0,
          );
        }

        return {
          ...line,
          locationName: sourceLoc?.name || 'Unknown',
          availableBins,
          quantityPicked: pickedQty.toString(),
          remaining: remaining.toString(),
          isFullyPicked: remaining <= 0,
          isPhysical: line.productType === 'inventory',
          onHand: totalOnHand.toString(),
          hasAllocation: false, // Transfer orders don't have backorder allocations in the same way
        };
      }),
    );

    const isFullyPicked = enrichedLines.every((l: any) => l.isFullyPicked);

    return {
      totalLines: lines.length,
      fullyPickedLines: enrichedLines.filter((l: any) => l.isFullyPicked)
        .length,
      isFullyPicked,
      lines: enrichedLines,
      picks,
    };
  }

  async pickLine(
    transferOrderId: string,
    lineId: string,
    binId: string,
    quantity: number,
    actor: string,
  ) {
    const line = await this.db.query.transferOrderLines.findFirst({
      where: eq(transferOrderLines.transferOrderLineId, lineId),
    });

    if (!line || line.transferOrderId !== transferOrderId) {
      throw new BadRequestException('Invalid line for this transfer order');
    }

    const rawBins = await this.db
      .select({
        binId: bins.binId,
        onHand: binContents.actualQuantity,
      })
      .from(binContents)
      .innerJoin(bins, eq(binContents.binId, bins.binId))
      .innerJoin(zones, eq(bins.zoneId, zones.zoneId))
      .where(
        and(
          eq(binContents.productId, line.productId),
          eq(
            zones.locationId,
            (await this.db.query.transferOrders.findFirst({
              where: eq(transferOrders.transferOrderId, transferOrderId),
            }))!.sourceLocationId,
          ),
          inArray(bins.binType, ['storage', 'pick', 'bulk']),
          eq(bins.isUnavailable, false),
          eq(bins.isBonded, false),
        ),
      );

    const availableBins = rawBins;

    const bin = availableBins.find((b: any) => b.binId === binId);
    if (!bin) {
      throw new BadRequestException('Bin not found or not pickable');
    }

    if (parseFloat(bin.onHand) < quantity) {
      throw new BadRequestException('Insufficient stock in selected bin');
    }

    const result = await this.db.transaction(async (tx) => {
      await tx.insert(transferOrderPicks).values({
        transferOrderId,
        transferOrderLineId: lineId,
        productId: line.productId,
        binId,
        quantity: quantity.toString(),
        createdBy: actor,
      });

      const [order] = await tx
        .select({ stateCode: transferOrders.stateCode })
        .from(transferOrders)
        .where(eq(transferOrders.transferOrderId, transferOrderId));

      if (order && order.stateCode !== TRANSFER_ORDER_STATE.RELEASED) {
        await this.changeTransferState(
          transferOrderId,
          TRANSFER_ORDER_STATE.PICKING,
          actor,
          tx,
        );
      }

      await emitEvent(tx as any, {
        aggregateType: 'transfer_order' as any,
        aggregateId: transferOrderId,
        eventType: 'line_added',
        actor,
        payload: { lineId, quantity, binId },
      });
    });

    return result;
  }

  async cancelPick(transferOrderId: string, pickId: string, actor: string) {
    const pick = await this.db.query.transferOrderPicks.findFirst({
      where: eq(transferOrderPicks.pickId, pickId),
    });

    if (!pick || pick.transferOrderId !== transferOrderId) {
      throw new BadRequestException('Invalid pick');
    }

    if (pick.stateCode !== TRANSFER_ORDER_PICK_STATE.PICKED) {
      throw new BadRequestException(
        'Can only cancel picks that are in picked state',
      );
    }

    await this.db.transaction(async (tx) => {
      await this.changePickState(
        pickId,
        TRANSFER_ORDER_PICK_STATE.CANCELLED,
        actor,
        tx,
      );

      await emitEvent(tx as any, {
        aggregateType: 'transfer_order' as any,
        aggregateId: transferOrderId,
        eventType: 'line_removed',
        actor,
        payload: { pickId },
      });
    });
  }

  // -------------------------------------------------------------------------
  // Shipping
  // -------------------------------------------------------------------------

  async shipTransferOrder(transferOrderId: string, actor: string) {
    return await this.db.transaction(async (tx) => {
      const order = await tx.query.transferOrders.findFirst({
        where: eq(transferOrders.transferOrderId, transferOrderId),
      });

      if (!order) throw new NotFoundException('Transfer Order not found');
      if (
        order.stateCode !== TRANSFER_ORDER_STATE.PICKING &&
        order.stateCode !== TRANSFER_ORDER_STATE.RELEASED
      ) {
        throw new BadRequestException(
          'Transfer order must be picking or released to ship',
        );
      }

      // 1) Get the INTRA_TRANSIT bin for the source location
      const [transitBin] = await tx
        .select({ binId: bins.binId })
        .from(bins)
        .innerJoin(zones, eq(bins.zoneId, zones.zoneId))
        .where(
          and(
            eq(zones.locationId, order.sourceLocationId),
            eq(bins.binNumber, 'INTRA_TRANSIT'),
          ),
        );

      if (!transitBin) {
        throw new BadRequestException(
          'Source location is missing INTRA_TRANSIT system bin. Please contact support.',
        );
      }

      // 2) Find all picked items
      const picks = await tx.query.transferOrderPicks.findMany({
        where: and(
          eq(transferOrderPicks.transferOrderId, transferOrderId),
          eq(transferOrderPicks.stateCode, TRANSFER_ORDER_PICK_STATE.PICKED),
        ),
      });

      if (picks.length === 0) {
        throw new BadRequestException('No items have been picked to ship');
      }

      // 3) Generate Shipment Number
      const shipmentPrefix = `TSH-${new Date().toISOString().split('T')[0].replace(/-/g, '')}-`;
      const lastShipment = await tx
        .select({ shipmentNumber: transferOrderShipments.shipmentNumber })
        .from(transferOrderShipments)
        .where(
          sql`${transferOrderShipments.shipmentNumber} LIKE ${shipmentPrefix + '%'}`,
        )
        .orderBy(desc(transferOrderShipments.shipmentNumber))
        .limit(1);

      let nextNum = 1;
      if (lastShipment.length > 0) {
        const parts = lastShipment[0].shipmentNumber.split('-');
        nextNum = parseInt(parts[2], 10) + 1;
      }
      const shipmentNumber = `${shipmentPrefix}${String(nextNum).padStart(3, '0')}`;
      const shipmentId = uuidv4();

      // 4) Create Shipment Header
      await tx.insert(transferOrderShipments).values({
        shipmentId,
        transferOrderId,
        shipmentNumber,
        stateCode: TRANSFER_ORDER_STATE.SHIPPED,
        shippedBy: actor,
      });

      // 5) Build Inventory Movements
      const inventoryLines: {
        productId: string;
        binId: string;
        quantity: number;
      }[] = [];
      const shipmentLinesInsert = [];

      for (const pick of picks) {
        const pickQty = parseFloat(pick.quantity);

        // A. Create shipment line
        shipmentLinesInsert.push({
          shipmentLineId: uuidv4(),
          shipmentId,
          transferOrderLineId: pick.transferOrderLineId,
          productId: pick.productId,
          pickId: pick.pickId,
          quantity: pickQty.toString(),
        });

        // B. Decrease from source pick bin
        inventoryLines.push({
          productId: pick.productId,
          binId: pick.binId!,
          quantity: -pickQty,
        });

        // C. Increase into INTRA_TRANSIT bin
        inventoryLines.push({
          productId: pick.productId,
          binId: transitBin.binId,
          quantity: pickQty,
        });

        // D. Mark pick as shipped
        await tx
          .update(transferOrderPicks)
          .set({ stateCode: TRANSFER_ORDER_PICK_STATE.SHIPPED as any })
          .where(eq(transferOrderPicks.pickId, pick.pickId));

        // E. Update shipped quantity on order line
        await tx
          .update(transferOrderLines)
          .set({
            quantityShipped: sql`${transferOrderLines.quantityShipped} + ${pick.quantity}`,
          })
          .where(
            eq(
              transferOrderLines.transferOrderLineId,
              pick.transferOrderLineId,
            ),
          );
      }

      await tx.insert(transferOrderShipmentLines).values(shipmentLinesInsert);

      // 6) Execute Inventory Movement
      await this.inventoryService.recordInventoryMovement(tx, {
        entryNumber: `INTRA-OUT-${shipmentNumber}-${Date.now().toString().slice(-4)}`,
        sourceType: 'TRANSFER_OUT',
        sourceId: shipmentId,
        memo: `Intracompany Shipment ${shipmentNumber}`,
        userId: actor,
        lines: inventoryLines,
      });

      // 7) Update Order State
      await this.changeTransferState(
        transferOrderId,
        TRANSFER_ORDER_STATE.SHIPPED,
        actor,
        tx,
      );

      return { shipmentId, shipmentNumber };
    });
  }

  // -------------------------------------------------------------------------
  // Receiving
  // -------------------------------------------------------------------------

  async receiveTransferOrder(
    transferOrderId: string,
    destinationBinId: string,
    actor: string,
  ) {
    return await this.db.transaction(async (tx) => {
      const order = await tx.query.transferOrders.findFirst({
        where: eq(transferOrders.transferOrderId, transferOrderId),
      });

      if (!order) throw new NotFoundException('Transfer Order not found');
      if (order.stateCode !== TRANSFER_ORDER_STATE.SHIPPED) {
        throw new BadRequestException(
          'Transfer order must be shipped to receive',
        );
      }

      // 1) Verify destination bin is valid for the destination location
      const [destBin] = await tx
        .select({ binId: bins.binId })
        .from(bins)
        .innerJoin(zones, eq(bins.zoneId, zones.zoneId))
        .where(
          and(
            eq(zones.locationId, order.destinationLocationId),
            eq(bins.binId, destinationBinId),
          ),
        );

      if (!destBin) {
        throw new BadRequestException(
          'Invalid destination bin for receiving location',
        );
      }

      // 2) Get the INTRA_TRANSIT bin for the source location (where stock currently resides)
      const [transitBin] = await tx
        .select({ binId: bins.binId })
        .from(bins)
        .innerJoin(zones, eq(bins.zoneId, zones.zoneId))
        .where(
          and(
            eq(zones.locationId, order.sourceLocationId),
            eq(bins.binNumber, 'INTRA_TRANSIT'),
          ),
        );

      if (!transitBin) {
        throw new BadRequestException(
          'Source location is missing INTRA_TRANSIT system bin. Please contact support.',
        );
      }

      // 3) Find all shipments that haven't been fully received yet
      // For simplicity, we'll receive the entire 'shipped' balance of the order.
      const orderLines = await tx.query.transferOrderLines.findMany({
        where: eq(transferOrderLines.transferOrderId, transferOrderId),
      });

      let totalReceived = 0;
      const inventoryLines: {
        productId: string;
        binId: string;
        quantity: number;
      }[] = [];
      const receiptLinesInsert = [];

      // 4) Generate Receipt Number
      const receiptPrefix = `TRC-${new Date().toISOString().split('T')[0].replace(/-/g, '')}-`;
      const lastReceipt = await tx
        .select({ receiptNumber: transferOrderReceipts.receiptNumber })
        .from(transferOrderReceipts)
        .where(
          sql`${transferOrderReceipts.receiptNumber} LIKE ${receiptPrefix + '%'}`,
        )
        .orderBy(desc(transferOrderReceipts.receiptNumber))
        .limit(1);

      let nextNum = 1;
      if (lastReceipt.length > 0) {
        const parts = lastReceipt[0].receiptNumber.split('-');
        nextNum = parseInt(parts[2], 10) + 1;
      }
      const receiptNumber = `${receiptPrefix}${String(nextNum).padStart(3, '0')}`;
      const receiptId = uuidv4();

      await tx.insert(transferOrderReceipts).values({
        receiptId,
        transferOrderId,
        receiptNumber,
        stateCode: TRANSFER_ORDER_STATE.RECEIVED,
        receivedBy: actor,
      });

      for (const line of orderLines) {
        const shipped = parseFloat(line.quantityShipped || '0');
        const received = parseFloat(line.quantityReceived || '0');
        const toReceive = shipped - received;

        if (toReceive > 0) {
          totalReceived += toReceive;

          receiptLinesInsert.push({
            receiptLineId: uuidv4(),
            receiptId,
            transferOrderLineId: line.transferOrderLineId,
            productId: line.productId,
            quantity: toReceive.toString(),
            binId: destinationBinId,
          });

          // Decrease from INTRA_TRANSIT bin
          inventoryLines.push({
            productId: line.productId,
            binId: transitBin.binId,
            quantity: -toReceive,
          });

          // Increase into Destination Bin
          inventoryLines.push({
            productId: line.productId,
            binId: destinationBinId,
            quantity: toReceive,
          });

          // Update received quantity on order line
          await tx
            .update(transferOrderLines)
            .set({
              quantityReceived: sql`${transferOrderLines.quantityReceived} + ${toReceive.toString()}`,
            })
            .where(
              eq(
                transferOrderLines.transferOrderLineId,
                line.transferOrderLineId,
              ),
            );
        }
      }

      if (totalReceived === 0) {
        throw new BadRequestException(
          'No items pending receipt on this transfer order',
        );
      }

      await tx.insert(transferOrderReceiptLines).values(receiptLinesInsert);

      // 5) Execute Inventory Movement
      await this.inventoryService.recordInventoryMovement(tx, {
        entryNumber: `INTRA-IN-${receiptNumber}-${Date.now().toString().slice(-4)}`,
        sourceType: 'TRANSFER_IN',
        sourceId: receiptId,
        memo: `Intracompany Receipt ${receiptNumber}`,
        userId: actor,
        lines: inventoryLines,
      });

      // 6) Update Order State
      await this.changeTransferState(
        transferOrderId,
        TRANSFER_ORDER_STATE.RECEIVED,
        actor,
        tx,
      );

      return { receiptId, receiptNumber };
    });
  }

  /**
   * Universal changeState for Transfer Orders
   */
  async changeTransferState(
    transferOrderId: string,
    newState: TransferOrderState,
    actor: string,
    tx: DrizzleDB,
  ) {
    if (!VALID_TRANSFER_STATES.includes(newState)) {
      throw new BadRequestException(
        `Invalid transfer order state: '${newState}'`,
      );
    }

    const [order] = await tx
      .select({ stateCode: transferOrders.stateCode })
      .from(transferOrders)
      .where(eq(transferOrders.transferOrderId, transferOrderId));

    if (!order) {
      throw new NotFoundException(
        `Transfer Order ${transferOrderId} not found`,
      );
    }

    const allowed = TRANSFER_ORDER_TRANSITIONS[order.stateCode];
    if (!allowed || !allowed.includes(newState)) {
      throw new BadRequestException(
        `Cannot transition transfer order from '${order.stateCode}' to '${newState}'.`,
      );
    }

    const [updated] = await tx
      .update(transferOrders)
      .set({ stateCode: newState, modifiedOn: new Date() })
      .where(eq(transferOrders.transferOrderId, transferOrderId))
      .returning();

    await emitEvent(tx as any, {
      aggregateType: AggregateType.TRANSFER_ORDER,
      aggregateId: transferOrderId,
      eventType: 'status_changed',
      payload: {
        entity: 'transfer_order',
        entityId: transferOrderId,
        from: order.stateCode,
        to: newState,
      },
      actor,
    });

    return updated;
  }

  private async changePickState(
    pickId: string,
    newState: TransferOrderPickState,
    actor: string,
    tx: DrizzleDB,
  ) {
    const [existing] = await tx
      .select({
        stateCode: transferOrderPicks.stateCode,
        transferOrderId: transferOrderPicks.transferOrderId,
      })
      .from(transferOrderPicks)
      .where(eq(transferOrderPicks.pickId, pickId))
      .limit(1);

    if (!existing) return;
    if (existing.stateCode === newState) return;

    const allowed = TRANSFER_ORDER_PICK_TRANSITIONS[existing.stateCode];
    if (!allowed || !allowed.includes(newState)) {
      throw new BadRequestException(
        `Cannot transition transfer pick from '${existing.stateCode}' to '${newState}'.`,
      );
    }

    await tx
      .update(transferOrderPicks)
      .set({ stateCode: newState as any, modifiedOn: new Date() })
      .where(eq(transferOrderPicks.pickId, pickId));

    await emitEvent(tx as any, {
      aggregateType: AggregateType.TRANSFER_ORDER,
      aggregateId: existing.transferOrderId,
      eventType: 'status_changed',
      payload: {
        entity: 'pick',
        entityId: pickId,
        from: existing.stateCode,
        to: newState,
      },
      actor,
    });
  }
}

import {
  Injectable,
  Inject,
  NotFoundException,
  BadRequestException,
  Logger,
} from '@nestjs/common';
import { eq, sql, and } from 'drizzle-orm';
import { DRIZZLE } from '../drizzle/drizzle.module';
import type { DrizzleDB } from '../drizzle/drizzle.module';
import {
  products as coreProducts,
  productEvents,
  productSuppliers,
  productSupplierEvents,
  productUoms,
  productDefaultBins,
} from '../drizzle/modbm-core-schema';
import { emitEvent } from '../common/emit-event';
import { AggregateType } from '../common/event-types';
import {
  PRODUCT_TRANSITIONS,
  PRODUCT_STATE,
  ProductState,
} from '@modbm/shared';
import { calculateAuditTrail, AuditMode } from '../common/audit';
import {
  CreateProductDto,
  UpdateProductDto,
  AddSupplierDto,
  LinkBinDto,
} from './dto';

@Injectable()
export class ProductsWriteService {
  constructor(@Inject(DRIZZLE) private db: DrizzleDB) {}

  private readonly logger = new Logger(ProductsWriteService.name);

  /**
   * Create a new product in modbm_core.
   * Product number uniqueness is enforced by the DB UNIQUE constraint.
   */
  async create(dto: CreateProductDto, actor: string) {
    const result = await this.db.transaction(async (tx: DrizzleDB) => {
      const [product] = await tx
        .insert(coreProducts)
        .values({
          ...dto,
          createdBy: actor,
        })
        .returning();

      await tx.insert(productEvents).values({
        productId: product.productId,
        eventType: 'created',
        payload: dto,
        actor,
      });

      return product;
    });

    this.logger.log(
      `Product created: ${dto.productNumber} (ID: ${result.productId}) by ${actor}`,
    );
    return result;
  }

  /**
   * Update a product.
   */
  async update(id: string, dto: UpdateProductDto, actor: string) {
    const existing = await this.db
      .select()
      .from(coreProducts)
      .where(eq(coreProducts.productId, id))
      .limit(1);

    if (existing.length === 0) {
      throw new NotFoundException(`Product '${id}' not found`);
    }

    const result = await this.db.transaction(async (tx: DrizzleDB) => {
      const audit = calculateAuditTrail(dto, existing[0], AuditMode.DIFF);

      const [updated] = await tx
        .update(coreProducts)
        .set({
          ...audit.changes,
          modifiedOn: new Date(),
        })
        .where(eq(coreProducts.productId, id))
        .returning();

      if (audit.hasChanges) {
        // Specialized event for status change
        if (
          audit.changes.stateCode !== undefined &&
          Object.keys(audit.changes).length === 1
        ) {
          await tx.insert(productEvents).values({
            productId: id,
            eventType: 'status_changed',
            payload: {
              from: existing[0].stateCode,
              to: audit.changes.stateCode,
            },
            actor,
          });
        } else {
          await tx.insert(productEvents).values({
            productId: id,
            eventType: 'updated',
            payload: {
              changes: audit.changes,
              previousValues: audit.previousValues,
            },
            actor,
          });
        }
      }

      return updated;
    });

    this.logger.log(`Product updated: ${id} by ${actor}`);
    return result;
  }

  /**
   * Archive a product.
   */
  async archive(id: string, actor: string) {
    return await this.changeProductState(id, PRODUCT_STATE.ARCHIVED, actor);
  }

  /**
   * Unarchive a product.
   */
  async unarchive(id: string, actor: string) {
    const existing = await this.db
      .select()
      .from(coreProducts)
      .where(eq(coreProducts.productId, id))
      .limit(1);

    if (existing.length === 0) {
      throw new NotFoundException(`Product '${id}' not found`);
    }

    if (existing[0].stateCode !== PRODUCT_STATE.ARCHIVED) {
      throw new BadRequestException(`Product '${id}' is not archived`);
    }

    const lastEvent = await this.db
      .select()
      .from(productEvents)
      .where(
        sql`${productEvents.productId} = ${id} AND ${productEvents.eventType} = 'archived'`,
      )
      .orderBy(sql`${productEvents.createdOn} DESC`)
      .limit(1);

    const previousState =
      ((lastEvent[0]?.payload as Record<string, unknown>)?.from as string) ||
      PRODUCT_STATE.ACTIVE;

    return await this.changeProductState(
      id,
      previousState as ProductState,
      actor,
    );
  }

  /**
   * Centralised state transition logic for products.
   */
  async changeProductState(
    productId: string,
    newState: ProductState,
    actor: string,
    tx?: DrizzleDB,
  ) {
    const db = tx || this.db;

    const [existing] = await db
      .select()
      .from(coreProducts)
      .where(eq(coreProducts.productId, productId))
      .limit(1);

    if (!existing) {
      throw new NotFoundException(`Product '${productId}' not found`);
    }

    const currentState = existing.stateCode as ProductState;

    if (currentState === newState) {
      return existing;
    }

    // Validation
    const allowed = PRODUCT_TRANSITIONS[currentState] || [];
    if (!allowed.includes(newState)) {
      throw new BadRequestException(
        `Invalid product state transition: '${currentState}' -> '${newState}'. Valid next states: ${allowed.join(', ') || 'None'}`,
      );
    }

    const [updated] = await db
      .update(coreProducts)
      .set({ stateCode: newState as any, modifiedOn: new Date() })
      .where(eq(coreProducts.productId, productId))
      .returning();

    const targetTx = tx || this.db;
    await targetTx.insert(productEvents).values({
      productId,
      eventType:
        newState === PRODUCT_STATE.ARCHIVED ? 'archived' : 'status_changed',
      payload: {
        from: currentState,
        to: newState,
      },
      actor,
    });

    return updated;
  }

  /**
   * Add or Upsert a supplier to a product.
   */
  async addSupplier(productId: string, dto: AddSupplierDto, actor: string) {
    // Verify product exists
    const existingProduct = await this.db
      .select({ id: coreProducts.productId })
      .from(coreProducts)
      .where(eq(coreProducts.productId, productId))
      .limit(1);

    if (!existingProduct.length) {
      throw new NotFoundException(`Product not found`);
    }

    const payload = {
      productId,
      vendorId: dto.vendorId,
      supplierPartNumber: dto.supplierPartNumber || null,
      costPrice: dto.costPrice ? dto.costPrice.toString() : '0',
      effectiveFrom: dto.effectiveFrom ? new Date(dto.effectiveFrom) : null,
      effectiveTo: dto.effectiveTo ? new Date(dto.effectiveTo) : null,
      stateCode: PRODUCT_STATE.ACTIVE,
      modifiedOn: new Date(),
    };

    return await this.db.transaction(async (tx) => {
      const [mapping] = await tx
        .insert(productSuppliers)
        .values({
          ...payload,
          createdBy: actor,
          createdOn: new Date(),
        })
        .onConflictDoUpdate({
          target: [productSuppliers.vendorId, productSuppliers.productId],
          set: {
            ...payload, // This brings back archived versions as "active" with the latest data
          },
        })
        .returning();

      await tx.insert(productSupplierEvents).values({
        productSupplierId: mapping.productSupplierId,
        eventType: 'linked',
        payload: dto,
        actor,
      });

      return mapping;
    });
  }

  /**
   * Remove (Archive) a supplier from a product.
   */
  async removeSupplier(productId: string, vendorId: string, actor: string) {
    return await this.db.transaction(async (tx) => {
      const [mapping] = await tx
        .update(productSuppliers)
        .set({ stateCode: PRODUCT_STATE.ARCHIVED, modifiedOn: new Date() })
        .where(
          sql`${productSuppliers.productId} = ${productId} AND ${productSuppliers.vendorId} = ${vendorId}`,
        )
        .returning();

      if (!mapping) {
        throw new NotFoundException('Supplier mapping not found');
      }

      await tx.insert(productSupplierEvents).values({
        productSupplierId: mapping.productSupplierId,
        eventType: 'unlinked',
        payload: { stateCode: PRODUCT_STATE.ARCHIVED },
        actor,
      });

      return mapping;
    });
  }

  /**
   * Add a UoM conversion to a product.
   */
  async addUom(
    productId: string,
    dto: { uomCode: string; ratio: string; barcode?: string },
    actor: string,
  ) {
    const existing = await this.db
      .select({ id: coreProducts.productId })
      .from(coreProducts)
      .where(eq(coreProducts.productId, productId))
      .limit(1);

    if (!existing.length) {
      throw new NotFoundException(`Product not found`);
    }

    return await this.db.transaction(async (tx) => {
      const [uom] = await tx
        .insert(productUoms)
        .values({
          productId,
          uomCode: dto.uomCode,
          ratio: dto.ratio,
          barcode: dto.barcode || null,
        })
        .onConflictDoUpdate({
          target: [productUoms.productId, productUoms.uomCode],
          set: {
            ratio: dto.ratio,
            barcode: dto.barcode || null,
          },
        })
        .returning();

      await tx.insert(productEvents).values({
        productId,
        eventType: 'uom_added',
        payload: { uomCode: dto.uomCode, ratio: dto.ratio },
        actor,
      });

      return uom;
    });
  }

  /**
   * Remove a UoM conversion from a product.
   */
  async removeUom(productId: string, productUomId: string, actor: string) {
    const existing = await this.db
      .select()
      .from(productUoms)
      .where(
        and(
          eq(productUoms.productUomId, productUomId),
          eq(productUoms.productId, productId),
        ),
      )
      .limit(1);

    if (!existing.length) {
      throw new NotFoundException('UoM conversion not found');
    }

    await this.db.transaction(async (tx) => {
      await tx
        .delete(productUoms)
        .where(eq(productUoms.productUomId, productUomId));

      await tx.insert(productEvents).values({
        productId,
        eventType: 'uom_removed',
        payload: { uomCode: existing[0].uomCode, ratio: existing[0].ratio },
        actor,
      });
    });

    return { deleted: true };
  }

  /**
   * Link a default bin to a product.
   */
  async linkDefaultBin(productId: string, dto: LinkBinDto, actor: string) {
    const existing = await this.db
      .select({ id: coreProducts.productId })
      .from(coreProducts)
      .where(eq(coreProducts.productId, productId))
      .limit(1);

    if (!existing.length) {
      throw new NotFoundException(`Product not found`);
    }

    return await this.db.transaction(async (tx) => {
      if (dto.isPrimaryPerLocation) {
        // Demote existing primary pins in that location
        await tx
          .update(productDefaultBins)
          .set({ isPrimaryPerLocation: false, modifiedOn: new Date() })
          .where(
            and(
              eq(productDefaultBins.productId, productId),
              eq(productDefaultBins.locationId, dto.locationId),
            ),
          );
      }

      const [binLink] = await tx
        .insert(productDefaultBins)
        .values({
          productId,
          locationId: dto.locationId,
          binId: dto.binId,
          isPrimaryPerLocation: dto.isPrimaryPerLocation ?? true,
          minQuantity: dto.minQuantity || '0',
          maxQuantity: dto.maxQuantity || null,
        })
        .onConflictDoUpdate({
          target: [
            productDefaultBins.productId,
            productDefaultBins.locationId,
            productDefaultBins.binId,
          ],
          set: {
            isPrimaryPerLocation: dto.isPrimaryPerLocation ?? true,
            minQuantity: dto.minQuantity || '0',
            maxQuantity: dto.maxQuantity || null,
            modifiedOn: new Date(),
          },
        })
        .returning();

      await tx.insert(productEvents).values({
        productId,
        eventType: 'updated',
        payload: {
          action: 'linked_default_bin',
          binId: dto.binId,
          isPrimary: dto.isPrimaryPerLocation,
        },
        actor,
      });

      return binLink;
    });
  }

  /**
   * Remove a default bin mapping from a product.
   */
  async removeDefaultBin(productDefaultBinId: string, actor: string) {
    const existing = await this.db
      .select()
      .from(productDefaultBins)
      .where(eq(productDefaultBins.productDefaultBinId, productDefaultBinId))
      .limit(1);

    if (!existing.length) {
      throw new NotFoundException('Default bin mapping not found');
    }

    await this.db.transaction(async (tx) => {
      await tx
        .delete(productDefaultBins)
        .where(eq(productDefaultBins.productDefaultBinId, productDefaultBinId));

      await tx.insert(productEvents).values({
        productId: existing[0].productId,
        eventType: 'updated',
        payload: { action: 'unlinked_default_bin', binId: existing[0].binId },
        actor,
      });
    });

    return { deleted: true };
  }
}

import {
  Injectable,
  Inject,
  NotFoundException,
  BadRequestException,
  Logger,
} from '@nestjs/common';
import { DRIZZLE } from '../drizzle/drizzle.module';
import type { DrizzleDB } from '../drizzle/drizzle.module';
import {
  purchaseOrders,
  purchaseOrderLineItems,
  purchaseOrderEvents,
  outbox,
  suppliers as coreSuppliers,
  products,
  productUoms,
  locations,
  backorders,
  purchaseInvoices,
  purchaseInvoiceLines,
  taxCategories,
} from '../drizzle/modbm-core-schema';
import { eq, or, ilike, desc, sql, inArray, and } from 'drizzle-orm';
import { InventoryService } from '../inventory/inventory.service';
import { PaginationQuery, parsePagination } from '../common/pagination';
import { calculateAuditTrail, AuditMode } from '../common/audit';
import { emitEvent } from '../common/emit-event';
import { AggregateType } from '../common/event-types';
import {
  PURCHASE_ORDER_STATE,
  PURCHASE_ORDER_TRANSITIONS,
  getValidStates,
  getAllowedTransitions,
  computeLinePriceForStorage,
  PURCHASE_INVOICE_STATE,
  BACKORDER_TRANSITIONS,
  BACKORDER_STATE,
  OPEN_PURCHASE_ORDER_STATES,
} from '@modbm/shared';
import type { PurchaseOrderState } from '@modbm/shared';

export interface UnifiedPurchaseOrderRow {
  id: string;
  orderNumber: string;
  name: string;
  vendorName: string;
  referenceNumber: string;
  stateCode: string;

  createdBy: string;
  createdOn: string | null;
  totalPrice: string | null;
  currencyCode: string | null;
}

import { SuppliersService } from '../suppliers/suppliers.service';
import { TaxCategoriesService } from '../tax/tax-categories.service';
import { AppConfigService } from '../settings/app-config.service';

@Injectable()
export class PurchaseOrdersService {
  constructor(
    @Inject(DRIZZLE) private db: DrizzleDB,
    private readonly inventoryService: InventoryService,
    private readonly suppliersService: SuppliersService,
    private readonly taxService: TaxCategoriesService,
    private readonly appConfig: AppConfigService,
  ) {}

  private readonly logger = new Logger(PurchaseOrdersService.name);

  private async resolveTaxForLine(
    tx: any,
    productId?: string,
    taxCategoryIdOverride?: string,
  ): Promise<{ taxCategoryId: string; rate: number }> {
    if (taxCategoryIdOverride) {
      try {
        const catRows = await tx
          .select()
          .from(taxCategories)
          .where(eq(taxCategories.taxCategoryId, taxCategoryIdOverride))
          .limit(1);
        if (catRows.length > 0) {
          return {
            taxCategoryId: catRows[0].taxCategoryId,
            rate: parseFloat(catRows[0].rate ?? '0'),
          };
        }
      } catch (err) {
        // Ignore and fallback
      }
    }

    if (productId && productId !== '00000000-0000-0000-0000-000000000000') {
      const pRows = await tx
        .select({ taxCategoryId: products.purchaseTaxCategoryId })
        .from(products)
        .where(eq(products.productId, productId))
        .limit(1);

      if (pRows.length > 0 && pRows[0].taxCategoryId) {
        try {
          const catRows = await tx
            .select()
            .from(taxCategories)
            .where(eq(taxCategories.taxCategoryId, pRows[0].taxCategoryId))
            .limit(1);
          if (catRows.length > 0) {
            return {
              taxCategoryId: catRows[0].taxCategoryId,
              rate: parseFloat(catRows[0].rate ?? '0'),
            };
          }
        } catch (err) {
          this.logger.warn(
            `Product ${productId} had invalid tax category ID: ${pRows[0].taxCategoryId}`,
          );
        }
      }
    }

    const defaultGstRows = await tx
      .select()
      .from(taxCategories)
      .where(eq(taxCategories.isDefault, true))
      .limit(1);
    if (defaultGstRows.length === 0) {
      throw new NotFoundException('No default tax category configured');
    }
    return {
      taxCategoryId: defaultGstRows[0].taxCategoryId,
      rate: parseFloat(defaultGstRows[0].rate ?? '0'),
    };
  }

  async create(createDto: any, userId: string) {
    return await this.db.transaction(async (tx) => {
      if (!createDto.deliveryLocationId) {
        throw new BadRequestException(
          'Delivery location is mandatory for all purchase orders.',
        );
      }

      // Ensure location exists
      const [loc] = await tx
        .select()
        .from(locations)
        .where(eq(locations.locationId, createDto.deliveryLocationId))
        .limit(1);

      if (!loc) {
        throw new BadRequestException('Invalid delivery location ID.');
      }

      // Create PO
      let order;
      try {
        const [inserted] = await tx
          .insert(purchaseOrders)
          .values({
            orderNumber: createDto.orderNumber, // In reality, should auto-gen
            name: createDto.name,
            vendorId: createDto.vendorId,
            currencyCode:
              createDto.currencyCode || this.appConfig.homeCurrency(),
            notes: createDto.notes,
            createdBy: userId,
            stateCode: PURCHASE_ORDER_STATE.DRAFT,
            deliveryLocationId: createDto.deliveryLocationId,
            referenceNumber: createDto.referenceNumber,
          })
          .returning();
        order = inserted;
      } catch (err: any) {
        console.error('PO INSERT ERROR:', err.message || err);
        throw err;
      }

      // Create lines if any
      if (createDto.lines && createDto.lines.length > 0) {
        const lineValues: any[] = [];
        let index = 0;
        for (const line of createDto.lines) {
          const { taxCategoryId, rate } = await this.resolveTaxForLine(
            tx,
            line.productId,
            line.taxCategoryId,
          );
          const pricing = computeLinePriceForStorage({
            quantity: parseFloat(line.quantity || '0'),
            pricePerUnit: parseFloat(line.pricePerUnit || '0'),
            discountPercentage: parseFloat(line.discountPercentage || '0'),
            taxRate: rate,
          });

          lineValues.push({
            purchaseOrderId: order.purchaseOrderId,
            lineNumber: index + 1,
            productId: line.productId,
            productDescription: line.productDescription,
            quantity: line.quantity.toString(),
            pricePerUnit: line.pricePerUnit.toString(),
            discountPercentage: line.discountPercentage?.toString() || '0',
            unitOfMeasure: line.unitOfMeasure || 'EA',
            amount: pricing.amount,
            tax: pricing.tax,
            totalAmount: pricing.totalAmount,
            taxCategoryId,
          });
          index++;
        }

        await tx.insert(purchaseOrderLineItems).values(lineValues);
      }

      await emitEvent(tx, {
        aggregateType: AggregateType.PURCHASE_ORDER,
        aggregateId: order.purchaseOrderId,
        eventType: 'created',
        payload: {
          orderNumber: order.orderNumber,
          vendorId: createDto.vendorId,
          lineCount: createDto.lines?.length || 0,
        },
        actor: userId,
      });

      return this.findOne(order.purchaseOrderId, tx);
    });
  }

  async findAll(query?: PaginationQuery) {
    const { page, limit, offset, searchTerm, includeArchived, days } =
      parsePagination(query);
    const stateFilter = query?.state ?? null;

    // --- App orders ---
    let appQuery = this.db
      .select({
        id: purchaseOrders.purchaseOrderId,
        orderNumber: purchaseOrders.orderNumber,
        name: purchaseOrders.name,
        vendorName: coreSuppliers.name,
        referenceNumber: purchaseOrders.referenceNumber,
        stateCode: purchaseOrders.stateCode,
        source: sql<string>`'app'`.as('source'),
        createdBy: purchaseOrders.createdBy,
        createdOn: purchaseOrders.createdOn,
        currencyCode: purchaseOrders.currencyCode,
      })
      .from(purchaseOrders)
      .leftJoin(
        coreSuppliers,
        eq(purchaseOrders.vendorId, coreSuppliers.vendorId),
      )
      .orderBy(desc(purchaseOrders.createdOn))
      .$dynamic();

    const conditions = [];

    if (searchTerm) {
      conditions.push(
        or(
          ilike(purchaseOrders.orderNumber, searchTerm),
          ilike(purchaseOrders.name, searchTerm),
          ilike(coreSuppliers.name, searchTerm),
        ),
      );
    }

    if (!includeArchived) {
      conditions.push(sql`${purchaseOrders.stateCode} != 'archived'`);
    }

    if (days && days > 0) {
      conditions.push(
        sql`${purchaseOrders.createdOn} >= NOW() - INTERVAL '1 day' * ${days}`,
      );
    }

    if (conditions.length > 0) {
      appQuery = appQuery.where(and(...conditions));
    }

    const appRows = await appQuery;

    // --- Aggregate line totals per app order ---
    const appTotalMap = new Map<string, string>();
    const appOrderIds = appRows.map((r) => r.id);
    if (appOrderIds.length > 0) {
      const totals = await this.db
        .select({
          purchaseOrderId: purchaseOrderLineItems.purchaseOrderId,
          total: sql<string>`COALESCE(SUM(${purchaseOrderLineItems.totalAmount}::numeric), 0)::text`,
        })
        .from(purchaseOrderLineItems)
        .where(inArray(purchaseOrderLineItems.purchaseOrderId, appOrderIds))
        .groupBy(purchaseOrderLineItems.purchaseOrderId);

      for (const row of totals) {
        appTotalMap.set(row.purchaseOrderId, row.total);
      }
    }

    const unified: UnifiedPurchaseOrderRow[] = appRows.map((r) => {
      return {
        id: r.id,
        orderNumber: r.orderNumber ?? '',
        name: r.name ?? '',
        vendorName: r.vendorName ?? '',
        referenceNumber: r.referenceNumber ?? '',
        stateCode: r.stateCode ?? PURCHASE_ORDER_STATE.DRAFT,
        createdBy: r.createdBy ?? '',
        createdOn: r.createdOn ? new Date(r.createdOn).toISOString() : null,
        totalPrice: appTotalMap.get(r.id) ?? null,
        currencyCode: r.currencyCode ?? 'EUR',
      };
    });

    const paginated = unified.slice(offset, offset + limit);

    return { data: paginated, page, limit, total: unified.length };
  }

  async findOne(id: string, tx: any = this.db) {
    const rawOrder = await tx
      .select()
      .from(purchaseOrders)
      .leftJoin(
        coreSuppliers,
        eq(purchaseOrders.vendorId, coreSuppliers.vendorId),
      )
      .leftJoin(
        locations,
        eq(purchaseOrders.deliveryLocationId, locations.locationId),
      )
      .where(eq(purchaseOrders.purchaseOrderId, id))
      .limit(1)
      .then((res: any[]) => res[0]);

    if (!rawOrder) {
      throw new NotFoundException(`Purchase Order ${id} not found`);
    }

    // Support both tuple JOIN structure (drizzle live engine) and flat structure (jest mocks)
    const poEntity = rawOrder.purchase_orders || rawOrder;
    const vendorName = rawOrder.suppliers?.name || poEntity.vendorId;
    const locationName =
      rawOrder.locations?.name || poEntity.deliveryLocationId;

    const order = {
      ...poEntity,
      vendorName,
      locationName,
      customerName: vendorName,
    };

    const rawLines = await tx
      .select()
      .from(purchaseOrderLineItems)
      .leftJoin(
        products,
        eq(purchaseOrderLineItems.productId, products.productId),
      )
      .where(eq(purchaseOrderLineItems.purchaseOrderId, id))
      .orderBy(purchaseOrderLineItems.lineNumber);

    const lines = rawLines.map((r: any) => {
      const lineEntity = r.purchase_order_lines || r;
      return {
        ...lineEntity,
        productNumber: r.products?.productNumber || lineEntity.productId,
        baseUom: r.products?.baseUom,
      };
    });

    const productIds: string[] = Array.from(
      new Set(
        lines
          .map((l: any) => l.productId as string | null)
          .filter(
            (id: any): id is string =>
              id !== null && id !== '00000000-0000-0000-0000-000000000000',
          ),
      ),
    );

    let allUoms: any[] = [];
    if (productIds.length > 0) {
      allUoms = await tx
        .select()
        .from(productUoms)
        .where(inArray(productUoms.productId, productIds));
    }

    const linesWithUoms = lines.map((line: any) => {
      return {
        ...line,
        productUoms: allUoms.filter((u) => u.productId === line.productId),
      };
    });

    const events = await tx
      .select()
      .from(purchaseOrderEvents)
      .where(eq(purchaseOrderEvents.purchaseOrderId, id))
      .orderBy(purchaseOrderEvents.createdOn);

    // Alias PO-specific fields to sales-order field names so the shared
    // frontend components work without fork. The canonical PO fields are
    // also included so callers that know about POs can use them directly.
    return {
      ...order,
      salesOrderId: order.purchaseOrderId,
      source: 'app' as const,
      lines: linesWithUoms.map((l: any) => ({
        ...l,
        salesOrderLineId: l.purchaseOrderLineId,
      })),
      events,
    };
  }

  async changePurchaseOrderState(
    id: string,
    stateCode: PurchaseOrderState,
    actor: string = 'system',
    tx?: DrizzleDB,
  ) {
    const db = tx || this.db;
    const validStates = getValidStates(PURCHASE_ORDER_TRANSITIONS);
    if (!validStates.includes(stateCode)) {
      throw new BadRequestException(`Invalid state: '${stateCode}'`);
    }

    const existing = await this.findOne(id);
    if (!existing) {
      throw new NotFoundException(`Purchase Order ${id} not found`);
    }

    const allowed = getAllowedTransitions(
      PURCHASE_ORDER_TRANSITIONS,
      existing.stateCode,
    );
    if (!allowed.includes(stateCode)) {
      throw new BadRequestException(
        `Cannot transition from '${existing.stateCode}' to '${stateCode}'. ` +
          `Allowed transitions: ${allowed.join(', ') || 'none'}`,
      );
    }

    if (
      existing.stateCode === PURCHASE_ORDER_STATE.DRAFT &&
      stateCode === PURCHASE_ORDER_STATE.ORDERED
    ) {
      if (!existing.deliveryLocationId) {
        throw new BadRequestException(
          'Cannot order: A Delivery Location must be specified.',
        );
      }

      const vendor = await this.suppliersService.findOne(existing.vendorId);
      if (vendor.isPurchasingBlocked || vendor.groupIsPurchasingBlocked) {
        throw new BadRequestException(
          'Cannot order: Supplier or Supplier Group is blocked for purchasing.',
        );
      }
    }

    if (stateCode === PURCHASE_ORDER_STATE.CANCELLED) {
      const anyReceived = existing.lines.some(
        (l: any) => parseFloat(l.quantityReceived || '0') > 0,
      );
      if (anyReceived) {
        throw new BadRequestException(
          'Cannot cancel a Purchase Order that has received goods. Use Close Short instead.',
        );
      }

      const invoiceLines = await this.db
        .select()
        .from(purchaseInvoices)
        .where(eq(purchaseInvoices.purchaseOrderId, id))
        .limit(1);

      if (invoiceLines.length > 0) {
        throw new BadRequestException(
          'Cannot cancel a Purchase Order that has attached invoices.',
        );
      }
    }

    if (stateCode === PURCHASE_ORDER_STATE.CLOSED_SHORT) {
      for (const line of existing.lines) {
        const received = parseFloat(line.quantityReceived || '0');
        if (received > 0) {
          const [{ totalInvoiced }] = await this.db
            .select({
              totalInvoiced:
                sql<string>`COALESCE(SUM(CAST(${purchaseInvoiceLines.quantityInvoiced} AS NUMERIC)), 0)::text` as any,
            })
            .from(purchaseInvoiceLines)
            .innerJoin(
              purchaseInvoices,
              eq(purchaseInvoiceLines.invoiceId, purchaseInvoices.invoiceId),
            )
            .where(
              and(
                eq(
                  purchaseInvoiceLines.purchaseOrderLineId,
                  line.purchaseOrderLineId,
                ),
                eq(purchaseInvoices.stateCode, PURCHASE_INVOICE_STATE.INVOICED),
              ),
            );
          const invoiced = parseFloat(totalInvoiced || '0');
          if (received > invoiced + 0.001) {
            throw new BadRequestException(
              `Cannot close short: Received quantities for product ${line.productNumber} must be fully invoiced first. Received: ${received}, Invoiced: ${invoiced}`,
            );
          }
        }
      }
    }

    return await db.transaction(async (tx: DrizzleDB) => {
      const updated = await this.updateStateInternal(id, stateCode, actor, tx);

      if (
        stateCode === PURCHASE_ORDER_STATE.CANCELLED ||
        stateCode === PURCHASE_ORDER_STATE.CLOSED_SHORT
      ) {
        const affected = await tx
          .select({ id: backorders.backorderId })
          .from(backorders)
          .where(eq(backorders.purchaseOrderId, id));
        for (const b of affected) {
          await this.changeBackorderState(b.id, 'pending_supply', actor, tx);
        }

        await tx
          .update(backorders)
          .set({
            purchaseOrderId: null,
            purchaseOrderLineId: null,
            modifiedOn: new Date(),
          })
          .where(eq(backorders.purchaseOrderId, id));
      }

      return updated;
    });
  }

  private async changeBackorderState(
    backorderId: string,
    newState: string,
    actor: string,
    tx: DrizzleDB,
  ) {
    const [existing] = await tx
      .select({
        stateCode: backorders.stateCode,
        salesOrderId: backorders.salesOrderId,
      })
      .from(backorders)
      .where(eq(backorders.backorderId, backorderId))
      .limit(1);

    if (!existing) return;

    const allowed = BACKORDER_TRANSITIONS[existing.stateCode] || [];
    if (!allowed.includes(newState)) {
      // Just log and skip if not allowed? No, let's be strict.
      // But during mass reset it might be already in that state.
      if (existing.stateCode === newState) return;
      throw new BadRequestException(
        `Cannot transition backorder ${backorderId} from ${existing.stateCode} to ${newState}`,
      );
    }

    await tx
      .update(backorders)
      .set({ stateCode: newState as any, modifiedOn: new Date() })
      .where(eq(backorders.backorderId, backorderId));

    await emitEvent(tx, {
      aggregateType: AggregateType.SALES_ORDER,
      aggregateId: existing.salesOrderId,
      eventType: 'status_changed',
      payload: {
        entity: 'backorder',
        entityId: backorderId,
        from: existing.stateCode,
        to: newState,
      },
      actor,
    });
  }

  /**
   * Archive a purchase order.
   */
  async archive(id: string, actor: string) {
    const existing = await this.findOne(id);

    if (
      existing.stateCode !== PURCHASE_ORDER_STATE.RECEIVED &&
      existing.stateCode !== PURCHASE_ORDER_STATE.CANCELLED
    ) {
      throw new BadRequestException(
        `Purchase Order must be 'received' or 'cancelled' to be archived (current state: '${existing.stateCode}')`,
      );
    }

    return await this.changePurchaseOrderState(
      id,
      PURCHASE_ORDER_STATE.ARCHIVED,
      actor,
    );
  }

  /**
   * Unarchive a purchase order.
   */
  async unarchive(id: string, actor: string) {
    const existing = await this.findOne(id);

    if (existing.stateCode !== PURCHASE_ORDER_STATE.ARCHIVED) {
      throw new BadRequestException(`Purchase Order is not archived`);
    }

    // Default to cancelled since no event store exists for POs yet
    return await this.changePurchaseOrderState(
      id,
      PURCHASE_ORDER_STATE.CANCELLED,
      actor,
    );
  }

  async addLine(orderId: string, lineDto: any, actor: string = 'system') {
    return await this.db.transaction(async (tx) => {
      const existing = await this.findOne(orderId, tx);
      if (existing.stateCode !== PURCHASE_ORDER_STATE.DRAFT) {
        throw new BadRequestException(
          'Can only add lines to draft purchase orders',
        );
      }

      const maxLine = existing.lines.reduce(
        (max: number, l: any) => Math.max(max, l.lineNumber || 0),
        0,
      );

      const qty = parseFloat(lineDto.quantity || '1');
      const price = parseFloat(lineDto.pricePerUnit || '0');
      const disc = parseFloat(lineDto.discountPercentage || '0');
      const { taxCategoryId, rate } = await this.resolveTaxForLine(
        tx,
        lineDto.productId,
        lineDto.taxCategoryId,
      );
      const pricing = computeLinePriceForStorage({
        quantity: qty,
        pricePerUnit: price,
        discountPercentage: disc,
        taxRate: rate,
      });

      await tx.insert(purchaseOrderLineItems).values({
        purchaseOrderId: orderId,
        lineNumber: maxLine + 1,
        productId: lineDto.productId,
        productDescription: lineDto.productDescription,
        quantity: lineDto.quantity?.toString() || '1',
        pricePerUnit: lineDto.pricePerUnit?.toString() || '0',
        discountPercentage: lineDto.discountPercentage?.toString() || '0',
        unitOfMeasure: lineDto.unitOfMeasure || 'EA',
        amount: pricing.amount,
        tax: pricing.tax,
        totalAmount: pricing.totalAmount,
        taxCategoryId,
      });

      await emitEvent(tx, {
        aggregateType: AggregateType.PURCHASE_ORDER,
        aggregateId: orderId,
        eventType: 'line_added',
        payload: {
          productId: lineDto.productId,
          quantity: lineDto.quantity,
          pricePerUnit: lineDto.pricePerUnit,
        },
        actor,
      });

      return this.findOne(orderId, tx);
    });
  }

  async updateLine(
    orderId: string,
    lineId: string,
    lineDto: any,
    actor: string = 'system',
  ) {
    return await this.db.transaction(async (tx) => {
      const existing = await this.findOne(orderId, tx);
      if (existing.stateCode !== PURCHASE_ORDER_STATE.DRAFT) {
        throw new BadRequestException(
          'Can only update lines on draft purchase orders',
        );
      }

      const updateFields: any = {};
      if (lineDto.quantity !== undefined)
        updateFields.quantity = lineDto.quantity.toString();
      if (lineDto.pricePerUnit !== undefined)
        updateFields.pricePerUnit = lineDto.pricePerUnit.toString();
      if (lineDto.discountPercentage !== undefined)
        updateFields.discountPercentage = lineDto.discountPercentage.toString();
      if (lineDto.productDescription !== undefined)
        updateFields.productDescription = lineDto.productDescription;
      if (lineDto.unitOfMeasure !== undefined)
        updateFields.unitOfMeasure = lineDto.unitOfMeasure;
      if (lineDto.taxCategoryId !== undefined)
        updateFields.taxCategoryId = lineDto.taxCategoryId;

      // Recalculate amount if qty, price, discount, or tax changed
      if (
        lineDto.quantity !== undefined ||
        lineDto.pricePerUnit !== undefined ||
        lineDto.discountPercentage !== undefined ||
        lineDto.taxCategoryId !== undefined
      ) {
        const line = existing.lines.find(
          (l: any) => l.purchaseOrderLineId === lineId,
        );
        const qty = parseFloat(
          lineDto.quantity?.toString() || line?.quantity || '0',
        );
        const price = parseFloat(
          lineDto.pricePerUnit?.toString() || line?.pricePerUnit || '0',
        );
        const disc = parseFloat(
          lineDto.discountPercentage?.toString() ||
            line?.discountPercentage ||
            '0',
        );

        let targetGst = line.taxCategoryId;
        if (lineDto.taxCategoryId !== undefined) {
          targetGst = lineDto.taxCategoryId;
        }

        const resolved = await this.resolveTaxForLine(
          tx,
          line.productId,
          targetGst,
        );
        updateFields.taxCategoryId = resolved.taxCategoryId;

        const pricing = computeLinePriceForStorage({
          quantity: qty,
          pricePerUnit: price,
          discountPercentage: disc,
          taxRate: resolved.rate,
        });
        updateFields.amount = pricing.amount;
        updateFields.tax = pricing.tax;
        updateFields.totalAmount = pricing.totalAmount;
      }

      await tx
        .update(purchaseOrderLineItems)
        .set(updateFields)
        .where(eq(purchaseOrderLineItems.purchaseOrderLineId, lineId));

      await emitEvent(tx, {
        aggregateType: AggregateType.PURCHASE_ORDER,
        aggregateId: orderId,
        eventType: 'line_updated',
        payload: {
          lineId,
          changes: updateFields,
        },
        actor,
      });

      return this.findOne(orderId, tx);
    });
  }

  async removeLine(orderId: string, lineId: string, actor: string = 'system') {
    return await this.db.transaction(async (tx) => {
      const existing = await this.findOne(orderId, tx);
      if (existing.stateCode !== PURCHASE_ORDER_STATE.DRAFT) {
        throw new BadRequestException(
          'Can only remove lines from draft purchase orders',
        );
      }

      // Reset associated demand records so they reappear as open demand
      await tx
        .update(backorders)
        .set({
          purchaseOrderId: null,
          purchaseOrderLineId: null,
          stateCode: 'pending_supply',
        })
        .where(eq(backorders.purchaseOrderLineId, lineId));

      await tx
        .delete(purchaseOrderLineItems)
        .where(eq(purchaseOrderLineItems.purchaseOrderLineId, lineId));

      await emitEvent(tx, {
        aggregateType: AggregateType.PURCHASE_ORDER,
        aggregateId: orderId,
        eventType: 'line_removed',
        payload: { lineId },
        actor,
      });

      return this.findOne(orderId, tx);
    });
  }

  async update(id: string, updateDto: any, userId: string) {
    return await this.db.transaction(async (tx) => {
      const existing = await this.findOne(id, tx);
      if (existing.stateCode !== PURCHASE_ORDER_STATE.DRAFT) {
        throw new BadRequestException('Can only update draft purchase orders');
      }

      const [updated] = await tx
        .update(purchaseOrders)
        .set({
          name: updateDto.name,
          vendorId: updateDto.vendorId,
          currencyCode: updateDto.currencyCode,
          notes: updateDto.notes,
          stateCode: updateDto.stateCode, // allow transition to 'ordered'
          deliveryLocationId: updateDto.deliveryLocationId,
          referenceNumber: updateDto.referenceNumber,
          modifiedOn: new Date(),
        })
        .where(eq(purchaseOrders.purchaseOrderId, id))
        .returning();

      // For simplicity in this demo, we're not doing full line-item syncing
      // Usually you'd use a delta technique or delete/recreate.
      // If updating lines, delete and recreate for simplicity.
      if (updateDto.lines) {
        await tx
          .delete(purchaseOrderLineItems)
          .where(eq(purchaseOrderLineItems.purchaseOrderId, id));

        if (updateDto.lines.length > 0) {
          const lineValues: any[] = [];
          let index = 0;
          for (const line of updateDto.lines) {
            const qty = parseFloat(line.quantity || '0');
            const price = parseFloat(line.pricePerUnit || '0');
            const disc = parseFloat(line.discountPercentage || '0');
            const { taxCategoryId, rate } = await this.resolveTaxForLine(
              line.productId,
              line.taxCategoryId,
            );
            const pricing = computeLinePriceForStorage({
              quantity: qty,
              pricePerUnit: price,
              discountPercentage: disc,
              taxRate: rate,
            });
            lineValues.push({
              purchaseOrderId: id,
              lineNumber: index + 1,
              productId: line.productId,
              productDescription: line.productDescription,
              quantity: line.quantity.toString(),
              pricePerUnit: line.pricePerUnit.toString(),
              unitOfMeasure: line.unitOfMeasure || 'EA',
              amount: pricing.amount,
              tax: pricing.tax,
              totalAmount: pricing.totalAmount,
              taxCategoryId,
            });
            index++;
          }
          await tx.insert(purchaseOrderLineItems).values(lineValues);
        }

        const audit = calculateAuditTrail(updateDto, existing, AuditMode.DIFF);
        if (audit.hasChanges) {
          await emitEvent(tx, {
            aggregateType: AggregateType.PURCHASE_ORDER,
            aggregateId: id,
            eventType: 'updated',
            payload: {
              changes: audit.changes,
              previousValues: audit.previousValues,
              linesCount: updateDto.lines?.length,
            },
            actor: userId,
          });
        }
      }

      return this.findOne(id, tx);
    });
  }

  async findPendingLines(productId?: string, vendorId?: string) {
    if (!productId && !vendorId) {
      throw new BadRequestException(
        'Either productId or vendorId is required to find pending lines',
      );
    }

    const conditions = [
      inArray(purchaseOrders.stateCode, [
        PURCHASE_ORDER_STATE.ORDERED,
        PURCHASE_ORDER_STATE.PARTIALLY_RECEIVED,
        PURCHASE_ORDER_STATE.RECEIVED,
        PURCHASE_ORDER_STATE.LEGACY,
      ]),
    ];

    // When filtering by productId (used from returns/other flows),
    // keep the quantity filter to only show lines still pending receipt.
    if (productId) {
      conditions.push(eq(purchaseOrderLineItems.productId, productId));
      conditions.push(
        sql`COALESCE(CAST(${purchaseOrderLineItems.quantityReceived} AS NUMERIC), 0) < CAST(${purchaseOrderLineItems.quantity} AS NUMERIC)`,
      );
    }

    if (vendorId) {
      conditions.push(eq(purchaseOrders.vendorId, vendorId));
    }

    // Subquery: total quantity already invoiced for each PO line
    const invoicedSubquery = this.db
      .select({
        purchaseOrderLineId: purchaseInvoiceLines.purchaseOrderLineId,
        totalInvoiced:
          sql<string>`COALESCE(SUM(CAST(${purchaseInvoiceLines.quantityInvoiced} AS NUMERIC)), 0)::text`.as(
            'total_invoiced',
          ),
      })
      .from(purchaseInvoiceLines)
      .where(sql`${purchaseInvoiceLines.purchaseOrderLineId} IS NOT NULL`)
      .groupBy(purchaseInvoiceLines.purchaseOrderLineId)
      .as('invoiced_agg');

    return await this.db
      .select({
        purchaseOrderId: purchaseOrders.purchaseOrderId,
        orderNumber: purchaseOrders.orderNumber,
        purchaseOrderName: purchaseOrders.name,
        vendorName: coreSuppliers.name,
        stateCode: purchaseOrders.stateCode,
        vendorId: purchaseOrders.vendorId,
        deliveryLocationId: purchaseOrders.deliveryLocationId,
        locationName: locations.name,
        currencyCode: purchaseOrders.currencyCode,
        purchaseOrderLineId: purchaseOrderLineItems.purchaseOrderLineId,
        lineNumber: purchaseOrderLineItems.lineNumber,
        productId: purchaseOrderLineItems.productId,
        productNumber: products.productNumber,
        productDescription: purchaseOrderLineItems.productDescription,
        quantity: purchaseOrderLineItems.quantity,
        pricePerUnit: purchaseOrderLineItems.pricePerUnit,
        quantityReceived: purchaseOrderLineItems.quantityReceived,
        quantityInvoiced:
          sql<string>`COALESCE(${invoicedSubquery.totalInvoiced}, '0')`.as(
            'quantity_invoiced',
          ),
      })
      .from(purchaseOrderLineItems)
      .innerJoin(
        purchaseOrders,
        eq(
          purchaseOrderLineItems.purchaseOrderId,
          purchaseOrders.purchaseOrderId,
        ),
      )
      .leftJoin(
        coreSuppliers,
        eq(purchaseOrders.vendorId, coreSuppliers.vendorId),
      )
      .leftJoin(
        products,
        eq(purchaseOrderLineItems.productId, products.productId),
      )
      .leftJoin(
        invoicedSubquery,
        eq(
          purchaseOrderLineItems.purchaseOrderLineId,
          invoicedSubquery.purchaseOrderLineId,
        ),
      )
      .leftJoin(
        locations,
        eq(purchaseOrders.deliveryLocationId, locations.locationId),
      )
      .where(and(...conditions))
      .orderBy(
        desc(purchaseOrders.createdOn),
        purchaseOrderLineItems.lineNumber,
      );
  }

  async findReturnableLines(productId: string) {
    if (!productId) {
      throw new BadRequestException(
        'productId is required to find returnable lines',
      );
    }

    return await this.db
      .select({
        purchaseOrderId: purchaseOrders.purchaseOrderId,
        orderNumber: purchaseOrders.orderNumber,
        purchaseOrderName: purchaseOrders.name,
        vendorName: coreSuppliers.name,
        stateCode: purchaseOrders.stateCode,
        vendorId: purchaseOrders.vendorId,
        currencyCode: purchaseOrders.currencyCode,
        purchaseOrderLineId: purchaseOrderLineItems.purchaseOrderLineId,
        lineNumber: purchaseOrderLineItems.lineNumber,
        productDescription: purchaseOrderLineItems.productDescription,
        quantity: purchaseOrderLineItems.quantity,
        pricePerUnit: purchaseOrderLineItems.pricePerUnit,
        quantityReceived: purchaseOrderLineItems.quantityReceived,
      })
      .from(purchaseOrderLineItems)
      .innerJoin(
        purchaseOrders,
        eq(
          purchaseOrderLineItems.purchaseOrderId,
          purchaseOrders.purchaseOrderId,
        ),
      )
      .leftJoin(
        coreSuppliers,
        eq(purchaseOrders.vendorId, coreSuppliers.vendorId),
      )
      .where(
        and(
          eq(purchaseOrderLineItems.productId, productId),
          inArray(purchaseOrders.stateCode, [
            PURCHASE_ORDER_STATE.RECEIVED,
            PURCHASE_ORDER_STATE.PARTIALLY_RECEIVED,
            PURCHASE_ORDER_STATE.INVOICED,
          ]),
          sql`${purchaseOrderLineItems.quantityReceived} > 0`,
        ),
      );
  }

  private async updateStateInternal(
    purchaseOrderId: string,
    newState: string,
    actor: string,
    tx?: DrizzleDB,
  ) {
    const VALID_STATES = getValidStates(PURCHASE_ORDER_TRANSITIONS);
    if (!VALID_STATES.includes(newState)) {
      throw new BadRequestException(`Invalid PO state: '${newState}'`);
    }

    const db = tx || this.db;
    const [existing] = await db
      .select({
        stateCode: purchaseOrders.stateCode,
        orderNumber: purchaseOrders.orderNumber,
      })
      .from(purchaseOrders)
      .where(eq(purchaseOrders.purchaseOrderId, purchaseOrderId))
      .limit(1);

    if (!existing) {
      throw new NotFoundException(
        `Purchase Order ${purchaseOrderId} not found`,
      );
    }

    const allowed = PURCHASE_ORDER_TRANSITIONS[existing.stateCode];
    if (!allowed || !allowed.includes(newState)) {
      throw new BadRequestException(
        `Cannot transition PO from '${existing.stateCode}' to '${newState}'. Allowed transitions: ${allowed?.join(', ') || 'none'}`,
      );
    }

    const [updated] = await db
      .update(purchaseOrders)
      .set({
        stateCode: newState as any,
        modifiedOn: new Date(),
      })
      .where(eq(purchaseOrders.purchaseOrderId, purchaseOrderId))
      .returning();

    await emitEvent(db as any, {
      aggregateType: AggregateType.PURCHASE_ORDER,
      aggregateId: purchaseOrderId,
      eventType: 'status_changed',
      payload: {
        entity: 'purchase_order',
        entityId: purchaseOrderId,
        orderNumber: existing.orderNumber,
        from: existing.stateCode,
        to: newState,
      },
      actor,
    });

    return updated;
  }
}
